export enum ModelType {
  FLASH = 'gemini-3-flash-preview',
  PRO = 'gemini-3-pro-preview',
}

export enum AnalysisMode {
  SINGLE = 'SINGLE',
  BULK = 'BULK',
}

export interface AnalysisCriteria {
  focusArea: string;
  strictness: 'low' | 'medium' | 'high';
  customInstructions: string;
}

export interface AnalysisResult {
  url: string;
  seoScore: number;
  eeatScore: number;
  llmOptimizationScore: number;
  isYMYL: boolean;
  summary: string;
  strengths: string[];
  weaknesses: string[];
  recommendations: Recommendation[];
  keywordGaps: string[];
  sentiment: string;
  timestamp: number;
}

export interface Recommendation {
  category: 'SEO' | 'EEAT' | 'Content' | 'Technical';
  priority: 'High' | 'Medium' | 'Low';
  action: string;
  description: string;
}

export interface ScrapingResult {
  url: string;
  content: string;
  title: string;
  success: boolean;
  error?: string;
}

export interface AppState {
  mode: AnalysisMode;
  urls: string[];
  results: AnalysisResult[];
  isAnalyzing: boolean;
  currentProgress: number; // 0-100
  selectedModel: ModelType;
  criteria: AnalysisCriteria;
}

import { ScrapingResult } from '../types';

/**
 * Attempts to scrape the content of a URL using a CORS proxy.
 * Note: Client-side scraping is limited. This uses a public proxy which may be rate-limited or blocked by some sites.
 */
export const scrapeUrl = async (url: string): Promise<ScrapingResult> => {
  try {
    // Validate URL
    if (!url.startsWith('http')) {
      return {
        url,
        content: '',
        title: '',
        success: false,
        error: 'Invalid URL. Must start with http:// or https://'
      };
    }

    // Using allorigins as a CORS proxy
    const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`;

    const response = await fetch(proxyUrl);

    if (!response.ok) {
      throw new Error(`Failed to fetch via proxy: ${response.statusText}`);
    }

    const html = await response.text();

    // Basic parsing to extract title and body text to reduce token usage
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    // Remove scripts and styles
    const scripts = doc.querySelectorAll('script, style, noscript, iframe, svg');
    scripts.forEach(script => script.remove());

    const title = doc.title || url;
    const bodyText = doc.body.innerText || doc.body.textContent || '';

    // Clean up whitespace
    const cleanedContent = bodyText.replace(/\s+/g, ' ').trim().slice(0, 50000); // Limit context window usage

    if (cleanedContent.length < 50) {
       throw new Error("Content too short or blocked by bot protection.");
    }

    return {
      url,
      content: cleanedContent,
      title,
      success: true
    };

  } catch (error: any) {
    console.error("Scraping error:", error);
    return {
      url,
      content: '',
      title: '',
      success: false,
      error: error.message || 'Unknown scraping error'
    };
  }
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, Recommendation } from "../types";

// Schema for the structured output
const analysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER, description: "Score from 0-100 for SEO optimization." },
    eeatScore: { type: Type.NUMBER, description: "Score from 0-100 for E-E-A-T compliance." },
    llmOptimizationScore: { type: Type.NUMBER, description: "Score from 0-100 for how well LLMs can understand this content." },
    isYMYL: { type: Type.BOOLEAN, description: "Whether the content falls under Your Money or Your Life category." },
    summary: { type: Type.STRING, description: "A concise summary of the content." },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key strengths."
    },
    weaknesses: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key weaknesses."
    },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING, enum: ['SEO', 'EEAT', 'Content', 'Technical'] },
          priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
          action: { type: Type.STRING },
          description: { type: Type.STRING }
        },
        required: ['category', 'priority', 'action', 'description']
      }
    },
    keywordGaps: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Potential missing keywords or topics."
    },
    sentiment: { type: Type.STRING, description: "Overall tone of the content." }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations']
};

export const analyzeContent = async (
  url: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType
): Promise<AnalysisResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY not found in environment variables");
  }

  const ai = new GoogleGenAI({ apiKey });

  const prompt = `
    Analyze the following web page content located at: ${url}

    Content Preview:
    ${content.slice(0, 30000)}... (truncated if too long)

    Analysis Criteria:
    - Focus Area: ${criteria.focusArea || 'General SEO & Quality'}
    - Strictness Level: ${criteria.strictness}
    - Additional Instructions: ${criteria.customInstructions}

    Tasks:
    1. Assess SEO Optimization (Keywords, structure, readability).
    2. Evaluate E-E-A-T (Experience, Expertise, Authoritativeness, Trustworthiness).
    3. Determine if YMYL (Your Money Your Life) applies and if standards are met.
    4. Analyze for LLM/AI Answer Engine Optimization (Is the data structured? Is it clear for an AI to cite?).
    5. Provide specific, actionable recommendations.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: 0.3, // Lower temperature for more analytical results
      },
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from Gemini");

    const parsedData = JSON.parse(jsonText);

    return {
      url,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    // Return a fallback error result structure
    return {
      url,
      timestamp: Date.now(),
      seoScore: 0,
      eeatScore: 0,
      llmOptimizationScore: 0,
      isYMYL: false,
      summary: "Analysis Failed",
      strengths: [],
      weaknesses: ["Analysis failed due to API error or content limits."],
      recommendations: [{ category: 'Technical', priority: 'High', action: 'Retry Analysis', description: 'The AI model could not process this request.' }],
      keywordGaps: [],
      sentiment: "Neutral"
    };
  }
};

import React from 'react';
