export default CriteriaSettings;

import React, { useState } from 'react';
import { AnalysisResult, Recommendation } from '../types';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Tooltip } from 'recharts';

interface ResultCardProps {
  result: AnalysisResult;
}

const ScoreGauge: React.FC<{ label: string; score: number; color: string }> = ({ label, score, color }) => (
  <div className="flex flex-col items-center">
    <div className={`relative w-20 h-20 flex items-center justify-center rounded-full border-4 ${color} bg-slate-800`}>
      <span className="text-xl font-bold text-slate-100">{score}</span>
    </div>
    <span className="mt-2 text-xs text-slate-400 uppercase tracking-wider">{label}</span>
  </div>
);

const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'recommendations' | 'details'>('overview');

  const chartData = [
    { subject: 'SEO', A: result.seoScore, fullMark: 100 },
    { subject: 'EEAT', A: result.eeatScore, fullMark: 100 },
    { subject: 'AI/LLM', A: result.llmOptimizationScore, fullMark: 100 },
    { subject: 'Content', A: Math.round((result.seoScore + result.eeatScore) / 2), fullMark: 100 },
    { subject: 'Trust', A: result.isYMYL ? result.eeatScore : 100, fullMark: 100 },
  ];

  const getPriorityColor = (p: string) => {
    switch (p) {
      case 'High': return 'text-red-400 border-red-900 bg-red-900/20';
      case 'Medium': return 'text-amber-400 border-amber-900 bg-amber-900/20';
      case 'Low': return 'text-blue-400 border-blue-900 bg-blue-900/20';
      default: return 'text-slate-400 border-slate-800';
    }
  };

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden shadow-xl mb-8">
      {/* Header */}
      <div className="p-6 border-b border-slate-700 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-white truncate max-w-2xl" title={result.url}>{result.url}</h2>
          <div className="flex items-center gap-3 mt-1">
            <span className="text-xs text-slate-400">{new Date(result.timestamp).toLocaleString()}</span>
            {result.isYMYL && <span className="px-2 py-0.5 rounded text-[10px] bg-purple-900 text-purple-200 border border-purple-700">YMYL DETECTED</span>}
          </div>
        </div>
        <div className="flex gap-2">
            {['overview', 'recommendations', 'details'].map((tab) => (
                <button
                    key={tab}
                    onClick={() => setActiveTab(tab as any)}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                        activeTab === tab 
                        ? 'bg-blue-600 text-white' 
                        : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
                    }`}
                >
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                </button>
            ))}
        </div>
      </div>

      {/* Content */}
      <div className="p-6">
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              <div className="flex justify-around bg-slate-900/50 p-6 rounded-xl border border-slate-700/50">
                <ScoreGauge 
                    label="SEO Score" 
                    score={result.seoScore} 
                    color={result.seoScore > 80 ? 'border-green-500' : result.seoScore > 50 ? 'border-amber-500' : 'border-red-500'} 
                />
                <ScoreGauge 
                    label="EEAT Score" 
                    score={result.eeatScore} 
                    color={result.eeatScore > 80 ? 'border-green-500' : result.eeatScore > 50 ? 'border-amber-500' : 'border-red-500'} 
                />
                <ScoreGauge 
                    label="AI Ready" 
                    score={result.llmOptimizationScore} 
                    color={result.llmOptimizationScore > 80 ? 'border-blue-500' : result.llmOptimizationScore > 50 ? 'border-amber-500' : 'border-red-500'} 
                />
              </div>

              <div>
                <h3 className="text-lg font-semibold text-slate-200 mb-2">Executive Summary</h3>
                <p className="text-slate-400 leading-relaxed">{result.summary}</p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="bg-slate-900/50 p-4 rounded-lg border border-green-900/30">
                  <h4 className="font-medium text-green-400 mb-2 flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                    Top Strengths
                  </h4>
                  <ul className="space-y-1">
                    {result.strengths.slice(0, 4).map((s, i) => (
                      <li key={i} className="text-sm text-slate-300">• {s}</li>
                    ))}
                  </ul>
                </div>
                <div className="bg-slate-900/50 p-4 rounded-lg border border-red-900/30">
                  <h4 className="font-medium text-red-400 mb-2 flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    Critical Weaknesses
                  </h4>
                  <ul className="space-y-1">
                    {result.weaknesses.slice(0, 4).map((w, i) => (
                      <li key={i} className="text-sm text-slate-300">• {w}</li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>

            <div className="h-[300px] flex items-center justify-center bg-slate-900/30 rounded-xl border border-slate-700/50">
              <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="70%" data={chartData}>
                  <PolarGrid stroke="#334155" />
                  <PolarAngleAxis dataKey="subject" tick={{ fill: '#94a3b8', fontSize: 12 }} />
                  <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
                  <Radar name="Score" dataKey="A" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.3} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#f8fafc' }}
                  />
                </RadarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {activeTab === 'recommendations' && (
          <div className="space-y-4">
            {result.recommendations.map((rec, idx) => (
              <div key={idx} className="bg-slate-900/50 rounded-lg p-4 border border-slate-700 flex flex-col md:flex-row md:items-start gap-4 transition hover:bg-slate-900/80">
                <div className={`shrink-0 px-3 py-1 rounded text-xs font-bold border uppercase ${getPriorityColor(rec.priority)}`}>
                  {rec.priority}
                </div>
                <div className="flex-grow">
                  <div className="flex justify-between items-start">
                    <h4 className="text-slate-200 font-semibold">{rec.action}</h4>
                    <span className="text-xs text-slate-500 bg-slate-800 px-2 py-1 rounded">{rec.category}</span>
                  </div>
                  <p className="text-slate-400 text-sm mt-1">{rec.description}</p>
                </div>
              </div>
            ))}
             {result.recommendations.length === 0 && (
                <div className="text-center text-slate-500 py-12">No specific recommendations generated.</div>
             )}
          </div>
        )}

        {activeTab === 'details' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
               <h3 className="text-lg font-semibold text-slate-200 mb-4">Keyword Opportunities</h3>
               <div className="flex flex-wrap gap-2">
                 {result.keywordGaps.map((k, i) => (
                   <span key={i} className="px-3 py-1 bg-slate-700 text-slate-300 rounded-full text-sm border border-slate-600">
                     {k}
                   </span>
                 ))}
                 {result.keywordGaps.length === 0 && <span className="text-slate-500 text-sm">No specific gaps identified.</span>}
               </div>
            </div>
             <div>
               <h3 className="text-lg font-semibold text-slate-200 mb-4">Sentiment & Tone</h3>
               <p className="text-slate-300 bg-slate-900/50 p-3 rounded border border-slate-700">{result.sentiment}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ResultCard;

import React, { useState, useCallback } from 'react';
import { AnalysisMode, AppState, ModelType, AnalysisCriteria, AnalysisResult } from './types';
import { scrapeUrl } from './services/scraperService';
import { analyzeContent } from './services/geminiService';
import CriteriaSettings from './components/CriteriaSettings';
import ResultCard from './components/ResultCard';

const INITIAL_CRITERIA: AnalysisCriteria = {
  focusArea: 'General SEO',
  strictness: 'medium',
  customInstructions: ''
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    mode: AnalysisMode.SINGLE,
    urls: [],
    results: [],
    isAnalyzing: false,
    currentProgress: 0,
    selectedModel: ModelType.FLASH,
    criteria: INITIAL_CRITERIA
  });

  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');

  const handleStartAnalysis = useCallback(async () => {
    let urlsToProcess: string[] = [];

    if (state.mode === AnalysisMode.SINGLE) {
      if (!inputUrl) return;
      urlsToProcess = [inputUrl];
    } else {
      if (!bulkInput) return;
      urlsToProcess = bulkInput.split('\n').map(u => u.trim()).filter(u => u.length > 0);
    }

    if (urlsToProcess.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], // Clear previous results
      currentProgress: 0 
    }));

    const results: AnalysisResult[] = [];
    const total = urlsToProcess.length;

    for (let i = 0; i < total; i++) {
      const url = urlsToProcess[i];

      // Step 1: Scrape
      const scrapeResult = await scrapeUrl(url);

      let analysisResult: AnalysisResult;

      if (scrapeResult.success && scrapeResult.content) {
         // Step 2: Analyze with Gemini
         analysisResult = await analyzeContent(url, scrapeResult.content, state.criteria, state.selectedModel);
      } else {
         // Handle failure gracefully
         analysisResult = {
             url,
             timestamp: Date.now(),
             seoScore: 0,
             eeatScore: 0,
             llmOptimizationScore: 0,
             isYMYL: false,
             summary: "Scraping Failed",
             strengths: [],
             weaknesses: [scrapeResult.error || "Could not access page content"],
             recommendations: [{ category: 'Technical', priority: 'High', action: 'Check URL Accessibility', description: 'The page could not be read. It might be blocking bots.' }],
             keywordGaps: [],
             sentiment: "N/A"
         };
      }

      results.push(analysisResult);

      // Update progress
      setState(prev => ({
        ...prev,
        results: [...results],
        currentProgress: Math.round(((i + 1) / total) * 100)
      }));
    }

    setState(prev => ({ ...prev, isAnalyzing: false }));

  }, [state.mode, state.criteria, state.selectedModel, inputUrl, bulkInput]);

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200">
      {/* Navbar */}
      <nav className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <span className="font-bold text-xl tracking-tight text-white">ContentAudit AI</span>
            </div>

            <div className="flex items-center gap-4">
               <select 
                 value={state.selectedModel}
                 onChange={(e) => setState(prev => ({ ...prev, selectedModel: e.target.value as ModelType }))}
                 className="bg-slate-800 text-sm border border-slate-700 text-slate-300 rounded px-3 py-1.5 focus:ring-2 focus:ring-blue-500 outline-none"
               >
                 <option value={ModelType.FLASH}>Gemini 2.5 Flash (Fast)</option>
                 <option value={ModelType.PRO}>Gemini 3 Pro (Deep Analysis)</option>
               </select>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Column: Controls */}
          <div className="lg:col-span-4 space-y-6">

            {/* Input Section */}
            <div className="bg-slate-800 p-6 rounded-lg border border-slate-700 shadow-lg">
              <div className="flex gap-4 mb-6 border-b border-slate-700 pb-2">
                <button
                  onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.SINGLE }))}
                  className={`pb-2 text-sm font-medium transition-colors relative ${state.mode === AnalysisMode.SINGLE ? 'text-blue-400' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Single URL
                  {state.mode === AnalysisMode.SINGLE && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-400"></span>}
                </button>
                <button
                   onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.BULK }))}
                   className={`pb-2 text-sm font-medium transition-colors relative ${state.mode === AnalysisMode.BULK ? 'text-blue-400' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Bulk Mode
                  {state.mode === AnalysisMode.BULK && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-400"></span>}
                </button>
              </div>

              {state.mode === AnalysisMode.SINGLE ? (
                <div>
                  <label className="block text-sm font-medium text-slate-400 mb-2">Target URL</label>
                  <input
                    type="text"
                    placeholder="https://example.com/blog/article"
                    value={inputUrl}
                    onChange={(e) => setInputUrl(e.target.value)}
                    className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-slate-200 focus:ring-2 focus:ring-blue-500 outline-none placeholder-slate-600"
                  />
                </div>
              ) : (
                <div>
                   <label className="block text-sm font-medium text-slate-400 mb-2">Target URLs (One per line)</label>
                   <textarea
                     placeholder="https://site1.com&#10;https://site2.com"
                     value={bulkInput}
                     onChange={(e) => setBulkInput(e.target.value)}
                     className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-slate-200 h-32 focus:ring-2 focus:ring-blue-500 outline-none placeholder-slate-600 resize-none"
                   />
                </div>
              )}

              <button
                onClick={handleStartAnalysis}
                disabled={state.isAnalyzing || (state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput)}
                className={`mt-6 w-full py-3 rounded font-semibold text-white transition-all shadow-lg ${
                  state.isAnalyzing 
                    ? 'bg-blue-600/50 cursor-not-allowed' 
                    : 'bg-blue-600 hover:bg-blue-500 hover:shadow-blue-500/20'
                }`}
              >
                {state.isAnalyzing ? (
                  <span className="flex items-center justify-center gap-2">
                    <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Analyzing... {state.currentProgress}%
                  </span>
                ) : (
                  'Start Audit'
                )}
              </button>
            </div>

            {/* Criteria Panel */}
            <CriteriaSettings 
              criteria={state.criteria} 
              onChange={(newCriteria) => setState(prev => ({ ...prev, criteria: newCriteria }))} 
            />

            {/* Quick Tips */}
            <div className="bg-slate-800/50 p-4 rounded-lg border border-slate-700">
              <h4 className="text-sm font-semibold text-slate-300 mb-2">Did you know?</h4>
              <p className="text-xs text-slate-500">
                Gemini 2.5 Flash is significantly faster for quick checks, while Gemini 3 Pro is better at understanding complex nuances in medical or financial content (YMYL).
              </p>
            </div>

          </div>

          {/* Right Column: Results */}
          <div className="lg:col-span-8">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-500 min-h-[400px] border-2 border-dashed border-slate-800 rounded-xl bg-slate-900/30">
                 <svg className="w-16 h-16 mb-4 text-slate-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                 <p className="text-lg">Ready to analyze content</p>
                 <p className="text-sm">Enter a URL to begin the audit.</p>
               </div>
             ) : (
               <div className="space-y-6">
                 {state.results.map((result, index) => (
                   <ResultCard key={`${result.url}-${index}`} result={result} />
                 ))}
               </div>
             )}
          </div>

        </div>
      </main>
    </div>
  );
};

