          </div>
        )}

        {activeTab === 'recommendations' && (
          <div className="space-y-4">
            {result.recommendations.map((rec, idx) => (
              <div key={idx} className="bg-slate-900/50 rounded-lg p-4 border border-slate-700 flex flex-col md:flex-row md:items-start gap-4 transition hover:bg-slate-900/80">
