import React, { useRef } from 'react';
import { AdminSettings, InstructionFile } from '../types';

interface AdminPanelProps {
  settings: AdminSettings;
  onSave: (settings: AdminSettings) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, onSave, onClose }) => {
  const [localSettings, setLocalSettings] = React.useState<AdminSettings>(settings);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;

    Array.from(files).forEach((file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        const newFile: InstructionFile = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          size: file.size
        };
        setLocalSettings(prev => ({
          ...prev,
          instructionFiles: [...prev.instructionFiles, newFile]
        }));
      };
      reader.readAsText(file);
    });

    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeFile = (id: string) => {
    setLocalSettings(prev => ({
      ...prev,
      instructionFiles: prev.instructionFiles.filter(f => f.id !== id)
    }));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/90 backdrop-blur-sm p-4 overflow-y-auto">
      <div className="bg-slate-800 w-full max-w-4xl rounded-xl border border-slate-700 shadow-2xl flex flex-col max-h-[90vh]">

