interface AdminPanelProps {
  settings: AdminSettings;
  onSave: (settings: AdminSettings) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, onSave, onClose }) => {
  const [localSettings, setLocalSettings] = React.useState<AdminSettings>(settings);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const configInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;

    Array.from(files).forEach((file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        const newFile: InstructionFile = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          size: file.size
        };
        setLocalSettings(prev => ({
          ...prev,
          instructionFiles: [...prev.instructionFiles, newFile]
        }));
      };
      reader.readAsText(file);
    });

    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleConfigImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const content = e.target?.result as string;
            const parsed = JSON.parse(content) as AdminSettings;
            if (parsed.promptTemplate && Array.isArray(parsed.instructionFiles)) {
                setLocalSettings(parsed);
                alert("Configuration imported successfully!");
            } else {
                throw new Error("Invalid format");
            }
        } catch (err) {
            alert("Failed to import configuration. Invalid file format.");
        }
    };
    reader.readAsText(file);
    if (configInputRef.current) configInputRef.current.value = '';
  };

  const removeFile = (id: string) => {
