import { AdminSettings } from "../types";

const STORAGE_KEY = 'content_audit_admin_settings';

// SHA-256 hash for "Netpeak2026"
const PASSWORD_HASH = '3a7bd3e2360a3d29eea436fcfb7e44c735d117c42d1c1835420b6b9942dd4f1b';

export const verifyPassword = async (input: string): Promise<boolean> => {
  try {
    const encoder = new TextEncoder();
    const data = encoder.encode(input);
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    return hashHex === PASSWORD_HASH;
  } catch (e) {
    console.error("Crypto verification failed", e);
    return false;
  }
};

export const saveAdminSettings = (settings: AdminSettings) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch (e) {
    console.error("Failed to save settings to localStorage", e);
    alert("Warning: Settings could not be saved to local storage (quota might be exceeded).");
  }
};

export const loadAdminSettings = (): AdminSettings | null => {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored ? JSON.parse(stored) : null;
  } catch (e) {
    console.error("Failed to load settings", e);
    return null;
  }
};

export const exportSettingsToFile = (settings: AdminSettings) => {
  const blob = new Blob([JSON.stringify(settings, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `content_audit_config_${new Date().toISOString().slice(0, 10)}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, AdminSettings } from "../types";

// Schema for the structured output
const analysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER, description: "Score from 0-100 for SEO optimization." },
    eeatScore: { type: Type.NUMBER, description: "Score from 0-100 for E-E-A-T compliance." },
    llmOptimizationScore: { type: Type.NUMBER, description: "Score from 0-100 for how well LLMs can understand this content." },
    isYMYL: { type: Type.BOOLEAN, description: "Whether the content falls under Your Money or Your Life category." },
    summary: { type: Type.STRING, description: "A concise summary of the content." },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key strengths."
    },
    weaknesses: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key weaknesses."
    },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING, enum: ['SEO', 'EEAT', 'Content', 'Technical'] },
          priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
          action: { type: Type.STRING },
          description: { type: Type.STRING }
        },
        required: ['category', 'priority', 'action', 'description']
      }
    },
    keywordGaps: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Potential missing keywords or topics."
    },
    sentiment: { type: Type.STRING, description: "Overall tone of the content." }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations']
};

export const analyzeContent = async (
  url: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY not found in environment variables");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Prepare Context from Uploaded Files
  const knowledgeBaseContext = adminSettings.instructionFiles.length > 0 
    ? `\n\nREFERENCE MATERIALS & INSTRUCTIONS:\n${adminSettings.instructionFiles.map(f => `--- FILE: ${f.name} ---\n${f.content}\n--- END FILE ---`).join('\n')}`
    : "";

  // Process Template Replacements
  let finalPrompt = adminSettings.promptTemplate;

  // Safe replacement helper
  const replace = (key: string, value: string) => {
    finalPrompt = finalPrompt.replace(new RegExp(key, 'g'), value);
  };

  replace('{{url}}', url);
  replace('{{content}}', content.slice(0, 40000)); // Increased limit slightly
  replace('{{focusArea}}', criteria.focusArea || 'General SEO & Quality');
  replace('{{strictness}}', criteria.strictness);
  replace('{{customInstructions}}', criteria.customInstructions || 'None');

  // Append knowledge base
  finalPrompt += knowledgeBaseContext;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: 0.3, 
      },
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from Gemini");

    const parsedData = JSON.parse(jsonText);

    return {
      url,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    return {
      url,
      timestamp: Date.now(),
      seoScore: 0,
      eeatScore: 0,
      llmOptimizationScore: 0,
      isYMYL: false,
      summary: "Analysis Failed",
      strengths: [],
      weaknesses: [],
      recommendations: [],
      keywordGaps: [],
      sentiment: "Neutral",
      error: error.message || "An unexpected error occurred during AI analysis."
    };
  }
};

import { ScrapingResult } from '../types';

/**
 * Attempts to scrape the content of a URL using a CORS proxy.
 * Note: Client-side scraping is limited. This uses a public proxy which may be rate-limited or blocked by some sites.
 */
export const scrapeUrl = async (url: string): Promise<ScrapingResult> => {
  try {
    // Validate URL
    if (!url.startsWith('http')) {
      return {
        url,
        content: '',
        title: '',
        success: false,
        error: 'Invalid URL. Must start with http:// or https://'
      };
    }

    // Try primary proxy (allorigins)
    // Using 'get' endpoint instead of 'raw' to sometimes bypass header issues, though it returns JSON.
    const proxyUrl = `https://api.allorigins.win/get?url=${encodeURIComponent(url)}`;

    const response = await fetch(proxyUrl);

    if (!response.ok) {
      throw new Error(`Proxy error: ${response.statusText}`);
    }

    const data = await response.json();
    const html = data.contents;

    if (!html) {
       throw new Error("No content returned from proxy.");
    }

    // Basic parsing to extract title and body text to reduce token usage
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    // Remove scripts and styles
    const scripts = doc.querySelectorAll('script, style, noscript, iframe, svg, link');
    scripts.forEach(script => script.remove());

    const title = doc.title || url;

    // Attempt to get text from specific main content areas first, falling back to body
    const mainContent = doc.querySelector('main') || doc.querySelector('article') || doc.body;
    const bodyText = mainContent.innerText || mainContent.textContent || '';

    // Clean up whitespace
    const cleanedContent = bodyText.replace(/\s+/g, ' ').trim().slice(0, 50000); 

    if (cleanedContent.length < 50) {
       throw new Error("Page content is empty or protected by anti-bot measures. The app cannot read this page directly.");
    }

    return {
      url,
      content: cleanedContent,
      title,
      success: true
    };

  } catch (error: any) {
    console.error("Scraping error:", error);
    return {
      url,
      content: '',
      title: '',
      success: false,
      error: error.message || 'Failed to access page content. Please check if the URL allows external access.'
    };
  }
};

