    criteria: INITIAL_CRITERIA,
    showAdmin: false,
    isAdminAuthenticated: false,
    adminSettings: {
        promptTemplate: DEFAULT_PROMPT_TEMPLATE,
        instructionFiles: []
    }
  });

  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  // Load settings on mount
  useEffect(() => {
    const savedSettings = loadAdminSettings();
    if (savedSettings) {
      setState(prev => ({ ...prev, adminSettings: savedSettings }));
    }
  }, []);

  const handleAdminClick = () => {
    if (state.isAdminAuthenticated) {
      setState(prev => ({ ...prev, showAdmin: true }));
    } else {
      setShowPasswordModal(true);
    }
  };

  const handleAuthenticated = () => {
    setState(prev => ({ ...prev, isAdminAuthenticated: true, showAdmin: true }));
    setShowPasswordModal(false);
  };

  const handleSaveSettings = (newSettings: AdminSettings) => {
    setState(prev => ({ ...prev, adminSettings: newSettings }));
    saveAdminSettings(newSettings);
  };

  const handleStartAnalysis = useCallback(async () => {
    let urlsToProcess: string[] = [];

    if (state.mode === AnalysisMode.SINGLE) {
      if (!inputUrl) return;
      urlsToProcess = [inputUrl];
    } else {
      if (!bulkInput) return;
      urlsToProcess = bulkInput.split('\n').map(u => u.trim()).filter(u => u.length > 0);
    }

    if (urlsToProcess.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], // Clear previous results
      currentProgress: 0 
    }));

    const results: AnalysisResult[] = [];
    const total = urlsToProcess.length;

    for (let i = 0; i < total; i++) {
      const url = urlsToProcess[i];

      // Step 1: Scrape
      const scrapeResult = await scrapeUrl(url);

      let analysisResult: AnalysisResult;

      if (scrapeResult.success && scrapeResult.content) {
         // Step 2: Analyze with Gemini using Admin Settings
         analysisResult = await analyzeContent(
            url, 
            scrapeResult.content, 
            state.criteria, 
            state.selectedModel, 
            state.adminSettings
         );
      } else {
         // Handle failure gracefully with proper Error Result
         analysisResult = {
             url,
             timestamp: Date.now(),
             seoScore: 0,
             eeatScore: 0,
             llmOptimizationScore: 0,
             isYMYL: false,
             summary: "Analysis Failed",
             strengths: [],
             weaknesses: [],
             recommendations: [],
             keywordGaps: [],
             sentiment: "N/A",
             error: scrapeResult.error || "Unknown Error: Could not access content"
         };
      }

      results.push(analysisResult);

      // Update progress
      setState(prev => ({
        ...prev,
        results: [...results],
        currentProgress: Math.round(((i + 1) / total) * 100)
      }));
    }

    setState(prev => ({ ...prev, isAnalyzing: false }));

  }, [state.mode, state.criteria, state.selectedModel, state.adminSettings, inputUrl, bulkInput]);

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 flex flex-col">
      {/* Navbar */}
      <nav className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16 gap-4">
            <div className="flex items-center gap-3 shrink-0">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <span className="font-bold text-lg md:text-xl tracking-tight text-white hidden sm:block">ContentAudit AI</span>
              <span className="font-bold text-lg tracking-tight text-white sm:hidden">ContentAudit</span>
            </div>

            <div className="flex items-center gap-2 md:gap-4 overflow-x-auto scrollbar-hide">
               <select 
                 value={state.selectedModel}
                 onChange={(e) => setState(prev => ({ ...prev, selectedModel: e.target.value as ModelType }))}
                 className="bg-slate-800 text-xs md:text-sm border border-slate-700 text-slate-300 rounded px-2 py-1.5 md:px-3 focus:ring-2 focus:ring-blue-500 outline-none max-w-[120px] md:max-w-none"
               >
                 <option value={ModelType.FLASH}>Gemini 2.5 Flash</option>
                 <option value={ModelType.PRO}>Gemini 3 Pro</option>
               </select>

               <button
                  onClick={handleAdminClick}
                  className="bg-slate-800 hover:bg-slate-700 text-slate-300 p-2 rounded border border-slate-700 transition-colors"
                  title="Admin Settings"
               >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
               </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex-grow">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Column: Controls (Full width on mobile, 4 cols on desktop) */}
          <div className="col-span-1 lg:col-span-4 space-y-6">

            {/* Input Section */}
            <div className="bg-slate-800 p-6 rounded-lg border border-slate-700 shadow-lg">
              <div className="flex gap-4 mb-6 border-b border-slate-700 pb-2 overflow-x-auto scrollbar-hide">
                <button
                  onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.SINGLE }))}
                  className={`pb-2 text-sm font-medium transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.SINGLE ? 'text-blue-400' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Single URL
                  {state.mode === AnalysisMode.SINGLE && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-400"></span>}
                </button>
                <button
                   onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.BULK }))}
                   className={`pb-2 text-sm font-medium transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.BULK ? 'text-blue-400' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Bulk Mode
                  {state.mode === AnalysisMode.BULK && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-400"></span>}
                </button>
              </div>

              {state.mode === AnalysisMode.SINGLE ? (
                <div>
                  <label className="block text-sm font-medium text-slate-400 mb-2">Target URL</label>
                  <input
                    type="text"
                    placeholder="https://example.com/blog/article"
                    value={inputUrl}
                    onChange={(e) => setInputUrl(e.target.value)}
                    className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-slate-200 focus:ring-2 focus:ring-blue-500 outline-none placeholder-slate-600 text-sm"
                  />
                </div>
              ) : (
                <div>
                   <label className="block text-sm font-medium text-slate-400 mb-2">Target URLs (One per line)</label>
                   <textarea
                     placeholder="https://site1.com&#10;https://site2.com"
                     value={bulkInput}
                     onChange={(e) => setBulkInput(e.target.value)}
                     className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-slate-200 h-32 focus:ring-2 focus:ring-blue-500 outline-none placeholder-slate-600 resize-none text-sm"
                   />
                </div>
              )}

              <button
                onClick={handleStartAnalysis}
                disabled={state.isAnalyzing || (state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput)}
                className={`mt-6 w-full py-3 rounded font-semibold text-white transition-all shadow-lg ${
                  state.isAnalyzing 
                    ? 'bg-blue-600/50 cursor-not-allowed' 
                    : 'bg-blue-600 hover:bg-blue-500 hover:shadow-blue-500/20'
                }`}
              >
                {state.isAnalyzing ? (
                  <span className="flex items-center justify-center gap-2">
                    <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Analyzing... {state.currentProgress}%
                  </span>
                ) : (
                  'Start Audit'
                )}
              </button>
            </div>

            {/* Criteria Panel */}
            <CriteriaSettings 
              criteria={state.criteria} 
              onChange={(newCriteria) => setState(prev => ({ ...prev, criteria: newCriteria }))} 
            />

            {/* Quick Tips */}
            <div className="bg-slate-800/50 p-4 rounded-lg border border-slate-700 hidden sm:block">
              <h4 className="text-sm font-semibold text-slate-300 mb-2">Did you know?</h4>
              <p className="text-xs text-slate-500">
                Gemini 2.5 Flash is significantly faster for quick checks, while Gemini 3 Pro is better at understanding complex nuances in medical or financial content (YMYL).
              </p>
            </div>

          </div>

          {/* Right Column: Results (Full width on mobile, 8 cols on desktop) */}
          <div className="col-span-1 lg:col-span-8">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-500 min-h-[300px] md:min-h-[400px] border-2 border-dashed border-slate-800 rounded-xl bg-slate-900/30 p-8 text-center">
                 <svg className="w-12 h-12 md:w-16 md:h-16 mb-4 text-slate-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                 <p className="text-base md:text-lg">Ready to analyze content</p>
                 <p className="text-sm">Enter a URL to begin the audit.</p>
               </div>
             ) : (
               <div className="space-y-6">
                 {state.results.map((result, index) => (
                   <ResultCard key={`${result.url}-${index}`} result={result} />
                 ))}
               </div>
             )}
          </div>

        </div>
      </main>

      {/* Admin Panel Overlay */}
      {state.showAdmin && (
        <AdminPanel 
            settings={state.adminSettings}
            onSave={handleSaveSettings}
            onClose={() => setState(prev => ({ ...prev, showAdmin: false }))}
        />
      )}

      {/* Password Modal Overlay */}
      {showPasswordModal && (
        <PasswordModal 
            onAuthenticated={handleAuthenticated}
            onClose={() => setShowPasswordModal(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AnalysisResult, Recommendation } from '../types';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Tooltip } from 'recharts';

interface ResultCardProps {
  result: AnalysisResult;
}

const ScoreGauge: React.FC<{ label: string; score: number; color: string }> = ({ label, score, color }) => (
  <div className="flex flex-col items-center">
    <div className={`relative w-16 h-16 md:w-20 md:h-20 flex items-center justify-center rounded-full border-4 ${color} bg-slate-800`}>
      <span className="text-lg md:text-xl font-bold text-slate-100">{score}</span>
    </div>
    <span className="mt-2 text-[10px] md:text-xs text-slate-400 uppercase tracking-wider text-center">{label}</span>
  </div>
);

const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'recommendations' | 'details'>('overview');
  const [expandedRecs, setExpandedRecs] = useState<number[]>([]);

  const toggleRec = (index: number) => {
    setExpandedRecs(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index]
    );
  };

  // If there is an error, render the Error View
  if (result.error) {
    return (
      <div className="bg-slate-800 rounded-xl border border-red-900/50 overflow-hidden shadow-xl mb-8">
        <div className="p-6 flex flex-col gap-4">
           <div className="flex items-center justify-between">
              <h2 className="text-lg md:text-xl font-bold text-white truncate max-w-2xl" title={result.url}>{result.url}</h2>
              <span className="text-xs text-slate-400">{new Date(result.timestamp).toLocaleTimeString()}</span>
           </div>

           <div className="bg-red-900/20 border border-red-900/50 rounded-lg p-6 flex items-start gap-4">
              <div className="bg-red-900/30 p-3 rounded-full shrink-0">
                  <svg className="w-8 h-8 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              </div>
              <div>
                  <h3 className="text-lg font-semibold text-red-200 mb-2">Analysis Failed</h3>
                  <p className="text-slate-300">{result.error}</p>
                  <p className="text-sm text-slate-500 mt-2">The content could not be retrieved or processed. Please check if the URL is accessible or try again later.</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  // Normal View
  const chartData = [
    { subject: 'SEO', A: result.seoScore, fullMark: 100 },
    { subject: 'EEAT', A: result.eeatScore, fullMark: 100 },
    { subject: 'AI/LLM', A: result.llmOptimizationScore, fullMark: 100 },
    { subject: 'Content', A: Math.round((result.seoScore + result.eeatScore) / 2), fullMark: 100 },
    { subject: 'Trust', A: result.isYMYL ? result.eeatScore : 100, fullMark: 100 },
  ];

  const getPriorityColor = (p: string) => {
    switch (p) {
      case 'High': return 'text-red-400 border-red-900 bg-red-900/20';
      case 'Medium': return 'text-amber-400 border-amber-900 bg-amber-900/20';
      case 'Low': return 'text-blue-400 border-blue-900 bg-blue-900/20';
      default: return 'text-slate-400 border-slate-800';
    }
  };

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden shadow-xl mb-8">
      {/* Header */}
      <div className="p-4 md:p-6 border-b border-slate-700 flex flex-col gap-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-2">
            <h2 className="text-lg md:text-xl font-bold text-white truncate w-full" title={result.url}>{result.url}</h2>
            <div className="flex items-center gap-3 shrink-0">
                <span className="text-xs text-slate-400">{new Date(result.timestamp).toLocaleTimeString()}</span>
                {result.isYMYL && <span className="px-2 py-0.5 rounded text-[10px] bg-purple-900 text-purple-200 border border-purple-700 whitespace-nowrap">YMYL DETECTED</span>}
            </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
            {['overview', 'recommendations', 'details'].map((tab) => (
                <button
