        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              {/* Gauges - Wrap on small screens */}
              <div className="flex flex-wrap justify-center sm:justify-around gap-6 bg-slate-900/50 p-6 rounded-xl border border-slate-700/50">
                <ScoreGauge 
