                  </ul>
                </div>
              </div>
            </div>

            <div className="h-[250px] md:h-[300px] flex items-center justify-center bg-slate-900/30 rounded-xl border border-slate-700/50">
              <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="65%" data={chartData}>
                  <PolarGrid stroke="#334155" />
                  <PolarAngleAxis dataKey="subject" tick={{ fill: '#94a3b8', fontSize: 10 }} />
                  <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
                  <Radar name="Score" dataKey="A" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.3} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#f8fafc' }}
                  />
                </RadarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {activeTab === 'recommendations' && (
          <div className="space-y-3">
            {result.recommendations.map((rec, idx) => {
              const isExpanded = expandedRecs.includes(idx);
              return (
                <div key={idx} className="bg-slate-900/50 rounded-lg border border-slate-700 overflow-hidden transition-all duration-200">
                  {/* Accordion Header */}
                  <div 
                    onClick={() => toggleRec(idx)}
                    className="p-4 flex flex-col sm:flex-row sm:items-center gap-3 cursor-pointer hover:bg-slate-800/50 transition-colors"
                  >
                    <div className="flex items-center gap-3 flex-grow min-w-0">
                      <div className={`shrink-0 w-20 text-center px-2 py-1 rounded text-[10px] font-bold border uppercase ${getPriorityColor(rec.priority)}`}>
                        {rec.priority}
                      </div>
                      <div className="flex-grow min-w-0">
                         <div className="flex items-center gap-2 mb-0.5">
                            <h4 className="text-slate-200 font-semibold text-sm md:text-base truncate">{rec.action}</h4>
                            <span className="text-[10px] text-slate-500 bg-slate-800 px-2 py-0.5 rounded border border-slate-700">{rec.category}</span>
                         </div>
                         <p className="text-slate-400 text-xs truncate opacity-80">{rec.description}</p>
                      </div>
