const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Attempts to scrape the content of a URL using a rotation of CORS proxies.
 * Implements exponential backoff and max 5 attempts.
 */
export const scrapeUrl = async (
  url: string, 
  customProxies: CustomProxy[] = [],
  onStatusUpdate?: (status: string) => void
): Promise<ScrapingResult> => {
  // Validate URL
  if (!url || !url.startsWith('http')) {
    return {
      url,
      content: '',
      title: '',
      success: false,
      error: 'Invalid URL. Must start with http:// or https://'
    };
  }

  // Combine custom proxies (prioritized) with default proxies
  const activeCustomProxies: ProxyConfig[] = customProxies
    .filter(p => p.isActive)
    .map(p => ({
      name: 'CustomProxy',
      constructUrl: (target: string) => `${p.urlTemplate}${encodeURIComponent(target)}`,
      extract: async (res: Response) => {
        if (!res.ok) throw new Error(`Status ${res.status}`);
        return await res.text();
      }
    }));

  const allProxies = [...activeCustomProxies, ...DEFAULT_PROXIES];
  const MAX_ATTEMPTS = 5;
  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {

    // Try each proxy in the list for this attempt
    for (const proxy of allProxies) {
      try {
        if (onStatusUpdate) {
          onStatusUpdate(`Scraping attempt ${attempt}/${MAX_ATTEMPTS} via ${proxy.name}...`);
        }

        const proxyUrl = proxy.constructUrl(url);
        const response = await fetchWithTimeout(proxyUrl);

        if (onStatusUpdate) onStatusUpdate(`Processing content from ${proxy.name}...`);

        const html = await proxy.extract(response);

        if (!html || html.length < 50) {
          throw new Error("Empty content returned from proxy");
        }

        // Basic parsing to extract title and body text
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');

        // Remove noise elements to focus on content
        const noiseSelectors = 'script, style, noscript, iframe, svg, link, nav, footer, header, [role="alert"], .cookie-banner, .popup';
        const noise = doc.querySelectorAll(noiseSelectors);
        noise.forEach(el => el.remove());

        const title = doc.title || url;

        // Attempt to get text from specific main content areas first, falling back to body
        const mainContent = doc.querySelector('main') || doc.querySelector('article') || doc.querySelector('#content') || doc.body;
        const bodyText = mainContent.innerText || mainContent.textContent || '';

        // Clean up whitespace and truncate to avoid token limits
        const cleanedContent = bodyText.replace(/\s+/g, ' ').trim().slice(0, 45000); 

        if (cleanedContent.length < 100) {
           throw new Error("Page content is too short or protected by anti-bot measures.");
        }

        return {
          url,
          content: cleanedContent,
          title,
          success: true
        };

      } catch (error: any) {
        console.warn(`Scraping attempt ${attempt} failed with ${proxy.name}: ${error.message}`);
        lastError = error;
        // Continue to the next proxy in the loop
      }
    }

    // If we finished the proxy loop and didn't return, we failed this attempt block.
    // Wait before starting the next attempt block (Exponential backoff: 1s, 2s, 4s, 8s...)
    if (attempt < MAX_ATTEMPTS) {
      const waitTime = Math.pow(2, attempt - 1) * 1000;
      if (onStatusUpdate) onStatusUpdate(`Connection failed. Retrying in ${waitTime/1000}s...`);
      await sleep(waitTime);
    }
  }

  // If we get here, all attempts failed
  console.error("All scraping attempts failed.");
  return {
    url,
    content: '',
    title: '',
    success: false,
    error: `Failed to access content after ${MAX_ATTEMPTS} attempts. Last error: ${lastError?.message || 'Blocked by target'}`
  };
};

