import { ScrapingResult, CustomProxy } from '../types';

/**
 * Helper to fetch with timeout to prevent hanging requests
 */
const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 20000): Promise<Response> => {
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);
  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal
    });
    clearTimeout(id);
    return response;
  } catch (error) {
    clearTimeout(id);
    throw error;
  }
};

interface ProxyConfig {
  name: string;
  constructUrl: (target: string) => string;
  extract: (res: Response) => Promise<string>;
}

const DEFAULT_PROXIES: ProxyConfig[] = [
  {
    name: 'AllOrigins',
    constructUrl: (target: string) => `https://api.allorigins.win/get?url=${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      const data = await res.json();
      return data.contents; 
    }
  },
  {
    name: 'ThingProxy',
    constructUrl: (target: string) => `https://thingproxy.freeboard.io/fetch/${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'CorsProxy',
    constructUrl: (target: string) => `https://corsproxy.io/?${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'CodeTabs',
    constructUrl: (target: string) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'Direct (Fallback)',
    constructUrl: (target: string) => target, // Try direct fetch as last resort
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  }
];

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Attempts to scrape the content of a URL using a rotation of CORS proxies.
 * Implements exponential backoff and max 5 attempts.
 */
export const scrapeUrl = async (
  url: string, 
  customProxies: CustomProxy[] = [],
  onStatusUpdate?: (status: string) => void
): Promise<ScrapingResult> => {
  // Validate URL
  if (!url || !url.startsWith('http')) {
    return {
      url,
      content: '',
      title: '',
      success: false,
      error: 'Invalid URL. Must start with http:// or https://'
    };
  }

  // Combine custom proxies (prioritized) with default proxies
  const activeCustomProxies: ProxyConfig[] = customProxies
    .filter(p => p.isActive)
    .map(p => ({
      name: 'CustomProxy',
      constructUrl: (target: string) => `${p.urlTemplate}${encodeURIComponent(target)}`,
      extract: async (res: Response) => {
        if (!res.ok) throw new Error(`Status ${res.status}`);
        return await res.text();
      }
    }));

  const allProxies = [...activeCustomProxies, ...DEFAULT_PROXIES];
  const MAX_ATTEMPTS = 5;
  let lastError: Error | null = null;
  const errors: string[] = [];

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {

    // Try each proxy in the list for this attempt
    for (const proxy of allProxies) {
      try {
        if (onStatusUpdate) {
          onStatusUpdate(`Scraping attempt ${attempt}/${MAX_ATTEMPTS} via ${proxy.name}...`);
        }

        const proxyUrl = proxy.constructUrl(url);
        const response = await fetchWithTimeout(proxyUrl);

        if (onStatusUpdate) onStatusUpdate(`Processing content from ${proxy.name}...`);

        const html = await proxy.extract(response);

        if (!html || html.length < 50) {
          throw new Error("Empty content returned from proxy");
        }

        // Basic parsing to extract title and body text
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');

        // Remove noise elements to focus on content
        const noiseSelectors = 'script, style, noscript, iframe, svg, link, nav, footer, header, [role="alert"], .cookie-banner, .popup';
        const noise = doc.querySelectorAll(noiseSelectors);
        noise.forEach(el => el.remove());

        const title = doc.title || url;

        // Attempt to get text from specific main content areas first, falling back to body
        const mainContent = doc.querySelector('main') || doc.querySelector('article') || doc.querySelector('#content') || doc.body;

        if (!mainContent) {
           throw new Error("Could not identify main content area");
        }

        const bodyText = mainContent.innerText || mainContent.textContent || '';

        // Clean up whitespace and truncate to avoid token limits
        const cleanedContent = bodyText.replace(/\s+/g, ' ').trim().slice(0, 45000); 

        if (cleanedContent.length < 200) {
           throw new Error(`Page content is too short (${cleanedContent.length} chars). Site might be SPA or blocking bots.`);
        }

        return {
          url,
          content: cleanedContent,
          title,
          success: true
        };

      } catch (error: any) {
        const errorMsg = `[Attempt ${attempt} - ${proxy.name}] ${error.message}`;
        console.warn(errorMsg);
        errors.push(errorMsg);
        lastError = error;
        // Continue to the next proxy in the loop
      }
    }

    // If we finished the proxy loop and didn't return, we failed this attempt block.
    // Wait before starting the next attempt block (Exponential backoff: 1s, 2s, 4s, 8s...)
    if (attempt < MAX_ATTEMPTS) {
      const waitTime = Math.pow(2, attempt - 1) * 1000;
      if (onStatusUpdate) onStatusUpdate(`Connection failed. Retrying in ${waitTime/1000}s...`);
      await sleep(waitTime);
    }
  }

  // If we get here, all attempts failed
  console.error("All scraping attempts failed.", errors);

  // Construct a more helpful error message
  let helpfulMessage = "Could not access content.";
  if (errors.some(e => e.includes("SPA"))) {
    helpfulMessage = "The site appears to be a Single Page Application (SPA) without server-side rendering, which cannot be scraped by this tool.";
  } else if (errors.some(e => e.includes("403") || e.includes("401"))) {
     helpfulMessage = "Access denied by target site (403/401).";
  }

  return {
    url,
    content: '',
    title: '',
    success: false,
    error: `${helpfulMessage} (Tried ${MAX_ATTEMPTS} attempts via ${allProxies.length} proxies). Last technical error: ${lastError?.message}`
  };
};

import { ScrapingResult, CustomProxy } from '../types';

/**
 * Helper to fetch with timeout to prevent hanging requests.
 * supports external AbortSignal to stop requests manually.
 */
const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 25000, signal?: AbortSignal): Promise<Response> => {
  if (signal?.aborted) {
    throw new DOMException('Aborted', 'AbortError');
  }

  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);

  const onAbort = () => {
    clearTimeout(id);
    controller.abort();
  };

  if (signal) {
    signal.addEventListener('abort', onAbort);
  }

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal
    });
    clearTimeout(id);
    if (signal) signal.removeEventListener('abort', onAbort);
    return response;
  } catch (error) {
    clearTimeout(id);
    if (signal) signal.removeEventListener('abort', onAbort);
    throw error;
  }
};

interface ProxyConfig {
  name: string;
  constructUrl: (target: string) => string;
  extract: (res: Response) => Promise<string>;
  isMarkdown?: boolean;
}

const DEFAULT_PROXIES: ProxyConfig[] = [
  {
    name: 'Jina Reader (High Success)',
    constructUrl: (target: string) => `https://r.jina.ai/${target}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    },
    isMarkdown: true
  },
  {
    name: 'AllOrigins',
    constructUrl: (target: string) => `https://api.allorigins.win/get?url=${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      const data = await res.json();
      return data.contents; 
    }
  },
  {
    name: 'CorsProxy',
    constructUrl: (target: string) => `https://corsproxy.io/?${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'ThingProxy',
    constructUrl: (target: string) => `https://thingproxy.freeboard.io/fetch/${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'Direct (Fallback)',
    constructUrl: (target: string) => target, 
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  }
];

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Attempts to scrape the content of a URL using a rotation of CORS proxies.
 * Implements exponential backoff, max 5 attempts, and abort capability.
 */
export const scrapeUrl = async (
  url: string, 
  customProxies: CustomProxy[] = [],
  onStatusUpdate?: (status: string) => void,
  signal?: AbortSignal
): Promise<ScrapingResult> => {
  // Validate URL
  if (!url || !url.startsWith('http')) {
    return {
      url,
      content: '',
      title: '',
      success: false,
      error: 'Invalid URL. Must start with http:// or https://'
    };
  }

  // Combine custom proxies (prioritized) with default proxies
  const activeCustomProxies: ProxyConfig[] = customProxies
    .filter(p => p.isActive)
    .map(p => ({
      name: 'CustomProxy',
      constructUrl: (target: string) => `${p.urlTemplate}${encodeURIComponent(target)}`,
      extract: async (res: Response) => {
        if (!res.ok) throw new Error(`Status ${res.status}`);
        return await res.text();
      }
    }));

  const allProxies = [...activeCustomProxies, ...DEFAULT_PROXIES];
  const MAX_ATTEMPTS = 5;
  let lastError: Error | null = null;
  const errors: string[] = [];

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    // Check abort before starting attempt
    if (signal?.aborted) {
        return {
            url, content: '', title: '', success: false, error: 'Scraping stopped by user.'
        };
    }

    // Try each proxy in the list for this attempt
    for (const proxy of allProxies) {
      if (signal?.aborted) {
        return { url, content: '', title: '', success: false, error: 'Scraping stopped by user.' };
      }

      try {
        if (onStatusUpdate) {
          onStatusUpdate(`Attempt ${attempt}/${MAX_ATTEMPTS}: Requesting via ${proxy.name}...`);
        }

        const proxyUrl = proxy.constructUrl(url);

        // Add headers to imitate a real browser where possible (Direct/some proxies)
        const fetchOptions: RequestInit = {
            method: 'GET',
            headers: {
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'Accept-Language': 'en-US,en;q=0.9',
                'Cache-Control': 'no-cache',
            }
        };

        const response = await fetchWithTimeout(proxyUrl, fetchOptions, 25000, signal);

        if (onStatusUpdate) onStatusUpdate(`Processing content from ${proxy.name}...`);

        const rawContent = await proxy.extract(response);

        if (!rawContent || rawContent.length < 50) {
          throw new Error("Empty content returned from proxy");
        }

        // Processing Logic
        let cleanedContent = '';
        let title = url;

        if (proxy.isMarkdown) {
             // Jina returns Markdown. It is already clean content.
             // We can extract a title from the first line if it's a H1
             const lines = rawContent.split('\n');
             if (lines[0].startsWith('# ')) {
                 title = lines[0].substring(2).trim();
             }
             cleanedContent = rawContent;
        } else {
             // HTML Parsing
             const parser = new DOMParser();
             const doc = parser.parseFromString(rawContent, 'text/html');

             // Remove noise elements
             const noiseSelectors = 'script, style, noscript, iframe, svg, link, nav, footer, header, [role="alert"], .cookie-banner, .popup, .ad-container';
             const noise = doc.querySelectorAll(noiseSelectors);
             noise.forEach(el => el.remove());

             title = doc.title || url;

             const mainContent = doc.querySelector('main') || doc.querySelector('article') || doc.querySelector('#content') || doc.body;
             if (!mainContent) throw new Error("Could not identify main content area");

             cleanedContent = mainContent.innerText || mainContent.textContent || '';
        }

        // Clean up whitespace and truncate
        cleanedContent = cleanedContent.replace(/\s+/g, ' ').trim().slice(0, 50000); 

        if (cleanedContent.length < 200) {
           throw new Error(`Page content is too short (${cleanedContent.length} chars). Site might be SPA or blocking bots.`);
        }

        return {
          url,
          content: cleanedContent,
          title,
          success: true
        };

      } catch (error: any) {
        if (error.name === 'AbortError') throw error; // Propagate abort

        const errorMsg = `[Attempt ${attempt} - ${proxy.name}] ${error.message}`;
        console.warn(errorMsg);
        errors.push(errorMsg);
        lastError = error;
      }
    }

    // Wait before starting the next attempt block
    if (attempt < MAX_ATTEMPTS) {
      if (signal?.aborted) break;
      // Randomize delay slightly to imitate human behavior (2s - 5s + exponential)
      const baseDelay = Math.pow(2, attempt - 1) * 1000;
      const randomJitter = Math.random() * 2000;
      const waitTime = baseDelay + randomJitter;

      if (onStatusUpdate) onStatusUpdate(`Connection failed. Cooling down for ${(waitTime/1000).toFixed(1)}s...`);
      await sleep(waitTime);
    }
  }

  // If we get here, all attempts failed
  console.error("All scraping attempts failed.", errors);

  let helpfulMessage = "Could not access content.";
  if (errors.some(e => e.includes("SPA"))) {
    helpfulMessage = "The site appears to be a Single Page Application (SPA) or is blocking automated access.";
  } else if (errors.some(e => e.includes("403") || e.includes("401"))) {
     helpfulMessage = "Access denied by target site (Anti-bot protection active).";
  }

  return {
    url,
    content: '',
    title: '',
    success: false,
    error: `${helpfulMessage} Tried ${MAX_ATTEMPTS} attempts. Last error: ${lastError?.message}`
  };
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AnalysisMode, AppState, ModelType, AnalysisCriteria, AnalysisResult, AdminSettings } from './types';
import { scrapeUrl } from './services/scraperService';
import { analyzeContent } from './services/geminiService';
import { loadAdminSettings, saveAdminSettings } from './services/adminService';
import CriteriaSettings from './components/CriteriaSettings';
import ResultCard from './components/ResultCard';
import AdminPanel from './components/AdminPanel';
import PasswordModal from './components/PasswordModal';

const INITIAL_CRITERIA: AnalysisCriteria = {
  focusArea: 'General SEO',
  strictness: 'medium',
  customInstructions: ''
};

const DEFAULT_PROMPT_TEMPLATE = `
Analyze the following web page content located at: {{url}}

Content Preview:
{{content}}

Analysis Criteria:
- Focus Area: {{focusArea}}
- Strictness Level: {{strictness}}
- User Custom Instructions: {{customInstructions}}

Tasks:
1. Assess SEO Optimization (Keywords, structure, readability).
2. Evaluate E-E-A-T (Experience, Expertise, Authoritativeness, Trustworthiness).
3. Determine if YMYL (Your Money Your Life) applies and if standards are met.
4. Analyze for LLM/AI Answer Engine Optimization (Is the data structured? Is it clear for an AI to cite?).
5. Provide a COMPREHENSIVE list of 25 to 30 detailed, actionable recommendations. 
   - DO NOT limit yourself to 5. Dig deep. Find every issue.
   - For EACH recommendation, you MUST:
     a) Identify the specific "Affected Content" (a quote, HTML tag, or section).
     b) Provide specific "Fix Steps" (an ordered list of actions).
     c) Explain the "Expected Impact" (e.g., improves CTR, fixes indexing).
`.trim();

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    mode: AnalysisMode.SINGLE,
    urls: [],
    results: [],
    isAnalyzing: false,
    currentProgress: 0,
    progressStatus: '',
    selectedModel: ModelType.FLASH,
    criteria: INITIAL_CRITERIA,
    showAdmin: false,
    isAdminAuthenticated: false,
    adminSettings: {
        promptTemplate: DEFAULT_PROMPT_TEMPLATE,
        instructionFiles: [],
        customProxies: [],
        proxyConsent: false
    }
  });

  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  // Ref to hold the AbortController for the current analysis session
  const abortControllerRef = useRef<AbortController | null>(null);

  // Load settings on mount
  useEffect(() => {
    const savedSettings = loadAdminSettings();
    if (savedSettings) {
      setState(prev => ({ ...prev, adminSettings: savedSettings }));
    }
  }, []);

  const handleAdminClick = () => {
    if (state.isAdminAuthenticated) {
      setState(prev => ({ ...prev, showAdmin: true }));
    } else {
      setShowPasswordModal(true);
    }
  };

  const handleAuthenticated = () => {
    setState(prev => ({ ...prev, isAdminAuthenticated: true, showAdmin: true }));
    setShowPasswordModal(false);
  };

  const handleSaveSettings = (newSettings: AdminSettings) => {
    setState(prev => ({ ...prev, adminSettings: newSettings }));
    saveAdminSettings(newSettings);
  };

  const handleStopAnalysis = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
      setState(prev => ({ 
        ...prev, 
        isAnalyzing: false, 
        progressStatus: 'Analysis stopped by user.' 
      }));
    }
  }, []);

  const handleStartAnalysis = useCallback(async () => {
    // Create new AbortController for this run
    if (abortControllerRef.current) {
        abortControllerRef.current.abort(); // Ensure previous is aborted
    }
    const controller = new AbortController();
    abortControllerRef.current = controller;

    let urlsToProcess: string[] = [];

    if (state.mode === AnalysisMode.SINGLE) {
      if (!inputUrl) return;
      urlsToProcess = [inputUrl];
    } else {
      if (!bulkInput) return;
      urlsToProcess = bulkInput.split('\n').map(u => u.trim()).filter(u => u.length > 0);
    }

    if (urlsToProcess.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], // Clear previous results
      currentProgress: 0,
      progressStatus: 'Initializing...'
    }));

    const results: AnalysisResult[] = [];
    const total = urlsToProcess.length;

    try {
      for (let i = 0; i < total; i++) {
        // Check abort signal between items
        if (controller.signal.aborted) break;

        const url = urlsToProcess[i];

        // Step 1: Scrape
        setState(prev => ({ ...prev, progressStatus: `Scraping ${url}...` }));

        const scrapeResult = await scrapeUrl(
          url, 
          state.adminSettings.customProxies, 
          (status) => setState(prev => ({ ...prev, progressStatus: status })),
          controller.signal
        );

        if (controller.signal.aborted) break;

        let analysisResult: AnalysisResult;

        if (scrapeResult.success && scrapeResult.content) {
           // Step 2: Analyze with Gemini using Admin Settings
           setState(prev => ({ ...prev, progressStatus: `Analyzing content with AI...` }));
           analysisResult = await analyzeContent(
              url, 
              scrapeResult.content, 
              state.criteria, 
              state.selectedModel, 
              state.adminSettings
           );
        } else {
           // Handle failure gracefully
           analysisResult = {
               url,
               timestamp: Date.now(),
               seoScore: 0,
               eeatScore: 0,
               llmOptimizationScore: 0,
               isYMYL: false,
               summary: "Analysis Failed",
               strengths: [],
               weaknesses: [],
               recommendations: [],
               keywordGaps: [],
               sentiment: "N/A",
               error: scrapeResult.error || "Unknown Error: Could not access content"
           };
        }

        results.push(analysisResult);

        // Update progress
        setState(prev => ({
          ...prev,
          results: [...results],
          currentProgress: Math.round(((i + 1) / total) * 100),
          progressStatus: i === total - 1 ? 'Finalizing...' : 'Next URL...'
        }));
      }
    } catch (err: any) {
        if (err.name !== 'AbortError') {
            console.error("Batch processing error", err);
        }
    } finally {
        // Cleanup
        if (abortControllerRef.current === controller) {
            abortControllerRef.current = null;
        }
        setState(prev => ({ 
            ...prev, 
            isAnalyzing: false, 
            progressStatus: controller.signal.aborted ? 'Stopped' : 'Complete' 
        }));
    }

  }, [state.mode, state.criteria, state.selectedModel, state.adminSettings, inputUrl, bulkInput]);

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 flex flex-col">
      {/* Navbar */}
      <nav className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16 gap-4">
            <div className="flex items-center gap-3 shrink-0">
              <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <span className="font-bold text-lg md:text-xl tracking-tight text-white hidden sm:block">ContentAudit AI</span>
              <span className="font-bold text-lg tracking-tight text-white sm:hidden">ContentAudit</span>
            </div>

            <div className="flex items-center gap-2 md:gap-4 overflow-x-auto scrollbar-hide">
               <select 
                 value={state.selectedModel}
                 onChange={(e) => setState(prev => ({ ...prev, selectedModel: e.target.value as ModelType }))}
                 className="bg-slate-800 text-xs md:text-sm border border-slate-700 text-slate-300 rounded px-2 py-1.5 md:px-3 focus:ring-2 focus:ring-blue-500 outline-none max-w-[120px] md:max-w-none"
               >
                 <option value={ModelType.FLASH}>Gemini 2.5 Flash</option>
                 <option value={ModelType.PRO}>Gemini 3 Pro</option>
               </select>

               <button
                  onClick={handleAdminClick}
                  className="bg-slate-800 hover:bg-slate-700 text-slate-300 p-2 rounded border border-slate-700 transition-colors"
                  title="Admin Settings"
               >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
               </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full flex-grow">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Column: Controls (Full width on mobile, 4 cols on desktop) */}
          <div className="col-span-1 lg:col-span-4 space-y-6">

            {/* Input Section */}
            <div className="bg-slate-800 p-6 rounded-lg border border-slate-700 shadow-lg">
              <div className="flex gap-4 mb-6 border-b border-slate-700 pb-2 overflow-x-auto scrollbar-hide">
                <button
                  onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.SINGLE }))}
                  className={`pb-2 text-sm font-medium transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.SINGLE ? 'text-blue-400' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Single URL
                  {state.mode === AnalysisMode.SINGLE && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-400"></span>}
                </button>
                <button
                   onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.BULK }))}
                   className={`pb-2 text-sm font-medium transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.BULK ? 'text-blue-400' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  Bulk Mode
                  {state.mode === AnalysisMode.BULK && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-400"></span>}
                </button>
              </div>

              {state.mode === AnalysisMode.SINGLE ? (
                <div>
                  <label className="block text-sm font-medium text-slate-400 mb-2">Target URL</label>
                  <input
                    type="text"
                    placeholder="https://example.com/blog/article"
                    value={inputUrl}
                    onChange={(e) => setInputUrl(e.target.value)}
                    className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-slate-200 focus:ring-2 focus:ring-blue-500 outline-none placeholder-slate-600 text-sm"
                  />
                </div>
              ) : (
                <div>
                   <label className="block text-sm font-medium text-slate-400 mb-2">Target URLs (One per line)</label>
                   <textarea
                     placeholder="https://site1.com&#10;https://site2.com"
                     value={bulkInput}
                     onChange={(e) => setBulkInput(e.target.value)}
                     className="w-full bg-slate-900 border border-slate-700 rounded p-3 text-slate-200 h-32 focus:ring-2 focus:ring-blue-500 outline-none placeholder-slate-600 resize-none text-sm"
                   />
                </div>
              )}

              {state.isAnalyzing ? (
                 <button
                    onClick={handleStopAnalysis}
                    className="mt-6 w-full py-3 rounded font-semibold text-white transition-all shadow-lg bg-red-600 hover:bg-red-500 hover:shadow-red-500/20 flex flex-col items-center justify-center relative overflow-hidden"
                 >
                     <div 
                        className="absolute top-0 left-0 h-full bg-red-500/30 transition-all duration-300 ease-out"
                        style={{ width: `${state.currentProgress}%` }}
                      ></div>
                     <span className="relative z-10 flex items-center gap-2">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        Stop Analysis
                     </span>
                     <span className="relative z-10 text-xs text-red-100 mt-1 font-normal opacity-90 animate-pulse">
                        {state.progressStatus} ({state.currentProgress}%)
                     </span>
                 </button>
              ) : (
                <button
                    onClick={handleStartAnalysis}
                    disabled={state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput}
                    className={`mt-6 w-full py-3 rounded font-semibold text-white transition-all shadow-lg overflow-hidden relative group ${
                    (state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput)
                        ? 'bg-blue-600/50 cursor-not-allowed' 
                        : 'bg-blue-600 hover:bg-blue-500 hover:shadow-blue-500/20'
                    }`}
                >
                    Start Audit
                </button>
              )}
            </div>

            {/* Criteria Panel */}
            <CriteriaSettings 
              criteria={state.criteria} 
              onChange={(newCriteria) => setState(prev => ({ ...prev, criteria: newCriteria }))} 
            />

            {/* Quick Tips */}
            <div className="bg-slate-800/50 p-4 rounded-lg border border-slate-700 hidden sm:block">
              <h4 className="text-sm font-semibold text-slate-300 mb-2">Did you know?</h4>
              <p className="text-xs text-slate-500">
                Gemini 2.5 Flash is significantly faster for quick checks, while Gemini 3 Pro is better at understanding complex nuances in medical or financial content (YMYL).
              </p>
            </div>

          </div>

          {/* Right Column: Results (Full width on mobile, 8 cols on desktop) */}
          <div className="col-span-1 lg:col-span-8">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-500 min-h-[300px] md:min-h-[400px] border-2 border-dashed border-slate-800 rounded-xl bg-slate-900/30 p-8 text-center">
                 <svg className="w-12 h-12 md:w-16 md:h-16 mb-4 text-slate-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                 <p className="text-base md:text-lg">Ready to analyze content</p>
                 <p className="text-sm">Enter a URL to begin the audit.</p>
               </div>
             ) : (
               <div className="space-y-6">
