import React, { useRef, useState } from 'react';
import { AdminSettings, InstructionFile, CustomProxy } from '../types';
import { exportSettingsToFile } from '../services/adminService';

interface AdminPanelProps {
  settings: AdminSettings;
  onSave: (settings: AdminSettings) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ settings, onSave, onClose }) => {
  const [localSettings, setLocalSettings] = useState<AdminSettings>(settings);
  const [newProxyUrl, setNewProxyUrl] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const configInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;

    Array.from(files).forEach((file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        const newFile: InstructionFile = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          size: file.size
        };
        setLocalSettings(prev => ({
          ...prev,
          instructionFiles: [...prev.instructionFiles, newFile]
        }));
      };
      reader.readAsText(file);
    });

    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleConfigImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const content = e.target?.result as string;
            const parsed = JSON.parse(content) as AdminSettings;
            if (parsed.promptTemplate) {
                setLocalSettings(parsed);
                alert("Configuration imported successfully!");
            } else {
                throw new Error("Invalid format");
            }
        } catch (err) {
            alert("Failed to import configuration. Invalid file format.");
        }
    };
    reader.readAsText(file);
    if (configInputRef.current) configInputRef.current.value = '';
  };

  const removeFile = (id: string) => {
    setLocalSettings(prev => ({
      ...prev,
      instructionFiles: prev.instructionFiles.filter(f => f.id !== id)
    }));
  };

  const addProxy = () => {
    if (!newProxyUrl) return;
    if (!localSettings.proxyConsent) {
      alert("You must agree to store proxy information locally before adding a proxy.");
      return;
    }

    const newProxy: CustomProxy = {
      id: Math.random().toString(36).substr(2, 9),
      urlTemplate: newProxyUrl,
      isActive: true
    };

    setLocalSettings(prev => ({
      ...prev,
      customProxies: [...(prev.customProxies || []), newProxy]
    }));
    setNewProxyUrl('');
  };

  const toggleProxy = (id: string) => {
     setLocalSettings(prev => ({
       ...prev,
       customProxies: prev.customProxies.map(p => p.id === id ? { ...p, isActive: !p.isActive } : p)
     }));
  };

  const removeProxy = (id: string) => {
    setLocalSettings(prev => ({
      ...prev,
      customProxies: prev.customProxies.filter(p => p.id !== id)
    }));
  };

  const handleConsentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
     const isChecked = e.target.checked;
     setLocalSettings(prev => ({
       ...prev,
       proxyConsent: isChecked,
       // If consent is revoked, clear proxies
       customProxies: isChecked ? prev.customProxies : []
     }));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 overflow-y-auto">
      <div className="bg-white w-full max-w-4xl rounded-xl border border-gray-200 shadow-2xl flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-white rounded-t-xl sticky top-0 z-10">
          <div>
            <h2 className="text-xl font-bold text-slate-900 flex items-center gap-2">
              <svg className="w-6 h-6 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
