import React, { useState, useEffect } from 'react';
import { CustomProxy } from '../types';

interface ProxyModalProps {
  onClose: () => void;
  onSave: (proxies: CustomProxy[]) => void;
  initialProxies: CustomProxy[];
}

const STORAGE_KEY = 'content_audit_user_proxies';

const ProxyModal: React.FC<ProxyModalProps> = ({ onClose, onSave, initialProxies }) => {
  const [proxies, setProxies] = useState<CustomProxy[]>([]);

  // New Proxy Form State
  const [ip, setIp] = useState('');
  const [port, setPort] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [protocol, setProtocol] = useState<'http' | 'https'>('http');

  useEffect(() => {
    // Load from props or local storage fallback
    if (initialProxies.length > 0) {
      setProxies(initialProxies);
    } else {
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) setProxies(JSON.parse(stored));
      } catch (e) {
        console.error("Failed to load proxies", e);
      }
    }
  }, [initialProxies]);

  const saveProxies = (newProxies: CustomProxy[]) => {
    setProxies(newProxies);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newProxies));
    onSave(newProxies);
  };

  const addProxy = () => {
    if (!ip || !port) return;

    const newProxy: CustomProxy = {
      id: Math.random().toString(36).substr(2, 9),
      ip,
      port,
      username,
      password,
      protocol,
      isActive: true
    };

    saveProxies([...proxies, newProxy]);

    // Reset Form
    setIp('');
    setPort('');
    setUsername('');
    setPassword('');
  };

  const removeProxy = (id: string) => {
    saveProxies(proxies.filter(p => p.id !== id));
  };

  const toggleProxy = (id: string) => {
    saveProxies(proxies.map(p => p.id === id ? { ...p, isActive: !p.isActive } : p));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 overflow-y-auto">
      <div className="bg-white w-full max-w-2xl rounded-xl border border-gray-200 shadow-2xl flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-white rounded-t-xl sticky top-0 z-10">
          <div>
            <h2 className="text-xl font-bold text-slate-900 flex items-center gap-2">
              <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
              Network & Proxy Configuration
            </h2>
            <p className="text-slate-500 text-sm mt-1">Configure custom proxies to bypass restrictions. Data is stored locally.</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-white">

          {/* Add Proxy Form */}
          <div className="bg-gray-50 p-5 rounded-lg border border-gray-200 shadow-sm">
             <h3 className="text-sm font-bold text-slate-900 mb-3 uppercase tracking-wide">Add New Proxy</h3>
             <div className="grid grid-cols-1 md:grid-cols-12 gap-3">
                 <div className="md:col-span-2">
                     <label className="text-xs font-semibold text-slate-500 mb-1 block">Protocol</label>
                     <select 
                        value={protocol} 
                        onChange={e => setProtocol(e.target.value as any)}
                        className="w-full bg-white border border-gray-300 rounded px-2 py-2 text-sm outline-none focus:ring-1 focus:ring-green-500"
                     >
                         <option value="http">HTTP</option>
                         <option value="https">HTTPS</option>
                     </select>
                 </div>
                 <div className="md:col-span-4">
                     <label className="text-xs font-semibold text-slate-500 mb-1 block">IP Address / Host</label>
                     <input 
                        type="text" 
                        value={ip}
                        onChange={e => setIp(e.target.value)}
                        placeholder="192.168.1.1"
                        className="w-full bg-white border border-gray-300 rounded px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-green-500"
                     />
                 </div>
                 <div className="md:col-span-2">
                     <label className="text-xs font-semibold text-slate-500 mb-1 block">Port</label>
                     <input 
                        type="text" 
                        value={port}
                        onChange={e => setPort(e.target.value)}
                        placeholder="8080"
                        className="w-full bg-white border border-gray-300 rounded px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-green-500"
                     />
                 </div>
                 <div className="md:col-span-2">
                     <label className="text-xs font-semibold text-slate-500 mb-1 block">Username (Opt)</label>
                     <input 
                        type="text" 
                        value={username}
                        onChange={e => setUsername(e.target.value)}
                        placeholder="user"
                        className="w-full bg-white border border-gray-300 rounded px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-green-500"
                     />
                 </div>
                 <div className="md:col-span-2">
                     <label className="text-xs font-semibold text-slate-500 mb-1 block">Password (Opt)</label>
                     <input 
                        type="password" 
                        value={password}
                        onChange={e => setPassword(e.target.value)}
                        placeholder="pass"
                        className="w-full bg-white border border-gray-300 rounded px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-green-500"
                     />
                 </div>
             </div>
             <div className="mt-4 flex justify-end">
