                     No proxies configured. The app will use default public relays.
                 </div>
             ) : (
                 proxies.map(p => (
                     <div key={p.id} className="flex items-center justify-between bg-white p-3 rounded-lg border border-gray-200 shadow-sm">
                         <div className="flex items-center gap-4">
                             <button 
                                onClick={() => toggleProxy(p.id)}
                                className={`w-4 h-4 rounded-full border ${p.isActive ? 'bg-green-500 border-green-600' : 'bg-gray-200 border-gray-300'}`}
                                title={p.isActive ? 'Active' : 'Inactive'}
                             />
                             <div className="flex flex-col">
                                 <div className="flex items-center gap-2">
                                     <span className="font-mono text-sm font-bold text-slate-800">{p.ip}:{p.port}</span>
                                     <span className="text-[10px] uppercase bg-gray-100 px-1.5 py-0.5 rounded text-slate-500 border border-gray-200">{p.protocol}</span>
                                 </div>
                                 {p.username && <span className="text-xs text-slate-500">Auth: {p.username} / ******</span>}
                             </div>
                         </div>
                         <button 
                            onClick={() => removeProxy(p.id)}
