/**
 * Helper to fetch with timeout to prevent hanging requests.
 * supports external AbortSignal to stop requests manually.
 */
const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 40000, signal?: AbortSignal): Promise<Response> => {
  if (signal?.aborted) {
    throw new DOMException('Aborted', 'AbortError');
  }

  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);

  const onAbort = () => {
    clearTimeout(id);
    controller.abort();
  };

  if (signal) {
    signal.addEventListener('abort', onAbort);
  }

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal
    });
    clearTimeout(id);
    if (signal) signal.removeEventListener('abort', onAbort);
    return response;
  } catch (error) {
    clearTimeout(id);
    if (signal) signal.removeEventListener('abort', onAbort);
    throw error;
  }
};

interface ProxyConfig {
  name: string;
  constructUrl: (target: string) => string;
  headers?: (target: string) => Record<string, string>;
  extract: (res: Response) => Promise<string>;
  isMarkdown?: boolean;
}

const DEFAULT_PROXIES: ProxyConfig[] = [
  {
    name: 'Jina Reader (Standard)',
    // Standard Jina usage. Appending raw URL is often more reliable than query param for some redirects
    constructUrl: (target: string) => `https://r.jina.ai/${target}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    },
    isMarkdown: true
  },
  {
    name: 'Jina Reader (Encoded)',
    // Fallback Jina with encoding if deep link failed due to special chars
    constructUrl: (target: string) => `https://r.jina.ai/${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    },
    isMarkdown: true
  },
  {
    name: 'AllOrigins',
    constructUrl: (target: string) => `https://api.allorigins.win/get?url=${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      const data = await res.json();
      return data.contents; 
    }
  },
  {
    name: 'CorsProxy',
    constructUrl: (target: string) => `https://corsproxy.io/?${encodeURIComponent(target)}`,
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  },
  {
    name: 'Direct (Fallback)',
    constructUrl: (target: string) => target, 
    extract: async (res: Response) => {
      if (!res.ok) throw new Error(`Status ${res.status}`);
      return await res.text();
    }
  }
];

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Attempts to scrape the content of a URL using a rotation of CORS proxies.
 * Implements exponential backoff, max 5 attempts, and abort capability.
 */
export const scrapeUrl = async (
  url: string, 
  customProxies: CustomProxy[] = [],
  onStatusUpdate?: (status: string) => void,
  signal?: AbortSignal
): Promise<ScrapingResult> => {
  // Validate URL
  if (!url || !url.startsWith('http')) {
    return {
      url,
      content: '',
      title: '',
      success: false,
      error: 'Invalid URL. Must start with http:// or https://'
    };
  }

  // Convert structured CustomProxy objects into ProxyConfig objects
  const activeCustomProxies: ProxyConfig[] = customProxies
    .filter(p => p.isActive && p.ip && p.port)
    .map(p => {
      const protocol = p.protocol || 'http';
      const authHeader = (p.username && p.password) 
        ? { 'Authorization': 'Basic ' + btoa(`${p.username}:${p.password}`) }
        : {};

      return {
        name: `Custom (${p.ip})`,
        constructUrl: (target: string) => `${protocol}://${p.ip}:${p.port}/?url=${encodeURIComponent(target)}`,
        headers: () => authHeader,
        extract: async (res: Response) => {
          if (!res.ok) throw new Error(`Status ${res.status}`);
          return await res.text();
        }
      };
    });

  const allProxies = [...activeCustomProxies, ...DEFAULT_PROXIES];
  const MAX_ATTEMPTS = 5;
  let lastError: Error | null = null;
  const errors: string[] = [];

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    // Check abort before starting attempt
    if (signal?.aborted) {
        return {
            url, content: '', title: '', success: false, error: 'Scraping stopped by user.'
        };
    }

    // Try each proxy in the list for this attempt
    for (const proxy of allProxies) {
      if (signal?.aborted) {
        return { url, content: '', title: '', success: false, error: 'Scraping stopped by user.' };
      }

      try {
        if (onStatusUpdate) {
          onStatusUpdate(`Attempt ${attempt}: Requesting via ${proxy.name}...`);
        }

        const proxyUrl = proxy.constructUrl(url);

        // Construct headers
        const fetchOptions: RequestInit = {
            method: 'GET',
            headers: {
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'Accept-Language': 'en-US,en;q=0.9',
                'Cache-Control': 'no-cache',
                ...(proxy.headers ? proxy.headers(url) : {})
            },
            redirect: 'follow'
        };

        // Increase timeout to 60s for Jina, 30s for others
        const timeout = proxy.name.includes('Jina') ? 60000 : 30000;
        const response = await fetchWithTimeout(proxyUrl, fetchOptions, timeout, signal);

        if (onStatusUpdate) onStatusUpdate(`Downloading content from ${proxy.name}...`);

        const rawContent = await proxy.extract(response);

        if (!rawContent || rawContent.length < 50) {
          throw new Error("Empty content returned from proxy");
        }

        // Processing Logic
        let cleanedContent = '';
        let title = url;

        if (proxy.isMarkdown) {
             // Jina returns Markdown.
             const lines = rawContent.split('\n');
             if (lines[0].startsWith('# ')) {
                 title = lines[0].substring(2).trim();
             }
             cleanedContent = rawContent;
        } else {
             // HTML Parsing
             const parser = new DOMParser();
             const doc = parser.parseFromString(rawContent, 'text/html');

             // Remove noise elements
             const noiseSelectors = 'script, style, noscript, iframe, svg, link, nav, footer, header, [role="alert"], .cookie-banner, .popup, .ad-container';
             const noise = doc.querySelectorAll(noiseSelectors);
             noise.forEach(el => el.remove());

             title = doc.title || url;

             const mainContent = doc.querySelector('main') || doc.querySelector('article') || doc.querySelector('#content') || doc.body;
             if (!mainContent) throw new Error("Could not identify main content area");

             cleanedContent = mainContent.innerText || mainContent.textContent || '';
        }

        // Clean up whitespace and truncate
        cleanedContent = cleanedContent.replace(/\s+/g, ' ').trim().slice(0, 50000); 

        // --- VALIDATION CHECKS ---
        if (cleanedContent.length < 200) {
           throw new Error(`Page content is too short (${cleanedContent.length} chars). Site might be SPA or blocking bots.`);
        }

        const lower = cleanedContent.toLowerCase();
        if (lower.includes('captcha') || lower.includes('verify you are human') || lower.includes('access denied') || lower.includes('security check')) {
            throw new Error("Anti-bot/Captcha detected.");
        }

        if (lower.includes('please enable javascript') || lower.includes('javascript is required')) {
            throw new Error("JavaScript required (SPA). Jina Reader should handle this, but failed.");
        }

        return {
          url,
          content: cleanedContent,
          title,
          success: true
        };

      } catch (error: any) {
        if (error.name === 'AbortError') throw error; // Propagate abort

        const errorMsg = `[Attempt ${attempt} - ${proxy.name}] ${error.message}`;
        console.warn(errorMsg);
        errors.push(errorMsg);
        lastError = error;
      }
    }

    // Wait before starting the next attempt block
    if (attempt < MAX_ATTEMPTS) {
      if (signal?.aborted) break;
      // Randomize delay slightly to imitate human behavior
      const baseDelay = Math.pow(2, attempt - 1) * 1000;
      const randomJitter = Math.random() * 2000;
      const waitTime = baseDelay + randomJitter;

      if (onStatusUpdate) onStatusUpdate(`Retrying in ${(waitTime/1000).toFixed(1)}s...`);
      await sleep(waitTime);
    }
  }

  // If we get here, all attempts failed
  console.error("All scraping attempts failed.", errors);

  let helpfulMessage = "Could not access content.";
  if (errors.some(e => e.includes("SPA"))) {
    helpfulMessage = "The site appears to be a Single Page Application (SPA) or is blocking automated access.";
  } else if (errors.some(e => e.includes("403") || e.includes("401"))) {
     helpfulMessage = "Access denied by target site (Anti-bot protection active).";
  }

  return {
    url,
    content: '',
    title: '',
    success: false,
    error: `${helpfulMessage} Tried ${MAX_ATTEMPTS} attempts. Last error: ${lastError?.message}`
  };
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { AnalysisCriteria, AnalysisResult, ModelType, AdminSettings, Recommendation } from "../types";

// Schema for the structured output
const analysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    seoScore: { type: Type.NUMBER, description: "Score from 0-100 for SEO optimization." },
    eeatScore: { type: Type.NUMBER, description: "Score from 0-100 for E-E-A-T compliance." },
    llmOptimizationScore: { type: Type.NUMBER, description: "Score from 0-100 for how well LLMs can understand this content." },
    isYMYL: { 
        type: Type.BOOLEAN, 
        description: "STRICT: True ONLY if content is medical, financial advice, or legal advice. Marketing sites, B2B services, and general blogs are FALSE." 
    },
    summary: { type: Type.STRING, description: "A concise summary of the content." },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key strengths."
    },
    weaknesses: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key weaknesses."
    },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING, enum: ['SEO', 'EEAT', 'Content', 'Technical'] },
          priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
          action: { type: Type.STRING, description: "The concise title of the action to take." },
          description: { type: Type.STRING, description: "Detailed explanation of the issue." },
          affectedContent: { type: Type.STRING, description: "The specific quote, section, or HTML element where the error was found. If general, specify 'Page-wide'." },
          fixSteps: { 
            type: Type.ARRAY, 
            items: { type: Type.STRING }, 
            description: "An ordered list of specific, actionable steps to resolve the issue." 
          },
          expectedImpact: { type: Type.STRING, description: "The benefit of fixing this (e.g., 'Improves Keyword Ranking', 'Increases Trust')." }
        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Potential missing keywords or topics."
    },
    sentiment: { type: Type.STRING, description: "Overall tone of the content." }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations']
};

export const analyzeContent = async (
  url: string,
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY not found in environment variables");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Prepare Context from Uploaded Files
  const knowledgeBaseContext = adminSettings.instructionFiles.length > 0 
    ? `\n\nREFERENCE MATERIALS & INSTRUCTIONS:\n${adminSettings.instructionFiles.map(f => `--- FILE: ${f.name} ---\n${f.content}\n--- END FILE ---`).join('\n')}`
    : "";

  // Process Template Replacements
  let finalPrompt = adminSettings.promptTemplate;

  // Safe replacement helper
  const replace = (key: string, value: string) => {
    finalPrompt = finalPrompt.replace(new RegExp(key, 'g'), value);
  };

  replace('{{url}}', url);
  replace('{{content}}', content.slice(0, 40000)); // Increased limit slightly
  replace('{{focusArea}}', criteria.focusArea || 'General SEO & Quality');
  replace('{{strictness}}', criteria.strictness);
  replace('{{customInstructions}}', criteria.customInstructions || 'None');

  // Append knowledge base
  finalPrompt += knowledgeBaseContext;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: 0.3, 
      },
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from Gemini");

    const parsedData = JSON.parse(jsonText);

    // SORT RECOMMENDATIONS BY PRIORITY
    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };
    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => {
        return (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0);
      });
    }

    return {
      url,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    return {
      url,
      timestamp: Date.now(),
      seoScore: 0,
      eeatScore: 0,
      llmOptimizationScore: 0,
      isYMYL: false,
      summary: "Analysis Failed",
      strengths: [],
      weaknesses: [],
      recommendations: [],
      keywordGaps: [],
      sentiment: "Neutral",
      error: error.message || "An unexpected error occurred during AI analysis."
    };
  }
};

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { AnalysisResult } from "../types";

export const generatePdfReport = (result: AnalysisResult) => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // -- Colors --
  const primaryColor = [37, 99, 235]; // Blue 600
  const secondaryColor = [71, 85, 105]; // Slate 600
  const accentColor = [245, 158, 11]; // Amber 500

  // -- Helper Functions --
  const addTitle = (text: string, y: number, fontSize = 16, isBold = true) => {
    doc.setFontSize(fontSize);
    doc.setFont("helvetica", isBold ? "bold" : "normal");
    doc.setTextColor(0, 0, 0);
    doc.text(text, 14, y);
  };

  const addSectionHeader = (text: string, y: number) => {
    doc.setFillColor(241, 245, 249); // Slate 100
    doc.rect(14, y - 6, pageWidth - 28, 10, 'F');
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.text(text.toUpperCase(), 16, y);
    return y + 10;
  };

  let finalY = 20;

  // 1. Header & Title
  doc.setFontSize(22);
  doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
  doc.setFont("helvetica", "bold");
  doc.text("Content Audit Report", 14, finalY);

  finalY += 10;
  doc.setFontSize(10);
  doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
  doc.setFont("helvetica", "normal");
  doc.text(`Generated: ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString()}`, 14, finalY);

  finalY += 6;
  doc.text(`Target URL: ${result.url}`, 14, finalY);

  // 2. Score Cards (Horizontal Layout)
  finalY += 15;
  const startX = 14;
  const boxWidth = 40;
  const boxHeight = 25;
  const gap = 5;

  const drawScoreBox = (label: string, score: number, x: number) => {
    doc.setDrawColor(200, 200, 200);
    doc.setFillColor(255, 255, 255);
    doc.roundedRect(x, finalY, boxWidth, boxHeight, 2, 2, 'FD');

    doc.setFontSize(16);
    doc.setFont("helvetica", "bold");
    if(score > 80) doc.setTextColor(22, 163, 74); // Green
    else if(score > 50) doc.setTextColor(234, 88, 12); // Orange
    else doc.setTextColor(220, 38, 38); // Red

    doc.text(score.toString(), x + (boxWidth/2), finalY + 12, { align: 'center' });

    doc.setFontSize(8);
    doc.setTextColor(100, 100, 100);
    doc.text(label, x + (boxWidth/2), finalY + 20, { align: 'center' });
  };

  drawScoreBox("SEO Score", result.seoScore, startX);
  drawScoreBox("E-E-A-T Score", result.eeatScore, startX + boxWidth + gap);
  drawScoreBox("AI Readiness", result.llmOptimizationScore, startX + (boxWidth + gap) * 2);

  if (result.isYMYL) {
      doc.setFillColor(237, 233, 254); // Purple 100
      doc.setDrawColor(139, 92, 246);
      doc.roundedRect(startX + (boxWidth + gap) * 3, finalY, boxWidth, boxHeight, 2, 2, 'FD');
      doc.setTextColor(109, 40, 217);
      doc.setFontSize(10);
      doc.text("YMYL", startX + (boxWidth + gap) * 3 + (boxWidth/2), finalY + 12, { align: 'center' });
      doc.text("DETECTED", startX + (boxWidth + gap) * 3 + (boxWidth/2), finalY + 18, { align: 'center' });
  }

  finalY += boxHeight + 15;

  // 3. Executive Summary
  finalY = addSectionHeader("Executive Summary", finalY);
  doc.setFontSize(10);
  doc.setTextColor(0,0,0);
  doc.setFont("helvetica", "normal");

  const summaryLines = doc.splitTextToSize(result.summary, pageWidth - 30);
  doc.text(summaryLines, 16, finalY);
  finalY += (summaryLines.length * 5) + 10;

  // 4. Strengths & Weaknesses (Side by Side)
  const colWidth = (pageWidth - 34) / 2;
  const startY_SW = finalY;

  // Strengths
  doc.setFillColor(240, 253, 244); // Green 50
  doc.rect(14, finalY, colWidth, 8, 'F');
  doc.setFontSize(11);
  doc.setTextColor(22, 101, 52);
  doc.setFont("helvetica", "bold");
  doc.text("Top Strengths", 16, finalY + 5.5);

  doc.setFontSize(9);
  doc.setTextColor(0,0,0);
  doc.setFont("helvetica", "normal");
  let cursorY = finalY + 14;
  result.strengths.slice(0, 5).forEach(s => {
      const lines = doc.splitTextToSize(`• ${s}`, colWidth - 4);
      doc.text(lines, 16, cursorY);
      cursorY += (lines.length * 4) + 2;
  });
  const maxLeftY = cursorY;

  // Weaknesses
  cursorY = startY_SW + 14;
  doc.setFillColor(254, 242, 242); // Red 50
  doc.rect(14 + colWidth + 6, startY_SW, colWidth, 8, 'F');
  doc.setFontSize(11);
  doc.setTextColor(153, 27, 27);
  doc.setFont("helvetica", "bold");
  doc.text("Critical Weaknesses", 16 + colWidth + 6, startY_SW + 5.5);

  doc.setFontSize(9);
  doc.setTextColor(0,0,0);
  doc.setFont("helvetica", "normal");
  result.weaknesses.slice(0, 5).forEach(w => {
      const lines = doc.splitTextToSize(`• ${w}`, colWidth - 4);
      doc.text(lines, 16 + colWidth + 6, cursorY);
      cursorY += (lines.length * 4) + 2;
  });

  finalY = Math.max(maxLeftY, cursorY) + 15;

  // 5. Keyword Gaps
  if(result.keywordGaps.length > 0) {
      finalY = addSectionHeader("Keyword & Topic Gaps", finalY);
      doc.setFontSize(9);
      doc.setTextColor(71, 85, 105);
      doc.setFont("helvetica", "italic");
      const gapText = result.keywordGaps.join(", ");
      const gapLines = doc.splitTextToSize(gapText, pageWidth - 32);
      doc.text(gapLines, 16, finalY);
      finalY += (gapLines.length * 4) + 15;
  }

  // 6. Detailed Recommendations Table
  doc.addPage();
  finalY = 20;
  addSectionHeader("Detailed Action Plan", finalY);
  finalY += 5;

  const tableBody = result.recommendations.map(rec => [
      rec.priority,
      rec.category,
      rec.action,
      `ISSUE: ${rec.description}\n\nFIX: ${rec.fixSteps.join('\n')}\n\nCONTEXT: "${rec.affectedContent.substring(0, 100)}..."`,
      rec.expectedImpact
  ]);

  (autoTable as any)(doc, {
    startY: finalY,
    head: [['Priority', 'Category', 'Action Item', 'Details & Instructions', 'Impact']],
    body: tableBody,
    styles: { fontSize: 8, cellPadding: 3, overflow: 'linebreak' },
    headStyles: { fillColor: primaryColor, textColor: 255, fontStyle: 'bold' },
    columnStyles: {
        0: { cellWidth: 18, fontStyle: 'bold' }, // Priority
        1: { cellWidth: 20 }, // Category
        2: { cellWidth: 35, fontStyle: 'bold' }, // Action
        3: { cellWidth: 'auto' }, // Details
        4: { cellWidth: 30 } // Impact
    },
    didParseCell: (data: any) => {
        // Color coding for Priority
        if (data.section === 'body' && data.column.index === 0) {
            const p = data.cell.raw;
            if (p === 'High') data.cell.styles.textColor = [220, 38, 38];
            else if (p === 'Medium') data.cell.styles.textColor = [234, 88, 12];
            else data.cell.styles.textColor = [22, 163, 74];
        }
    }
  });

  // Save the PDF
  doc.save(`ContentAudit_${new Date().toISOString().slice(0,10)}.pdf`);
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AnalysisMode, AppState, ModelType, AnalysisCriteria, AnalysisResult, AdminSettings, CustomProxy } from './types';
import { scrapeUrl } from './services/scraperService';
import { analyzeContent } from './services/geminiService';
import { loadAdminSettings, saveAdminSettings } from './services/adminService';
import CriteriaSettings from './components/CriteriaSettings';
import ResultCard from './components/ResultCard';
import AdminPanel from './components/AdminPanel';
import PasswordModal from './components/PasswordModal';
import ProxyModal from './components/ProxyModal';

const INITIAL_CRITERIA: AnalysisCriteria = {
  focusArea: 'General SEO',
  strictness: 'medium',
  customInstructions: ''
};

const DEFAULT_PROMPT_TEMPLATE = `
Analyze the following web page content located at: {{url}}

Content Preview:
{{content}}

Analysis Criteria:
- Focus Area: {{focusArea}}
- Strictness Level: {{strictness}}
- User Custom Instructions: {{customInstructions}}

--- AUDIT INSTRUCTIONS ---
You are a Senior SEO Auditor and Content Strategist. Your goal is to analyze the content against high standards of Google's E-E-A-T and modern "Helpful Content" signals.
Use the following strict guidelines to evaluate the content.

1. **Authorship & E-E-A-T (Critical)**
   - Is there a real, named author? (Generic "Team" or "Staff" is a negative signal).
   - Are there clear credentials, job titles, or links to LinkedIn/Bio pages?
   - **Originality**: Does the content cite original research, first-hand data, or unique case studies? Or is it just aggregating existing info?
   - **Expertise**: Are there expert quotes? Note: Quotes in images are NOT readable by crawlers and should be flagged as an issue.

2. **Structure & Journalism Style**
   - **Inverted Pyramid**: Does it start with the "Most Important Point" or answer? Avoid academic intros that bury the lede.
   - **Headings**: Check hierarchy (H1 -> H2 -> H3). H1 must be unique. H2s should be informative (e.g., questions users ask).
   - **Sentence Structure**: One sentence = One idea. Flag long, complex sentences ("Walls of text").
   - **Formatting**: Look for tables, numbered lists, and visual breaks. (Tables increase citation rates).

3. **AI & LLM Optimization (GEO - Generative Engine Optimization)**
   - **Direct Answers**: Does the content contain concise (40-60 word) definition blocks that AI can easily extract as a featured snippet?
   - **Numeric Anchors**: Does it use specific data points (e.g., "cited 40% more often") rather than vague claims ("significant growth")?
   - **Context**: Are user pain points explicitly named and connected to the solution?

4. **Technical & UX**
   - **CTA**: Are Call-to-Actions value-led and specific? (Avoid generic "Click here").
   - **Internal Links**: Are there 2-10 relevant internal links with descriptive anchor text?
   - **External Links**: Are sources cited? (Opinions/Stats should link to sources).

--- OUTPUT REQUIREMENTS ---
Provide a JSON response with a COMPREHENSIVE list of recommendations (25-30 items).
For each recommendation:
- **Priority**: High (EEAT/Safety/Broken), Medium (Optimization), Low (Polish).
- **Action**: Short title.
- **Description**: What is wrong.
- **Affected Content**: Quote the exact text, header, or section.
- **Fix Steps**: Step-by-step instructions (e.g., "1. Change H2 to... 2. Add table comparing X and Y...").
- **Expected Impact**: Specific benefit (e.g., "Increases extraction rate by AI").

Do NOT be lenient. If the author is anonymous, flag it. If the intro is fluff, flag it. If there are no tables, flag it.
`.trim();

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    mode: AnalysisMode.SINGLE,
    urls: [],
    results: [],
    isAnalyzing: false,
    currentProgress: 0,
    progressStatus: '',
    selectedModel: ModelType.FLASH,
    criteria: INITIAL_CRITERIA,
    showAdmin: false,
    showProxy: false,
    isAdminAuthenticated: false,
    adminSettings: {
        promptTemplate: DEFAULT_PROMPT_TEMPLATE,
        instructionFiles: []
    }
  });

  const [customProxies, setCustomProxies] = useState<CustomProxy[]>([]);
  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    // Load Admin Settings
    const savedSettings = loadAdminSettings();
    if (savedSettings) {
      setState(prev => ({ ...prev, adminSettings: savedSettings }));
    }

    // Load Proxies from local storage independently (public access)
    try {
        const savedProxies = localStorage.getItem('content_audit_user_proxies');
        if (savedProxies) {
            setCustomProxies(JSON.parse(savedProxies));
        }
    } catch (e) { console.error(e); }
  }, []);

  const handleAdminClick = () => {
    if (state.isAdminAuthenticated) {
      setState(prev => ({ ...prev, showAdmin: true }));
    } else {
      setShowPasswordModal(true);
    }
  };

  const handleAuthenticated = () => {
    setState(prev => ({ ...prev, isAdminAuthenticated: true, showAdmin: true }));
    setShowPasswordModal(false);
  };

  const handleSaveSettings = (newSettings: AdminSettings) => {
    setState(prev => ({ ...prev, adminSettings: newSettings }));
    saveAdminSettings(newSettings);
  };

  const handleStopAnalysis = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
      setState(prev => ({ 
        ...prev, 
        isAnalyzing: false, 
        progressStatus: 'Analysis stopped by user.' 
      }));
    }
  }, []);

  const handleStartAnalysis = useCallback(async () => {
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
    const controller = new AbortController();
    abortControllerRef.current = controller;

    let urlsToProcess: string[] = [];

    if (state.mode === AnalysisMode.SINGLE) {
      if (!inputUrl) return;
      urlsToProcess = [inputUrl];
    } else {
      if (!bulkInput) return;
      urlsToProcess = bulkInput.split('\n').map(u => u.trim()).filter(u => u.length > 0);
    }

    if (urlsToProcess.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], 
      currentProgress: 0,
      progressStatus: 'Initializing...'
    }));

    const results: AnalysisResult[] = [];
    const total = urlsToProcess.length;

    try {
      for (let i = 0; i < total; i++) {
        if (controller.signal.aborted) break;

        const url = urlsToProcess[i];

        // Granular Progress: Start of item (10% into this item's allocation)
        const baseProgress = (i / total) * 100;
        const itemShare = 100 / total;

        setState(prev => ({ 
            ...prev, 
            currentProgress: Math.round(baseProgress + (itemShare * 0.1)),
            progressStatus: `Scraping ${url}...` 
        }));

        const scrapeResult = await scrapeUrl(
          url, 
          customProxies, 
          (status) => setState(prev => ({ ...prev, progressStatus: status })),
          controller.signal
        );

        if (controller.signal.aborted) break;

        let analysisResult: AnalysisResult;

        if (scrapeResult.success && scrapeResult.content) {
           // Granular Progress: Analysis phase (50% into this item's allocation)
           setState(prev => ({ 
               ...prev, 
               currentProgress: Math.round(baseProgress + (itemShare * 0.5)),
               progressStatus: `Auditing content with Gemini AI...` 
           }));

           analysisResult = await analyzeContent(
              url, 
              scrapeResult.content, 
              state.criteria, 
              state.selectedModel, 
              state.adminSettings
           );
        } else {
           analysisResult = {
               url,
               timestamp: Date.now(),
               seoScore: 0,
               eeatScore: 0,
               llmOptimizationScore: 0,
               isYMYL: false,
               summary: "Analysis Failed",
               strengths: [],
               weaknesses: [],
               recommendations: [],
               keywordGaps: [],
               sentiment: "N/A",
               error: scrapeResult.error || "Unknown Error: Could not access content"
           };
        }

        results.push(analysisResult);

        // Item Complete
        setState(prev => ({
          ...prev,
          results: [...results],
          currentProgress: Math.round(((i + 1) / total) * 100),
          progressStatus: i === total - 1 ? 'Finalizing...' : 'Next URL...'
        }));
      }
    } catch (err: any) {
        if (err.name !== 'AbortError') {
            console.error("Batch processing error", err);
        }
    } finally {
        if (abortControllerRef.current === controller) {
            abortControllerRef.current = null;
        }
        setState(prev => ({ 
            ...prev, 
            isAnalyzing: false, 
            progressStatus: controller.signal.aborted ? 'Stopped' : 'Complete' 
        }));
    }

  }, [state.mode, state.criteria, state.selectedModel, state.adminSettings, inputUrl, bulkInput, customProxies]);

  return (
    <div className="min-h-screen bg-gray-50 text-slate-900 flex flex-col font-inter">
      {/* Navbar */}
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto max-w-[1920px] px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16 gap-4">
            <div className="flex items-center gap-3 shrink-0">
              <div className="w-9 h-9 bg-blue-600 rounded-lg flex items-center justify-center shadow-md shadow-blue-600/20">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <span className="font-bold text-xl tracking-tight text-slate-900 hidden sm:block">ContentAudit AI</span>
              <span className="font-bold text-lg tracking-tight text-slate-900 sm:hidden">ContentAudit</span>
            </div>

            <div className="flex items-center gap-2 md:gap-4 overflow-x-auto scrollbar-hide">
               <select 
                 value={state.selectedModel}
                 onChange={(e) => setState(prev => ({ ...prev, selectedModel: e.target.value as ModelType }))}
                 className="bg-gray-50 text-xs md:text-sm border border-gray-300 text-slate-700 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm"
               >
                 <option value={ModelType.FLASH}>Gemini 2.5 Flash</option>
                 <option value={ModelType.PRO}>Gemini 3 Pro</option>
               </select>

               {/* Proxy Button (Public) */}
               <button
                  onClick={() => setState(prev => ({ ...prev, showProxy: true }))}
                  className="bg-white hover:bg-gray-50 text-slate-600 p-2 rounded-lg border border-gray-300 shadow-sm transition-all hover:shadow"
                  title="Proxy Configuration"
               >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
               </button>

               {/* Admin Button (Protected) */}
               <button
                  onClick={handleAdminClick}
                  className="bg-white hover:bg-gray-50 text-slate-600 p-2 rounded-lg border border-gray-300 shadow-sm transition-all hover:shadow"
                  title="Admin Settings"
               >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
               </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="container mx-auto max-w-[1920px] px-4 sm:px-6 lg:px-8 py-8 w-full flex-grow">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Column: Controls (Scalable width) */}
          <div className="col-span-1 lg:col-span-4 xl:col-span-3 space-y-6">

            {/* Input Section */}
            <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
              <div className="flex gap-4 mb-6 border-b border-gray-200 pb-2 overflow-x-auto scrollbar-hide">
                <button
                  onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.SINGLE }))}
                  className={`pb-2 text-sm font-semibold transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.SINGLE ? 'text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  Single URL
                  {state.mode === AnalysisMode.SINGLE && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-600 rounded-full"></span>}
                </button>
                <button
                   onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.BULK }))}
                   className={`pb-2 text-sm font-semibold transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.BULK ? 'text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  Bulk Mode
                  {state.mode === AnalysisMode.BULK && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-600 rounded-full"></span>}
                </button>
              </div>

              {state.mode === AnalysisMode.SINGLE ? (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-2">Target URL</label>
                  <input
                    type="text"
                    placeholder="https://example.com/blog/article"
                    value={inputUrl}
                    onChange={(e) => setInputUrl(e.target.value)}
                    className="w-full bg-gray-50 border border-gray-300 rounded-lg p-3 text-slate-900 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none placeholder-gray-400 text-sm transition-all"
                  />
                </div>
              ) : (
                <div>
                   <label className="block text-sm font-medium text-slate-700 mb-2">Target URLs (One per line)</label>
                   <textarea
                     placeholder="https://site1.com&#10;https://site2.com"
                     value={bulkInput}
                     onChange={(e) => setBulkInput(e.target.value)}
                     className="w-full bg-gray-50 border border-gray-300 rounded-lg p-3 text-slate-900 h-32 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none placeholder-gray-400 resize-none text-sm transition-all"
                   />
                </div>
              )}

              {state.isAnalyzing ? (
                 <button
                    onClick={handleStopAnalysis}
                    className="mt-6 w-full py-3 rounded-lg font-semibold text-white transition-all shadow-lg bg-red-600 hover:bg-red-500 hover:shadow-red-500/20 flex flex-col items-center justify-center relative overflow-hidden active:transform active:scale-95"
                 >
                     <div 
                        className="absolute top-0 left-0 h-full bg-red-500/30 transition-all duration-300 ease-out"
                        style={{ width: `${state.currentProgress}%` }}
                      ></div>
                     <span className="relative z-10 flex items-center gap-2">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        Stop Analysis
                     </span>
                     <span className="relative z-10 text-xs text-red-100 mt-1 font-medium opacity-90 animate-pulse">
                        {state.progressStatus} ({state.currentProgress}%)
                     </span>
                 </button>
              ) : (
                <button
                    onClick={handleStartAnalysis}
                    disabled={state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput}
                    className={`mt-6 w-full py-3 rounded-lg font-semibold text-white transition-all shadow-md active:transform active:scale-95 overflow-hidden relative group ${
                    (state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput)
                        ? 'bg-blue-400 cursor-not-allowed opacity-70' 
                        : 'bg-blue-600 hover:bg-blue-500 hover:shadow-blue-600/30'
                    }`}
                >
                    Start Audit
                </button>
              )}
            </div>

            {/* Criteria Panel */}
            <CriteriaSettings 
              criteria={state.criteria} 
              onChange={(newCriteria) => setState(prev => ({ ...prev, criteria: newCriteria }))} 
            />

            {/* Quick Tips */}
            <div className="bg-white p-5 rounded-xl border border-blue-100 shadow-sm hidden sm:block">
              <h4 className="text-sm font-semibold text-blue-800 mb-2 flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                Pro Tip
              </h4>
              <p className="text-xs text-slate-600 leading-relaxed">
                Use <b>Gemini 3 Pro</b> for deep YMYL (Your Money Your Life) topics to get more authoritative checks. Use <b>Flash</b> for rapid SEO audits.
              </p>
            </div>

          </div>

          {/* Right Column: Results (Scalable width) */}
          <div className="col-span-1 lg:col-span-8 xl:col-span-9">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[300px] md:min-h-[400px] border-2 border-dashed border-gray-300 rounded-xl bg-gray-50/50 p-8 text-center">
                 <div className="bg-white p-4 rounded-full shadow-sm mb-4">
                     <svg className="w-10 h-10 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                 </div>
                 <p className="text-base md:text-lg font-medium text-slate-600">Ready to analyze content</p>
                 <p className="text-sm">Enter a URL to begin the professional audit.</p>
               </div>
             ) : (
               <div className="space-y-6">
                 {state.results.map((result, index) => (
                   <ResultCard key={`${result.url}-${index}`} result={result} />
                 ))}
               </div>
             )}
          </div>

        </div>
      </main>

      {/* Admin Panel Overlay */}
      {state.showAdmin && (
        <AdminPanel 
            settings={state.adminSettings}
            onSave={handleSaveSettings}
            onClose={() => setState(prev => ({ ...prev, showAdmin: false }))}
        />
      )}

      {/* Proxy Modal Overlay (Public) */}
      {state.showProxy && (
        <ProxyModal 
            onClose={() => setState(prev => ({ ...prev, showProxy: false }))}
            onSave={(newProxies) => setCustomProxies(newProxies)}
            initialProxies={customProxies}
        />
      )}

      {/* Password Modal Overlay */}
      {showPasswordModal && (
        <PasswordModal 
            onAuthenticated={handleAuthenticated}
            onClose={() => setShowPasswordModal(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AnalysisResult, Recommendation } from '../types';
