export default ResultCard;

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { AnalysisResult } from "../types";

// --- Color Palette (Slate & Blue Modern Theme) ---
const COLORS = {
  primary: [37, 99, 235] as [number, number, number],   // Blue 600
  secondary: [71, 85, 105] as [number, number, number], // Slate 600
  textDark: [30, 41, 59] as [number, number, number],   // Slate 800
  textLight: [100, 116, 139] as [number, number, number],// Slate 500
  success: [22, 163, 74] as [number, number, number],   // Green 600
  warning: [234, 88, 12] as [number, number, number],   // Orange 600
  danger: [220, 38, 38] as [number, number, number],    // Red 600
  bgLight: [248, 250, 252] as [number, number, number], // Slate 50
  white: [255, 255, 255] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],  // Slate 200
};

export const generatePdfReport = (result: AnalysisResult) => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const margin = 20;
  let cursorY = 20;

  // --- Helpers ---

  const setFont = (type: 'heading' | 'subheading' | 'body' | 'small', weight: 'bold' | 'normal' = 'normal') => {
    if (type === 'heading') {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(24);
        doc.setTextColor(COLORS.textDark[0], COLORS.textDark[1], COLORS.textDark[2]);
    } else if (type === 'subheading') {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(14);
        doc.setTextColor(COLORS.primary[0], COLORS.primary[1], COLORS.primary[2]);
    } else if (type === 'body') {
        doc.setFont("helvetica", weight);
        doc.setFontSize(10);
        doc.setTextColor(COLORS.textDark[0], COLORS.textDark[1], COLORS.textDark[2]);
    } else if (type === 'small') {
        doc.setFont("helvetica", weight);
        doc.setFontSize(8);
        doc.setTextColor(COLORS.textLight[0], COLORS.textLight[1], COLORS.textLight[2]);
    }
  };

  const drawBadge = (text: string, x: number, y: number, color: [number, number, number]) => {
    doc.setFontSize(8);
    doc.setFont("helvetica", "bold");
    const textWidth = doc.getTextWidth(text) + 6;
    const textHeight = 6;

    // Background Pill
    doc.setFillColor(color[0], color[1], color[2]);
    doc.setDrawColor(color[0], color[1], color[2]);
    doc.roundedRect(x, y - 4, textWidth, textHeight, 2, 2, 'F');

    // Text
    doc.setTextColor(255, 255, 255);
    doc.text(text, x + 3, y);
  };

  const drawCard = (x: number, y: number, w: number, h: number) => {
    doc.setFillColor(COLORS.white[0], COLORS.white[1], COLORS.white[2]);
    doc.setDrawColor(COLORS.border[0], COLORS.border[1], COLORS.border[2]);
    doc.roundedRect(x, y, w, h, 3, 3, 'FD');
  };

  const getColorForScore = (score: number) => {
      if (score >= 80) return COLORS.success;
      if (score >= 50) return COLORS.warning;
      return COLORS.danger;
  };

  // --- PAGE 1: DASHBOARD ---

  // 1. Top Brand Bar
  doc.setFillColor(COLORS.primary[0], COLORS.primary[1], COLORS.primary[2]);
  doc.rect(0, 0, pageWidth, 5, 'F');

  // 2. Header Section
  cursorY = 25;
  setFont('small');
  doc.text(`AUDIT DATE: ${new Date().toLocaleDateString().toUpperCase()}`, margin, cursorY);
  doc.text("GENERATED BY CONTENTAUDIT AI", pageWidth - margin - doc.getTextWidth("GENERATED BY CONTENTAUDIT AI"), cursorY);

  cursorY += 10;
  setFont('heading');
  doc.text("Content Audit Report", margin, cursorY);

  cursorY += 8;
  setFont('body');
  doc.setTextColor(COLORS.textLight[0], COLORS.textLight[1], COLORS.textLight[2]);
  const urlText = doc.splitTextToSize(result.url, pageWidth - (margin * 2));
  doc.text(urlText, margin, cursorY);
  cursorY += (urlText.length * 5) + 15;

  // 3. Scores Row
  const cardWidth = (pageWidth - (margin * 2) - 10) / 3;
  const cardHeight = 35;

  const drawScoreCard = (title: string, score: number, x: number) => {
    drawCard(x, cursorY, cardWidth, cardHeight);

    // Score Title
    doc.setFontSize(9);
    doc.setTextColor(COLORS.textLight[0], COLORS.textLight[1], COLORS.textLight[2]);
    doc.setFont("helvetica", "bold");
    doc.text(title.toUpperCase(), x + 15, cursorY + 12);

    // Score Value
    const scoreColor = getColorForScore(score);
    doc.setFontSize(24);
    doc.setTextColor(scoreColor[0], scoreColor[1], scoreColor[2]);
    doc.setFont("helvetica", "bold");
    doc.text(score.toString(), x + 15, cursorY + 25);

    // Progress Bar BG
    doc.setFillColor(COLORS.bgLight[0], COLORS.bgLight[1], COLORS.bgLight[2]);
    doc.rect(x + 15, cursorY + 28, cardWidth - 30, 2, 'F');
    // Progress Bar Fill
    doc.setFillColor(scoreColor[0], scoreColor[1], scoreColor[2]);
    doc.rect(x + 15, cursorY + 28, (cardWidth - 30) * (score / 100), 2, 'F');
  };

  drawScoreCard("SEO Performance", result.seoScore, margin);
  drawScoreCard("E-E-A-T Signal", result.eeatScore, margin + cardWidth + 5);
  drawScoreCard("AI Readiness", result.llmOptimizationScore, margin + (cardWidth + 5) * 2);

  cursorY += cardHeight + 15;

  // YMYL Warning if needed
  if (result.isYMYL) {
    doc.setFillColor(254, 242, 242); // Red 50
    doc.setDrawColor(252, 165, 165); // Red 300
    doc.roundedRect(margin, cursorY, pageWidth - (margin*2), 12, 2, 2, 'FD');
    doc.setTextColor(185, 28, 28); // Red 700
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text("⚠️  YMYL CONTENT DETECTED: STRICT E-E-A-T STANDARDS APPLIED", margin + 5, cursorY + 8);
    cursorY += 20;
  }

  // 4. Executive Summary Box
  setFont('subheading');
  doc.text("EXECUTIVE SUMMARY", margin, cursorY);
  cursorY += 5;

  // Background box for summary
  doc.setFillColor(COLORS.bgLight[0], COLORS.bgLight[1], COLORS.bgLight[2]);
  doc.setDrawColor(COLORS.border[0], COLORS.border[1], COLORS.border[2]);

  // Calculate height needed
  setFont('body');
  const summaryLines = doc.splitTextToSize(result.summary, pageWidth - (margin * 2) - 10);
  const summaryHeight = (summaryLines.length * 5) + 10;

  doc.roundedRect(margin, cursorY, pageWidth - (margin * 2), summaryHeight, 2, 2, 'FD');
  doc.text(summaryLines, margin + 5, cursorY + 7);

  cursorY += summaryHeight + 15;

  // 5. Strengths & Weaknesses Grid
  const colWidth = (pageWidth - (margin * 2) - 10) / 2;
  const startGridY = cursorY;

  // Strengths Col
