  doc.roundedRect(margin, cursorY, pageWidth - (margin * 2), summaryHeight, 2, 2, 'FD');
  doc.text(summaryLines, margin + 5, cursorY + 8);

  cursorY += summaryHeight + 15;

  // 5. Strengths & Weaknesses Grid
  const colWidth = (pageWidth - (margin * 2) - 10) / 2;
  const startGridY = cursorY;

  // Strengths Col
  setFont('subheading');
  doc.setTextColor(COLORS.success[0], COLORS.success[1], COLORS.success[2]);
  doc.text("Top Strengths", margin, cursorY);
  cursorY += 8;

  setFont('body');
  result.strengths.slice(0, 5).forEach(s => {
    doc.setFillColor(COLORS.success[0], COLORS.success[1], COLORS.success[2]);
    doc.circle(margin + 2, cursorY - 1, 1.5, 'F');
