    doc.text(sLines, margin + 8, cursorY);
    cursorY += (sLines.length * 5) + 3;
  });

  // Weaknesses Col (Reset Y)
  const weakX = margin + colWidth + 10;
  let weakY = startGridY;

  setFont('subheading');
  doc.setTextColor(COLORS.danger[0], COLORS.danger[1], COLORS.danger[2]);
  doc.text("Critical Issues", weakX, weakY);
  weakY += 8;

  setFont('body');
  result.weaknesses.slice(0, 5).forEach(w => {
    doc.setFillColor(COLORS.danger[0], COLORS.danger[1], COLORS.danger[2]);
    doc.circle(weakX + 2, weakY - 1, 1.5, 'F');
    const wLines = doc.splitTextToSize(w, colWidth - 10);
    doc.text(wLines, weakX + 8, weakY);
    weakY += (wLines.length * 5) + 3;
  });

  cursorY = Math.max(cursorY, weakY) + 10;

  // 6. Keyword Gaps (Chips)
  if (result.keywordGaps.length > 0) {
      // Check if we have space, else new page
      if (cursorY + 30 > pageHeight) { doc.addPage(); cursorY = margin; }

      setFont('subheading');
      doc.text("MISSING KEYWORDS / TOPICS", margin, cursorY);
      cursorY += 8;

      let chipX = margin;
      setFont('small', 'bold');

      result.keywordGaps.forEach(k => {
          const kWidth = doc.getTextWidth(k) + 10;
          if (chipX + kWidth > pageWidth - margin) {
              chipX = margin;
              cursorY += 10;
          }

          doc.setDrawColor(COLORS.border[0], COLORS.border[1], COLORS.border[2]);
          doc.setFillColor(255, 255, 255);
          doc.roundedRect(chipX, cursorY - 6, kWidth, 8, 4, 4, 'FD');
          doc.setTextColor(COLORS.textDark[0], COLORS.textDark[1], COLORS.textDark[2]);
          doc.text(k, chipX + 5, cursorY);

          chipX += kWidth + 5;
      });
  }

  // --- PAGE 2: ACTION PLAN ---
  doc.addPage();
  cursorY = margin;

  setFont('heading');
  doc.text("Detailed Action Plan", margin, cursorY);
  cursorY += 10;

  const tableBody = result.recommendations.map(rec => [
    rec.priority,
    rec.category,
    rec.action,
    // Add bullet points to fix steps for readability
    `${rec.description}\n\nSUGGESTED FIX:\n${rec.fixSteps.map(s => `• ${s}`).join('\n')}`,
    rec.expectedImpact
  ]);

