        fillColor: COLORS.bgLight,
        textColor: COLORS.textDark,
        fontStyle: 'bold',
        lineWidth: 0,
        fontSize: 9
    },
    // Widen columns significantly due to Landscape mode
    columnStyles: {
        0: { cellWidth: 25, fontStyle: 'bold' }, // Priority
        1: { cellWidth: 30 }, // Category
        2: { cellWidth: 50, fontStyle: 'bold', textColor: COLORS.primary }, // Action
        3: { cellWidth: 'auto' }, // Main content takes remaining space (approx 100mm+)
        4: { cellWidth: 50 } // Impact
    },
    didParseCell: (data: any) => {
        // Custom styling for Priority Column
        if (data.section === 'body' && data.column.index === 0) {
            const p = data.cell.raw;
            if (p === 'High') data.cell.styles.textColor = COLORS.danger;
