          doc.setDrawColor(COLORS.border[0], COLORS.border[1], COLORS.border[2]);
          doc.setFillColor(255, 255, 255);
          doc.roundedRect(chipX, cursorY - 6, kWidth, 8, 4, 4, 'FD');
          doc.setTextColor(COLORS.textDark[0], COLORS.textDark[1], COLORS.textDark[2]);
          doc.text(k, chipX + 5, cursorY);

          chipX += kWidth + 5;
      });
  }

  // --- PAGE 2: ACTION PLAN ---
  doc.addPage();
  cursorY = margin;

  setFont('heading');
  doc.text("Detailed Action Plan", margin, cursorY);
  cursorY += 10;

  const tableBody = result.recommendations.map(rec => [
    rec.priority,
    rec.category,
    rec.action,
    // Add bullet points to fix steps for readability
    `${rec.description}\n\nSUGGESTED FIX:\n${rec.fixSteps.map(s => `• ${s}`).join('\n')}`,
    rec.expectedImpact
  ]);

  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['PRIORITY', 'CATEGORY', 'ACTION ITEM', 'DETAILS & INSTRUCTIONS', 'EXPECTED IMPACT']],
    body: tableBody,
    theme: 'grid',
    styles: {
        font: 'helvetica',
        fontSize: 10,
        cellPadding: 4, // Reduced padding to allow more content per line
        valign: 'top',
        lineColor: [230, 230, 230],
        lineWidth: 0.1,
        textColor: COLORS.textDark,
        overflow: 'linebreak'
    },
    headStyles: {
        fillColor: COLORS.bgLight,
        textColor: COLORS.textDark,
        fontStyle: 'bold',
        lineWidth: 0,
        fontSize: 10
    },
    // Widen columns significantly due to Landscape mode
    // Column 0 (Priority) widened to 32 to prevent wrapping of "PRIORITY"
    columnStyles: {
        0: { cellWidth: 32, fontStyle: 'bold' }, 
        1: { cellWidth: 30 }, 
        2: { cellWidth: 50, fontStyle: 'bold', textColor: COLORS.primary }, 
        3: { cellWidth: 'auto' }, // Main content takes remaining space
        4: { cellWidth: 45 } 
    },
    didParseCell: (data: any) => {
        // Custom styling for Priority Column
        if (data.section === 'body' && data.column.index === 0) {
            const p = data.cell.raw;
            if (p === 'High') data.cell.styles.textColor = COLORS.danger;
            else if (p === 'Medium') data.cell.styles.textColor = COLORS.warning;
            else data.cell.styles.textColor = COLORS.success;
        }
    },
    didDrawPage: (data: any) => {
        const pageCount = doc.getNumberOfPages();
        doc.setFontSize(8);
        doc.setTextColor(COLORS.textLight[0], COLORS.textLight[1], COLORS.textLight[2]);
        doc.text(`Page ${pageCount}`, pageWidth - margin, pageHeight - 10, { align: 'right' });
    }
  });

  // Save
  doc.save(`ContentAudit_${new Date().toISOString().slice(0,10)}.pdf`);
};

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { AnalysisResult } from "../types";

// --- Color Palette (Modern Corporate) ---
const COLORS = {
  primary: [37, 99, 235] as [number, number, number],   // Blue 600
  slateDark: [15, 23, 42] as [number, number, number],  // Slate 900
  slateMed: [51, 65, 85] as [number, number, number],   // Slate 700
  slateLight: [100, 116, 139] as [number, number, number], // Slate 500
  bgLight: [248, 250, 252] as [number, number, number], // Slate 50
  white: [255, 255, 255] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],
  // Priority Colors
  high: [220, 38, 38] as [number, number, number],      // Red 600
  highBg: [254, 242, 242] as [number, number, number],  // Red 50
  med: [234, 88, 12] as [number, number, number],       // Orange 600
  medBg: [255, 247, 237] as [number, number, number],   // Orange 50
  low: [22, 163, 74] as [number, number, number],       // Green 600
  lowBg: [240, 253, 244] as [number, number, number],   // Green 50
};

export const generatePdfReport = (result: AnalysisResult) => {
  // A4 Landscape: 297mm x 210mm
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const pageWidth = doc.internal.pageSize.width;
  const pageHeight = doc.internal.pageSize.height;
  const marginX = 15;
  const marginY = 15;
  let cursorY = marginY;

  // --- Helpers ---
  const setFont = (type: 'h1' | 'h2' | 'h3' | 'body' | 'small', weight: 'bold' | 'normal' = 'normal') => {
    doc.setFont("helvetica", weight);
    if (type === 'h1') {
        doc.setFontSize(22);
        doc.setTextColor(...COLORS.slateDark);
    } else if (type === 'h2') {
        doc.setFontSize(16);
        doc.setTextColor(...COLORS.primary);
    } else if (type === 'h3') {
        doc.setFontSize(12);
        doc.setTextColor(...COLORS.slateDark);
    } else if (type === 'body') {
        doc.setFontSize(10);
        doc.setTextColor(...COLORS.slateMed);
    } else if (type === 'small') {
        doc.setFontSize(8);
        doc.setTextColor(...COLORS.slateLight);
    }
  };

  const drawContainer = (x: number, y: number, w: number, h: number, fill: boolean = true) => {
    doc.setDrawColor(...COLORS.border);
    if (fill) {
        doc.setFillColor(...COLORS.white);
        doc.roundedRect(x, y, w, h, 2, 2, 'FD');
    } else {
        doc.roundedRect(x, y, w, h, 2, 2, 'S');
    }
  };

  // --- PAGE 1: EXECUTIVE DASHBOARD ---

  // 1. Header with Brand & Date
  setFont('h1', 'bold');
  doc.text("Content Audit Report", marginX, cursorY + 8);

  setFont('small');
  const dateStr = new Date().toLocaleDateString();
  doc.text(`GENERATED: ${dateStr}`, pageWidth - marginX - 25, cursorY + 8);

  // Divider
  cursorY += 15;
  doc.setDrawColor(...COLORS.border);
  doc.line(marginX, cursorY, pageWidth - marginX, cursorY);
  cursorY += 8;

  // 2. URL
  setFont('body');
  doc.setTextColor(...COLORS.slateLight);
  doc.text("Target URL:", marginX, cursorY);
  doc.setTextColor(...COLORS.primary);
  doc.text(result.url, marginX + 22, cursorY);
  cursorY += 12;

  // 3. Score Cards (3 Columns)
  const gap = 6;
  const cardW = (pageWidth - (marginX * 2) - (gap * 2)) / 3;
  const cardH = 30;

  const drawScore = (label: string, score: number, x: number) => {
      drawContainer(x, cursorY, cardW, cardH);

      // Label
      doc.setFontSize(9);
      doc.setTextColor(...COLORS.slateLight);
      doc.setFont("helvetica", "bold");
      doc.text(label.toUpperCase(), x + 6, cursorY + 8);

      // Score
      doc.setFontSize(20);
      let sc = COLORS.low;
      if (score < 50) sc = COLORS.high;
      else if (score < 80) sc = COLORS.med;

      doc.setTextColor(...sc);
      doc.text(`${score}/100`, x + 6, cursorY + 22);

      // Mini Bar
      const barW = cardW - 12;
      doc.setFillColor(...COLORS.bgLight);
      doc.rect(x + 6, cursorY + 25, barW, 2, 'F');
      doc.setFillColor(...sc);
      doc.rect(x + 6, cursorY + 25, barW * (score / 100), 2, 'F');
  };

  drawScore("SEO Performance", result.seoScore, marginX);
  drawScore("E-E-A-T Signal", result.eeatScore, marginX + cardW + gap);
  drawScore("AI Readiness", result.llmOptimizationScore, marginX + (cardW + gap) * 2);

  cursorY += cardH + 10;

  // 4. Executive Summary
  setFont('h3', 'bold');
  doc.text("Executive Summary", marginX, cursorY);
  cursorY += 5;

  setFont('body');
  const summaryLines = doc.splitTextToSize(result.summary, pageWidth - (marginX * 2));
  doc.text(summaryLines, marginX, cursorY);
  cursorY += (summaryLines.length * 5) + 8;

  // 5. Strengths & Weaknesses (2 Columns)
  const gridW = (pageWidth - (marginX * 2) - 10) / 2;
  const startY = cursorY;

  // Strengths
  drawContainer(marginX, cursorY, gridW, 50);
  setFont('h3', 'bold');
  doc.setTextColor(...COLORS.low);
  doc.text("Key Strengths", marginX + 5, cursorY + 8);

  setFont('body');
  doc.setTextColor(...COLORS.slateMed);
  let sY = cursorY + 16;
  result.strengths.slice(0, 5).forEach(s => {
      doc.setFillColor(...COLORS.low);
      doc.circle(marginX + 7, sY - 1, 1, 'F');
      doc.text(doc.splitTextToSize(s, gridW - 15), marginX + 12, sY);
      sY += 6;
  });

  // Weaknesses
  const wX = marginX + gridW + 10;
  drawContainer(wX, cursorY, gridW, 50);
  setFont('h3', 'bold');
  doc.setTextColor(...COLORS.high);
  doc.text("Critical Issues", wX + 5, cursorY + 8);

  setFont('body');
  doc.setTextColor(...COLORS.slateMed);
  let wY = cursorY + 16;
  result.weaknesses.slice(0, 5).forEach(w => {
      doc.setFillColor(...COLORS.high);
      doc.circle(wX + 7, wY - 1, 1, 'F');
      doc.text(doc.splitTextToSize(w, gridW - 15), wX + 12, wY);
      wY += 6;
  });

  // --- PAGE 2: ACTION PLAN ---
  doc.addPage();
  cursorY = marginX;

  setFont('h1', 'bold');
  doc.text("Prioritized Action Plan", marginX, cursorY);
  cursorY += 10;

  // Table Data Prep
  const tableData = result.recommendations.map(rec => [
    rec.priority.toUpperCase(),
    rec.category,
    rec.action,
    `${rec.description}\n\nFIX:\n${rec.fixSteps.map(s => `• ${s}`).join('\n')}`,
    rec.expectedImpact
  ]);

  (autoTable as any)(doc, {
    startY: cursorY,
    head: [['PRIORITY', 'CATEGORY', 'ACTION ITEM', 'DETAILS & INSTRUCTIONS', 'IMPACT']],
    body: tableData,
    theme: 'plain', // We will custom draw borders
    styles: {
        font: 'helvetica',
        fontSize: 9,
        cellPadding: 4,
        valign: 'top',
        lineColor: COLORS.border,
        lineWidth: 0.1,
        textColor: COLORS.slateMed
    },
    headStyles: {
        fillColor: COLORS.bgLight,
        textColor: COLORS.slateDark,
        fontStyle: 'bold',
        halign: 'left',
        valign: 'middle',
        fontSize: 9, // Explicit small font for header to prevent wrap
        minCellHeight: 10
    },
    columnStyles: {
        0: { cellWidth: 25, halign: 'center', valign: 'middle' }, // Priority (Badge)
        1: { cellWidth: 25, fontStyle: 'bold' },
        2: { cellWidth: 50, fontStyle: 'bold', textColor: COLORS.primary },
        3: { cellWidth: 'auto' }, // Takes remaining space
        4: { cellWidth: 40, fontSize: 8, textColor: COLORS.slateLight }
    },
    didParseCell: (data: any) => {
        // Add border to bottom of every row
        if (data.section === 'body') {
            data.cell.styles.borderBottom = { width: 0.1, color: COLORS.border };
        }
    },
    didDrawCell: (data: any) => {
        // Draw Badge for Priority Column
        if (data.section === 'body' && data.column.index === 0) {
            const priority = data.cell.raw as string;
            let bg = COLORS.bgLight;
            let text = COLORS.slateLight;

            if (priority === 'HIGH') {
                bg = COLORS.highBg;
                text = COLORS.high;
            } else if (priority === 'MEDIUM') {
                bg = COLORS.medBg;
                text = COLORS.med;
            } else if (priority === 'LOW') {
                bg = COLORS.lowBg;
                text = COLORS.low;
            }

            const { x, y, width, height } = data.cell;

            // Clear text rendered by default to avoid double draw (we draw custom)
            // autoTable doesn't have an easy "skip draw" for content only, 
            // but we can draw a rectangle OVER it if needed, or rely on a hook that replaces content.
            // Actually, simplest is to use `willDrawCell` to clear text, but `didDrawCell` is for overlay.
            // We will draw a filled rect behind the text.

            doc.setFillColor(...bg);
            doc.roundedRect(x + 2, y + 3, width - 4, 6, 2, 2, 'F');

            doc.setTextColor(...text);
            doc.setFontSize(7);
            doc.setFont("helvetica", "bold");
            doc.text(priority, x + width / 2, y + 7, { align: 'center' });

            // Mask the default text drawing which might happen after? 
            // Actually standard text is drawn in standard hook. 
            // We can effectively hide the standard text by setting text color to transparent in didParseCell? 
            // No, jspdf doesn't support transparent text easily. 
            // Hack: We change the cell text to empty string in didParseCell for col 0.
        }
    },
    willDrawCell: (data: any) => {
        // Prevent default text drawing for Priority column
        if (data.section === 'body' && data.column.index === 0) {
            data.cell.text = []; // Clear text so we can draw custom badge in didDrawCell
        }
    }
  });

  // Footer with Page Numbers
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
      doc.setPage(i);
      doc.setFontSize(8);
      doc.setTextColor(...COLORS.slateLight);
      doc.text(`Page ${i} of ${pageCount} | ContentAudit AI`, pageWidth - marginX, pageHeight - 8, { align: 'right' });
  }

  doc.save(`ContentAudit_Report.pdf`);
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AnalysisMode, AppState, ModelType, AnalysisCriteria, AnalysisResult, AdminSettings, CustomProxy } from './types';
import { scrapeUrl } from './services/scraperService';
import { analyzeContent } from './services/geminiService';
import { loadAdminSettings, saveAdminSettings } from './services/adminService';
import CriteriaSettings from './components/CriteriaSettings';
import ResultCard from './components/ResultCard';
import AdminPanel from './components/AdminPanel';
import PasswordModal from './components/PasswordModal';
import ProxyModal from './components/ProxyModal';

const INITIAL_CRITERIA: AnalysisCriteria = {
  focusArea: 'General SEO',
  strictness: 'medium',
  customInstructions: ''
};

const DEFAULT_PROMPT_TEMPLATE = `
Analyze the following web page content located at: {{url}}

Content Preview:
{{content}}

Analysis Criteria:
- Focus Area: {{focusArea}}
- Strictness Level: {{strictness}}
- User Custom Instructions: {{customInstructions}}

--- AUDIT INSTRUCTIONS ---
You are a Senior SEO Auditor and Content Strategist. Your goal is to analyze the content against high standards of Google's E-E-A-T and modern "Helpful Content" signals.
Use the following strict guidelines to evaluate the content.

1. **Authorship & E-E-A-T (Critical)**
   - Is there a real, named author? (Generic "Team" or "Staff" is a negative signal).
   - Are there clear credentials, job titles, or links to LinkedIn/Bio pages?
   - **Originality**: Does the content cite original research, first-hand data, or unique case studies? Or is it just aggregating existing info?
   - **Expertise**: Are there expert quotes? Note: Quotes in images are NOT readable by crawlers and should be flagged as an issue.

2. **Structure & Journalism Style**
   - **Inverted Pyramid**: Does it start with the "Most Important Point" or answer? Avoid academic intros that bury the lede.
   - **Headings**: Check hierarchy (H1 -> H2 -> H3). H1 must be unique. H2s should be informative (e.g., questions users ask).
   - **Sentence Structure**: One sentence = One idea. Flag long, complex sentences ("Walls of text").
   - **Formatting**: Look for tables, numbered lists, and visual breaks. (Tables increase citation rates).

3. **AI & LLM Optimization (GEO - Generative Engine Optimization)**
   - **Direct Answers**: Does the content contain concise (40-60 word) definition blocks that AI can easily extract as a featured snippet?
   - **Numeric Anchors**: Does it use specific data points (e.g., "cited 40% more often") rather than vague claims ("significant growth")?
   - **Context**: Are user pain points explicitly named and connected to the solution?

4. **Technical & UX**
   - **CTA**: Are Call-to-Actions value-led and specific? (Avoid generic "Click here").
   - **Internal Links**: Are there 2-10 relevant internal links with descriptive anchor text?
   - **External Links**: Are sources cited? (Opinions/Stats should link to sources).

--- OUTPUT REQUIREMENTS ---
Provide a JSON response with a COMPREHENSIVE list of recommendations (25-30 items).
For each recommendation:
- **Priority**: High (EEAT/Safety/Broken), Medium (Optimization), Low (Polish).
- **Action**: Short title.
- **Description**: What is wrong.
- **Affected Content**: Quote the exact text, header, or section.
- **Fix Steps**: Step-by-step instructions (e.g., "1. Change H2 to... 2. Add table comparing X and Y...").
- **Expected Impact**: Specific benefit (e.g., "Increases extraction rate by AI").

Do NOT be lenient. If the author is anonymous, flag it. If the intro is fluff, flag it. If there are no tables, flag it.
`.trim();

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    mode: AnalysisMode.SINGLE,
    urls: [],
    results: [],
    isAnalyzing: false,
    currentProgress: 0,
    progressStatus: '',
    selectedModel: ModelType.FLASH,
    criteria: INITIAL_CRITERIA,
    showAdmin: false,
    showProxy: false,
    isAdminAuthenticated: false,
    adminSettings: {
        promptTemplate: DEFAULT_PROMPT_TEMPLATE,
        instructionFiles: []
    }
  });

  const [customProxies, setCustomProxies] = useState<CustomProxy[]>([]);
  const [inputUrl, setInputUrl] = useState('');
  const [bulkInput, setBulkInput] = useState('');
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    // Load Admin Settings
    const savedSettings = loadAdminSettings();
    if (savedSettings) {
      setState(prev => ({ ...prev, adminSettings: savedSettings }));
    }

    // Load Proxies from local storage independently (public access)
    try {
        const savedProxies = localStorage.getItem('content_audit_user_proxies');
        if (savedProxies) {
            setCustomProxies(JSON.parse(savedProxies));
        }
    } catch (e) { console.error(e); }
  }, []);

  const handleAdminClick = () => {
    if (state.isAdminAuthenticated) {
      setState(prev => ({ ...prev, showAdmin: true }));
    } else {
      setShowPasswordModal(true);
    }
  };

  const handleAuthenticated = () => {
    setState(prev => ({ ...prev, isAdminAuthenticated: true, showAdmin: true }));
    setShowPasswordModal(false);
  };

  const handleSaveSettings = (newSettings: AdminSettings) => {
    setState(prev => ({ ...prev, adminSettings: newSettings }));
    saveAdminSettings(newSettings);
  };

  const handleStopAnalysis = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
      setState(prev => ({ 
        ...prev, 
        isAnalyzing: false, 
        progressStatus: 'Analysis stopped by user.' 
      }));
    }
  }, []);

  const handleStartAnalysis = useCallback(async () => {
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
    const controller = new AbortController();
    abortControllerRef.current = controller;

    let urlsToProcess: string[] = [];

    if (state.mode === AnalysisMode.SINGLE) {
      if (!inputUrl) return;
      urlsToProcess = [inputUrl];
    } else {
      if (!bulkInput) return;
      urlsToProcess = bulkInput.split('\n').map(u => u.trim()).filter(u => u.length > 0);
    }

    if (urlsToProcess.length === 0) return;

    setState(prev => ({ 
      ...prev, 
      isAnalyzing: true, 
      results: [], 
      currentProgress: 0,
      progressStatus: 'Initializing...'
    }));

    const results: AnalysisResult[] = [];
    const total = urlsToProcess.length;

    try {
      for (let i = 0; i < total; i++) {
        if (controller.signal.aborted) break;

        const url = urlsToProcess[i];

        // Granular Progress: Start of item (10% into this item's allocation)
        const baseProgress = (i / total) * 100;
        const itemShare = 100 / total;

        setState(prev => ({ 
            ...prev, 
            currentProgress: Math.round(baseProgress + (itemShare * 0.1)),
            progressStatus: `Scraping ${url}...` 
        }));

        const scrapeResult = await scrapeUrl(
          url, 
          customProxies, 
          (status) => setState(prev => ({ ...prev, progressStatus: status })),
          controller.signal
        );

        if (controller.signal.aborted) break;

        let analysisResult: AnalysisResult;

        if (scrapeResult.success && scrapeResult.content) {
           // Granular Progress: Analysis phase (50% into this item's allocation)
           setState(prev => ({ 
               ...prev, 
               currentProgress: Math.round(baseProgress + (itemShare * 0.5)),
               progressStatus: `Auditing content with Gemini AI...` 
           }));

           analysisResult = await analyzeContent(
              url, 
              scrapeResult.content, 
              state.criteria, 
              state.selectedModel, 
              state.adminSettings
           );
        } else {
           analysisResult = {
               url,
               timestamp: Date.now(),
               seoScore: 0,
               eeatScore: 0,
               llmOptimizationScore: 0,
               isYMYL: false,
               summary: "Analysis Failed",
               strengths: [],
               weaknesses: [],
               recommendations: [],
               keywordGaps: [],
               sentiment: "N/A",
               error: scrapeResult.error || "Unknown Error: Could not access content"
           };
        }

        results.push(analysisResult);

        // Item Complete
        setState(prev => ({
          ...prev,
          results: [...results],
          currentProgress: Math.round(((i + 1) / total) * 100),
          progressStatus: i === total - 1 ? 'Finalizing...' : 'Next URL...'
        }));
      }
    } catch (err: any) {
        if (err.name !== 'AbortError') {
            console.error("Batch processing error", err);
        }
    } finally {
        if (abortControllerRef.current === controller) {
            abortControllerRef.current = null;
        }
        setState(prev => ({ 
            ...prev, 
            isAnalyzing: false, 
            progressStatus: controller.signal.aborted ? 'Stopped' : 'Complete' 
        }));
    }

  }, [state.mode, state.criteria, state.selectedModel, state.adminSettings, inputUrl, bulkInput, customProxies]);

  return (
    <div className="min-h-screen bg-gray-50 text-slate-900 flex flex-col font-inter">
      {/* Navbar */}
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="container mx-auto max-w-[1920px] px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16 gap-4">
            <div className="flex items-center gap-3 shrink-0">
              <div className="w-9 h-9 bg-blue-600 rounded-lg flex items-center justify-center shadow-md shadow-blue-600/20 shrink-0">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <span className="font-bold text-xl tracking-tight text-slate-900 hidden sm:block shrink-0">ContentAudit AI</span>
              <span className="font-bold text-lg tracking-tight text-slate-900 sm:hidden shrink-0">ContentAudit</span>
            </div>

            <div className="flex items-center gap-2 md:gap-4 flex-nowrap overflow-x-auto scrollbar-hide py-1">
               <select 
                 value={state.selectedModel}
                 onChange={(e) => setState(prev => ({ ...prev, selectedModel: e.target.value as ModelType }))}
                 className="bg-gray-50 text-xs md:text-sm border border-gray-300 text-slate-700 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm shrink-0"
               >
                 <option value={ModelType.FLASH}>Gemini 2.5 Flash</option>
                 <option value={ModelType.PRO}>Gemini 3 Pro</option>
               </select>

               {/* Proxy Button (Public) */}
               <button
                  onClick={() => setState(prev => ({ ...prev, showProxy: true }))}
                  className="bg-white hover:bg-gray-50 text-slate-600 p-2 rounded-lg border border-gray-300 shadow-sm transition-all hover:shadow shrink-0"
                  title="Proxy Configuration"
               >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
               </button>

               {/* Admin Button (Protected) */}
               <button
                  onClick={handleAdminClick}
                  className="bg-white hover:bg-gray-50 text-slate-600 p-2 rounded-lg border border-gray-300 shadow-sm transition-all hover:shadow shrink-0"
                  title="Admin Settings"
               >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
               </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="container mx-auto max-w-[1920px] px-4 sm:px-6 lg:px-8 py-8 w-full flex-grow">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Column: Controls (Scalable width) */}
          <div className="col-span-1 lg:col-span-4 xl:col-span-3 space-y-6">

            {/* Input Section */}
            <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
              <div className="flex gap-4 mb-6 border-b border-gray-200 pb-2 overflow-x-auto scrollbar-hide">
                <button
                  onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.SINGLE }))}
                  className={`pb-2 text-sm font-semibold transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.SINGLE ? 'text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  Single URL
                  {state.mode === AnalysisMode.SINGLE && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-600 rounded-full"></span>}
                </button>
                <button
                   onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.BULK }))}
                   className={`pb-2 text-sm font-semibold transition-colors relative whitespace-nowrap ${state.mode === AnalysisMode.BULK ? 'text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  Bulk Mode
                  {state.mode === AnalysisMode.BULK && <span className="absolute bottom-[-9px] left-0 w-full h-0.5 bg-blue-600 rounded-full"></span>}
                </button>
              </div>

              {state.mode === AnalysisMode.SINGLE ? (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-2">Target URL</label>
                  <input
                    type="text"
                    placeholder="https://example.com/blog/article"
                    value={inputUrl}
                    onChange={(e) => setInputUrl(e.target.value)}
                    className="w-full bg-gray-50 border border-gray-300 rounded-lg p-3 text-slate-900 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none placeholder-gray-400 text-sm transition-all"
                  />
                </div>
              ) : (
                <div>
                   <label className="block text-sm font-medium text-slate-700 mb-2">Target URLs (One per line)</label>
                   <textarea
                     placeholder="https://site1.com&#10;https://site2.com"
                     value={bulkInput}
                     onChange={(e) => setBulkInput(e.target.value)}
                     className="w-full bg-gray-50 border border-gray-300 rounded-lg p-3 text-slate-900 h-32 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none placeholder-gray-400 resize-none text-sm transition-all"
                   />
                </div>
              )}

              {state.isAnalyzing ? (
                 <button
                    onClick={handleStopAnalysis}
                    className="mt-6 w-full py-3 rounded-lg font-semibold text-white transition-all shadow-lg bg-red-600 hover:bg-red-500 hover:shadow-red-500/20 flex flex-col items-center justify-center relative overflow-hidden active:transform active:scale-95"
                 >
                     <div 
                        className="absolute top-0 left-0 h-full bg-red-500/30 transition-all duration-300 ease-out"
                        style={{ width: `${state.currentProgress}%` }}
                      ></div>
                     <span className="relative z-10 flex items-center gap-2">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        Stop Analysis
                     </span>
                     <span className="relative z-10 text-xs text-red-100 mt-1 font-medium opacity-90 animate-pulse">
                        {state.progressStatus} ({state.currentProgress}%)
                     </span>
                 </button>
              ) : (
                <button
                    onClick={handleStartAnalysis}
                    disabled={state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput}
                    className={`mt-6 w-full py-3 rounded-lg font-semibold text-white transition-all shadow-md active:transform active:scale-95 overflow-hidden relative group ${
                    (state.mode === AnalysisMode.SINGLE ? !inputUrl : !bulkInput)
                        ? 'bg-blue-400 cursor-not-allowed opacity-70' 
                        : 'bg-blue-600 hover:bg-blue-500 hover:shadow-blue-600/30'
                    }`}
                >
                    Start Audit
                </button>
              )}
            </div>

            {/* Criteria Panel */}
            <CriteriaSettings 
              criteria={state.criteria} 
              onChange={(newCriteria) => setState(prev => ({ ...prev, criteria: newCriteria }))} 
            />

            {/* Quick Tips */}
            <div className="bg-white p-5 rounded-xl border border-blue-100 shadow-sm hidden sm:block">
              <h4 className="text-sm font-semibold text-blue-800 mb-2 flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                Pro Tip
              </h4>
              <p className="text-xs text-slate-600 leading-relaxed">
                Use <b>Gemini 3 Pro</b> for deep YMYL (Your Money Your Life) topics to get more authoritative checks. Use <b>Flash</b> for rapid SEO audits.
              </p>
            </div>

          </div>

          {/* Right Column: Results (Scalable width) */}
          <div className="col-span-1 lg:col-span-8 xl:col-span-9">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[300px] md:min-h-[400px] border-2 border-dashed border-gray-300 rounded-xl bg-gray-50/50 p-8 text-center">
                 <div className="bg-white p-4 rounded-full shadow-sm mb-4">
                     <svg className="w-10 h-10 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                 </div>
                 <p className="text-base md:text-lg font-medium text-slate-600">Ready to analyze content</p>
                 <p className="text-sm">Enter a URL to begin the professional audit.</p>
               </div>
             ) : (
               <div className="space-y-6">
                 {state.results.map((result, index) => (
                   <ResultCard key={`${result.url}-${index}`} result={result} />
                 ))}
               </div>
             )}
          </div>

        </div>
      </main>

      {/* Admin Panel Overlay */}
      {state.showAdmin && (
        <AdminPanel 
            settings={state.adminSettings}
            onSave={handleSaveSettings}
            onClose={() => setState(prev => ({ ...prev, showAdmin: false }))}
        />
      )}

      {/* Proxy Modal Overlay (Public) */}
      {state.showProxy && (
        <ProxyModal 
            onClose={() => setState(prev => ({ ...prev, showProxy: false }))}
            onSave={(newProxies) => setCustomProxies(newProxies)}
            initialProxies={customProxies}
        />
      )}

      {/* Password Modal Overlay */}
      {showPasswordModal && (
        <PasswordModal 
            onAuthenticated={handleAuthenticated}
            onClose={() => setShowPasswordModal(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AnalysisResult, Recommendation } from '../types';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Tooltip } from 'recharts';
import { generatePdfReport } from '../services/pdfService';

interface ResultCardProps {
  result: AnalysisResult;
}

const ScoreGauge: React.FC<{ label: string; score: number; color: string; textColor: string }> = ({ label, score, color, textColor }) => (
  <div className="flex flex-col items-center group">
    <div className={`relative w-16 h-16 md:w-20 md:h-20 flex items-center justify-center rounded-full border-[5px] ${color} bg-white shadow-sm transition-transform group-hover:scale-105`}>
      <span className={`text-xl md:text-2xl font-bold ${textColor}`}>{score}</span>
    </div>
    <span className="mt-2 text-[10px] md:text-xs text-slate-500 uppercase tracking-wider text-center font-semibold">{label}</span>
  </div>
);

const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'recommendations' | 'details'>('overview');
  const [expandedRecs, setExpandedRecs] = useState<number[]>([]);
  const [showPromptModal, setShowPromptModal] = useState(false);
  const [generatedPrompt, setGeneratedPrompt] = useState('');

  const toggleRec = (index: number) => {
    setExpandedRecs(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index]
    );
  };

  const handleGeneratePrompt = () => {
    const highPriority = result.recommendations
        .filter(r => r.priority === 'High')
        .map(r => `- FIX: ${r.action}\n  CONTEXT: ${r.affectedContent}\n  INSTRUCTION: ${r.fixSteps.join(' ')}`)
        .join('\n\n');

    const keywords = result.keywordGaps.join(', ');

    const prompt = `Act as a professional SEO copywriter and Subject Matter Expert. I need you to rewrite and optimize the content for the following page: ${result.url}

GOAL: Improve SEO Score, E-E-A-T signals, and Readability.

--- CRITICAL ISSUES TO FIX (HIGH PRIORITY) ---
${highPriority || 'No critical issues found, focus on general polish.'}

--- KEYWORDS TO INTEGRATE NATURALLY ---
${keywords || 'Keywords are well optimized.'}

--- TONE & STYLE ---
Current Sentiment: ${result.sentiment}
Desired Tone: Authoritative, Clear, Helpful, and Engaging.

--- INSTRUCTIONS ---
1. Rewrite the sections identified in "Critical Issues" to address the problems.
2. Ensure the content demonstrates Experience, Expertise, Authoritativeness, and Trustworthiness (E-E-A-T).
3. Use the missing keywords naturally within the headers or body text.
4. Output the revised content in formatted Markdown.
`;
    setGeneratedPrompt(prompt);
    setShowPromptModal(true);
  };

  const copyPrompt = () => {
      navigator.clipboard.writeText(generatedPrompt);
      alert("Prompt copied to clipboard!");
  };

  // If there is an error, render the Error View
  if (result.error) {
    return (
      <div className="bg-white rounded-xl border border-red-200 overflow-hidden shadow-sm mb-8">
        <div className="p-6 flex flex-col gap-4">
           <div className="flex items-center justify-between">
              <h2 className="text-lg md:text-xl font-bold text-slate-900 truncate max-w-2xl" title={result.url}>{result.url}</h2>
              <span className="text-xs text-slate-500">{new Date(result.timestamp).toLocaleTimeString()}</span>
           </div>

           <div className="bg-red-50 border border-red-100 rounded-lg p-6 flex items-start gap-4">
              <div className="bg-red-100 p-3 rounded-full shrink-0">
                  <svg className="w-8 h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              </div>
              <div>
                  <h3 className="text-lg font-semibold text-red-800 mb-2">Analysis Failed</h3>
                  <p className="text-slate-700">{result.error}</p>
                  <p className="text-sm text-slate-500 mt-2">The content could not be retrieved or processed. Please check if the URL is accessible or try again later.</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  // Normal View
  const chartData = [
    { subject: 'SEO', A: result.seoScore, fullMark: 100 },
    { subject: 'EEAT', A: result.eeatScore, fullMark: 100 },
    { subject: 'AI/LLM', A: result.llmOptimizationScore, fullMark: 100 },
    { subject: 'Content', A: Math.round((result.seoScore + result.eeatScore) / 2), fullMark: 100 },
    { subject: 'Trust', A: result.isYMYL ? result.eeatScore : 100, fullMark: 100 },
  ];

  const getPriorityStyles = (p: string) => {
    switch (p) {
      case 'High': return 'text-red-700 bg-red-100 border-red-200';
      case 'Medium': return 'text-amber-700 bg-amber-100 border-amber-200';
      case 'Low': return 'text-blue-700 bg-blue-100 border-blue-200';
      default: return 'text-slate-600 bg-slate-100 border-slate-200';
    }
  };

  const getColor = (score: number) => {
      if (score > 80) return { border: 'border-green-500', text: 'text-green-700' };
      if (score > 50) return { border: 'border-amber-500', text: 'text-amber-700' };
      return { border: 'border-red-500', text: 'text-red-700' };
  };

  return (
    <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm mb-8 transition-shadow hover:shadow-md">
      {/* Header */}
      <div className="p-4 md:p-6 border-b border-gray-100 flex flex-col gap-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex flex-col min-w-0">
                <h2 className="text-lg md:text-xl font-bold text-slate-900 truncate w-full" title={result.url}>{result.url}</h2>
                <div className="flex items-center gap-3 mt-1">
                    <span className="text-xs text-slate-500">{new Date(result.timestamp).toLocaleTimeString()}</span>
                    {result.isYMYL && <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-purple-100 text-purple-700 border border-purple-200 whitespace-nowrap">YMYL DETECTED</span>}
                </div>
            </div>

            <div className="flex flex-wrap gap-2 shrink-0">
                <button 
                    onClick={() => generatePdfReport(result)}
                    className="flex items-center justify-center gap-2 px-4 py-2 bg-white border border-gray-300 text-slate-700 text-sm font-semibold rounded-lg shadow-sm hover:bg-gray-50 transition-all active:scale-95 whitespace-nowrap"
                >
                    <svg className="w-4 h-4 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                    Export PDF
                </button>
                <button 
                    onClick={handleGeneratePrompt}
                    className="flex items-center justify-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-blue-600 text-white text-sm font-semibold rounded-lg shadow hover:shadow-lg transition-all active:scale-95 whitespace-nowrap"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                    Generate Fix Prompt
                </button>
            </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide border-t border-gray-50 pt-4">
            {['overview', 'recommendations', 'details'].map((tab) => (
                <button
                    key={tab}
                    onClick={() => setActiveTab(tab as any)}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-all whitespace-nowrap ${
                        activeTab === tab 
                        ? 'bg-slate-900 text-white shadow-md' 
                        : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                    }`}
                >
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                </button>
            ))}
        </div>
      </div>

      {/* Content */}
      <div className="p-4 md:p-6 bg-gray-50/30">
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              {/* Gauges */}
              <div className="flex flex-wrap justify-center sm:justify-around gap-6 bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
                <ScoreGauge label="SEO Score" score={result.seoScore} color={getColor(result.seoScore).border} textColor={getColor(result.seoScore).text} />
                <ScoreGauge label="EEAT Score" score={result.eeatScore} color={getColor(result.eeatScore).border} textColor={getColor(result.eeatScore).text} />
                <ScoreGauge label="AI Ready" score={result.llmOptimizationScore} color={getColor(result.llmOptimizationScore).border} textColor={getColor(result.llmOptimizationScore).text} />
              </div>

              <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
                <h3 className="text-lg font-bold text-slate-900 mb-2">Executive Summary</h3>
                <p className="text-slate-600 leading-relaxed text-sm md:text-base">{result.summary}</p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-green-50/50 p-5 rounded-xl border border-green-100">
                  <h4 className="font-bold text-green-700 mb-3 flex items-center gap-2">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                    Top Strengths
                  </h4>
                  <ul className="space-y-2">
                    {result.strengths.slice(0, 4).map((s, i) => (
                      <li key={i} className="text-sm text-slate-700 flex items-start gap-2">
                          <span className="mt-1.5 w-1 h-1 rounded-full bg-green-500 shrink-0"></span>
                          {s}
                      </li>
                    ))}
                  </ul>
                </div>
                <div className="bg-red-50/50 p-5 rounded-xl border border-red-100">
                  <h4 className="font-bold text-red-700 mb-3 flex items-center gap-2">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    Critical Weaknesses
                  </h4>
                  <ul className="space-y-2">
                    {result.weaknesses.slice(0, 4).map((w, i) => (
                      <li key={i} className="text-sm text-slate-700 flex items-start gap-2">
                          <span className="mt-1.5 w-1 h-1 rounded-full bg-red-500 shrink-0"></span>
                          {w}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>

            <div className="h-[300px] flex items-center justify-center bg-white rounded-xl border border-gray-100 shadow-sm p-4">
              <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="70%" data={chartData}>
                  <PolarGrid stroke="#e2e8f0" />
                  <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 11, fontWeight: 600 }} />
                  <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
                  <Radar name="Score" dataKey="A" stroke="#2563eb" fill="#3b82f6" fillOpacity={0.4} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#ffffff', borderColor: '#e2e8f0', color: '#0f172a', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  />
                </RadarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {activeTab === 'recommendations' && (
          <div className="space-y-3">
            <div className="flex justify-between items-center mb-2 px-1">
                <span className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Sorted by Priority</span>
                <span className="text-xs text-slate-400">{result.recommendations.length} issues found</span>
            </div>
            {result.recommendations.map((rec, idx) => {
              const isExpanded = expandedRecs.includes(idx);
              return (
                <div key={idx} className="bg-white rounded-lg border border-gray-200 overflow-hidden transition-all duration-200 shadow-sm hover:shadow-md">
                  {/* Accordion Header */}
                  <div 
                    onClick={() => toggleRec(idx)}
                    className="p-4 flex flex-col sm:flex-row sm:items-center gap-3 cursor-pointer hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex items-start sm:items-center gap-3 flex-grow min-w-0">
                      <div className={`shrink-0 w-20 text-center px-2 py-1 rounded-md text-[10px] font-bold border uppercase shadow-sm ${getPriorityStyles(rec.priority)}`}>
                        {rec.priority}
                      </div>
                      <div className="flex-grow min-w-0">
                         <div className="flex items-center gap-2 mb-0.5">
                            <h4 className="text-slate-900 font-bold text-sm md:text-base truncate">{rec.action}</h4>
                            <span className="text-[10px] text-slate-500 bg-gray-100 px-2 py-0.5 rounded border border-gray-200">{rec.category}</span>
                         </div>
                         <p className="text-slate-500 text-xs truncate">{rec.description}</p>
                      </div>
                    </div>
                    <div className={`shrink-0 transform transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`}>
                      <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                    </div>
                  </div>

                  {/* Accordion Body */}
                  {isExpanded && (
                    <div className="px-5 pb-5 pt-2 border-t border-gray-100 bg-gray-50/50">
                      <div className="space-y-5">

                        {/* Description */}
                        <div>
                           <p className="text-slate-700 text-sm leading-relaxed">{rec.description}</p>
                        </div>

                        {/* Affected Content */}
                        {rec.affectedContent && (
                            <div className="bg-white p-4 rounded-lg border border-red-100 shadow-sm">
                                <span className="text-xs text-red-500 font-bold uppercase tracking-wider block mb-2 flex items-center gap-1">
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                                    Problem Context
                                </span>
                                <code className="text-xs md:text-sm text-slate-600 font-mono block whitespace-pre-wrap break-words bg-red-50/30 p-2 rounded">
                                    "{rec.affectedContent}"
                                </code>
                            </div>
                        )}

                        {/* Fix Steps */}
                        {rec.fixSteps && rec.fixSteps.length > 0 && (
                            <div>
                                <span className="text-xs text-blue-600 font-bold uppercase tracking-wider block mb-2">Action Plan</span>
                                <ol className="list-decimal list-inside space-y-2 bg-white p-4 rounded-lg border border-blue-100 shadow-sm">
                                    {rec.fixSteps.map((step, i) => (
                                        <li key={i} className="text-sm text-slate-700 pl-1 marker:text-blue-500 marker:font-bold">{step}</li>
                                    ))}
                                </ol>
                            </div>
                        )}

                        {/* Impact */}
                        {rec.expectedImpact && (
                             <div className="flex items-center gap-3 bg-green-50 p-3 rounded-lg border border-green-100">
                                <svg className="w-5 h-5 text-green-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                                <div>
                                    <span className="text-xs text-green-700 font-bold uppercase tracking-wider block">Expected Impact</span>
                                    <p className="text-sm text-green-800">{rec.expectedImpact}</p>
                                </div>
                             </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
             {result.recommendations.length === 0 && (
                <div className="text-center text-slate-400 py-12">No specific recommendations generated.</div>
             )}
          </div>
        )}

        {activeTab === 'details' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
               <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                   <svg className="w-5 h-5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" /></svg>
                   Keyword Opportunities
               </h3>
               <div className="flex flex-wrap gap-2">
                 {result.keywordGaps.map((k, i) => (
                   <span key={i} className="px-3 py-1.5 bg-slate-100 text-slate-700 rounded-lg text-sm border border-slate-200 font-medium">
                     {k}
                   </span>
                 ))}
                 {result.keywordGaps.length === 0 && <span className="text-slate-400 text-sm">No specific gaps identified.</span>}
               </div>
            </div>
             <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
               <h3 className="text-lg font-bold text-slate-900 mb-4">Sentiment & Tone</h3>
               <div className="p-4 bg-slate-50 rounded-lg border border-slate-200">
                   <p className="text-slate-700 font-medium italic">"{result.sentiment}"</p>
               </div>
            </div>
          </div>
        )}
      </div>

      {/* Optimization Prompt Modal */}
      {showPromptModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
              <div className="bg-white w-full max-w-2xl rounded-xl shadow-2xl flex flex-col max-h-[90vh]">
                  <div className="p-5 border-b border-gray-200 flex justify-between items-center">
                      <h3 className="text-lg font-bold text-slate-900">AI Optimization Prompt</h3>
                      <button onClick={() => setShowPromptModal(false)} className="text-slate-400 hover:text-slate-600">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                      </button>
                  </div>
                  <div className="p-6 overflow-y-auto bg-gray-50">
                      <p className="text-sm text-slate-500 mb-4">
                          Copy this prompt and paste it into your favorite AI tool (Gemini, ChatGPT, Claude) to automatically rewrite your content with these fixes applied.
                      </p>
                      <textarea 
                        readOnly 
                        value={generatedPrompt} 
                        className="w-full h-64 p-4 text-sm font-mono text-slate-800 bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                  </div>
                  <div className="p-5 border-t border-gray-200 bg-white rounded-b-xl flex justify-end gap-3">
                      <button 
                        onClick={() => setShowPromptModal(false)} 
                        className="px-4 py-2 text-slate-600 font-medium hover:bg-gray-100 rounded-lg transition-colors"
                      >
                          Close
                      </button>
                      <button 
                        onClick={copyPrompt}
                        className="px-4 py-2 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 shadow-sm transition-colors"
                      >
                          Copy to Clipboard
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

