import React, { useState } from 'react';
import { AnalysisResult, Recommendation } from '../types';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, Tooltip } from 'recharts';
import { generatePdfReport } from '../services/pdfService';

interface ResultCardProps {
  result: AnalysisResult;
}

const ScoreGauge: React.FC<{ label: string; score: number; colorClass: string }> = ({ label, score, colorClass }) => (
  <div className="flex flex-col items-center group cursor-default">
    <div className="relative w-24 h-24 flex items-center justify-center">
      {/* Background Ring */}
      <svg className="absolute inset-0 w-full h-full transform -rotate-90" viewBox="0 0 100 100">
        <circle cx="50" cy="50" r="45" fill="none" stroke="#e2e8f0" strokeWidth="6" />
        <circle 
            cx="50" cy="50" r="45" fill="none" stroke="currentColor" strokeWidth="6" strokeDasharray="283" strokeDashoffset={283 - (283 * score / 100)}
            strokeLinecap="round"
            className={`transition-all duration-1000 ease-out ${colorClass}`}
        />
      </svg>
      <div className="flex flex-col items-center justify-center">
        <span className={`text-3xl font-bold tracking-tight ${colorClass}`}>{score}</span>
      </div>
    </div>
    <span className="mt-3 text-[11px] uppercase tracking-widest font-bold text-slate-400">{label}</span>
  </div>
);

const ResultCard: React.FC<ResultCardProps> = ({ result }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'recommendations' | 'details'>('overview');
  const [expandedRecs, setExpandedRecs] = useState<number[]>([]);
  const [showPromptModal, setShowPromptModal] = useState(false);
  const [generatedPrompt, setGeneratedPrompt] = useState('');

  const toggleRec = (index: number) => {
    setExpandedRecs(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index]
    );
  };

  const handleGeneratePrompt = () => {
    const highPriority = result.recommendations
        .filter(r => r.priority === 'High')
        .map(r => `- FIX: ${r.action}\n  CONTEXT: ${r.affectedContent}\n  INSTRUCTION: ${r.fixSteps.join(' ')}`)
        .join('\n\n');

    const keywords = result.keywordGaps.join(', ');

    const prompt = `Act as a professional SEO copywriter. Rewrite and optimize the content for: ${result.url}

GOAL: Improve SEO, E-E-A-T, and Readability.

--- CRITICAL ISSUES ---
${highPriority || 'Focus on general polish.'}

--- MISSING TOPICS ---
${keywords || 'Keywords optimized.'}

--- TONE ---
Sentiment: ${result.sentiment}
Desired: Authoritative, Clear, Helpful.

--- INSTRUCTIONS ---
1. Rewrite critical sections.
2. Ensure E-E-A-T.
3. Integrate missing keywords naturally.
4. Output Markdown.
`;
    setGeneratedPrompt(prompt);
    setShowPromptModal(true);
  };

  const copyPrompt = () => {
      navigator.clipboard.writeText(generatedPrompt);
      alert("Prompt copied!");
  };

  if (result.error) {
    return (
      <div className="bg-white rounded-2xl border border-red-100 shadow-xl shadow-red-100/50 overflow-hidden mb-8">
        <div className="p-8 flex flex-col gap-4 text-center items-center">
           <div className="w-16 h-16 bg-red-50 rounded-full flex items-center justify-center mb-2">
                <svg className="w-8 h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
           </div>
           <h3 className="text-xl font-bold text-slate-900">Analysis Failed</h3>
           <p className="text-slate-500 max-w-md">{result.error}</p>
           <p className="text-xs text-slate-400 font-mono mt-2 bg-slate-50 px-3 py-1 rounded">{result.url}</p>
        </div>
      </div>
    );
  }

  const chartData = [
    { subject: 'SEO', A: result.seoScore, fullMark: 100 },
    { subject: 'EEAT', A: result.eeatScore, fullMark: 100 },
    { subject: 'AI/LLM', A: result.llmOptimizationScore, fullMark: 100 },
    { subject: 'Content', A: Math.round((result.seoScore + result.eeatScore) / 2), fullMark: 100 },
    { subject: 'Trust', A: result.isYMYL ? result.eeatScore : 100, fullMark: 100 },
  ];

  const getColorClass = (score: number) => {
      if (score > 80) return 'text-green-500';
      if (score > 50) return 'text-amber-500';
      return 'text-red-500';
  };

  const getPriorityBadge = (p: string) => {
      const styles = {
          'High': 'bg-red-50 text-red-600 border-red-100 ring-red-500/10',
          'Medium': 'bg-amber-50 text-amber-600 border-amber-100 ring-amber-500/10',
          'Low': 'bg-blue-50 text-blue-600 border-blue-100 ring-blue-500/10',
      }[p] || 'bg-slate-50 text-slate-600';

      return <span className={`px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-wide border ring-1 ring-inset ${styles}`}>{p}</span>;
