                </div>
                <h2 className="text-xl md:text-2xl font-bold text-slate-900 truncate leading-tight" title={result.url}>{result.url}</h2>
                <a href={result.url} target="_blank" rel="noreferrer" className="text-sm text-blue-500 hover:text-blue-600 font-medium inline-flex items-center gap-1 mt-1">
                    Visit Page <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                </a>
            </div>

            <div className="flex flex-wrap gap-3 shrink-0">
                <button 
                    onClick={() => generatePdfReport(result)}
