                    <div className="shrink-0 self-center">
                        <div className={`w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center transition-transform duration-200 group-hover:bg-slate-100 ${isExpanded ? 'rotate-180 bg-blue-50 text-blue-600' : 'text-slate-400'}`}>
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                        </div>
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="px-5 pb-6 sm:pl-20 sm:pr-8">
                        <div className="pt-4 border-t border-slate-50 space-y-5 animate-in slide-in-from-top-2 duration-200">

                             <p className="text-slate-700 text-sm leading-relaxed">{rec.description}</p>

                             {rec.affectedContent && (
                                <div className="bg-red-50/50 p-4 rounded-xl border border-red-100/50">
                                    <span className="text-[10px] text-red-400 font-bold uppercase tracking-wider mb-2 block">Found In Content</span>
                                    <div className="text-xs md:text-sm text-slate-600 font-mono italic opacity-80 pl-3 border-l-2 border-red-200">
                                        "{rec.affectedContent}"
