                </button>
              )}
            </div>

            {/* Configuration Settings */}
            <CriteriaSettings 
              criteria={state.criteria} 
              onChange={(newCriteria) => setState(prev => ({ ...prev, criteria: newCriteria }))} 
            />

            {/* Quick Tips */}
            <div className="bg-gradient-to-br from-indigo-50 to-blue-50 p-6 rounded-2xl border border-blue-100/50 hidden lg:block">
              <h4 className="text-sm font-bold text-indigo-900 mb-2 flex items-center gap-2">
                <span className="flex items-center justify-center w-6 h-6 rounded-full bg-indigo-100 text-indigo-600">
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                </span>
                Pro Tip
              </h4>
              <p className="text-xs text-indigo-800/80 leading-relaxed font-medium">
                Switch to <b>Gemini 3 Pro</b> for deep YMYL topics. It performs stricter checks on medical and financial content claims.
              </p>
            </div>

          </div>

          {/* Right Column: Results */}
          <div className="col-span-1 lg:col-span-8 xl:col-span-9">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[400px] border-2 border-dashed border-slate-200 rounded-3xl bg-white/50 p-8 text-center animate-in fade-in zoom-in duration-500">
                 <div className="w-20 h-20 bg-white rounded-full shadow-xl shadow-slate-200 flex items-center justify-center mb-6">
                     <svg className="w-8 h-8 text-blue-500 opacity-80" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                 </div>
                 <h3 className="text-xl font-bold text-slate-700 mb-2">Ready to audit</h3>
                 <p className="text-slate-500 max-w-sm">Enter a URL to generate a comprehensive SEO & E-E-A-T analysis report.</p>
               </div>
             ) : (
               <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 fade-in">
                 {state.results.map((result, index) => (
                   <ResultCard key={`${result.url}-${index}`} result={result} />
                 ))}
                 {/* Spacer for bottom scrolling */}
                 <div className="h-10"></div>
               </div>
             )}
          </div>

        </div>
      </main>

      {/* Footer Banner */}
      <div className="fixed bottom-0 left-0 w-full bg-slate-900 text-slate-300 text-[10px] md:text-xs py-2 px-4 z-50 flex items-center justify-between border-t border-slate-700">
          <span>// work in progress for fixes & suggestions contact Antako</span>
          <a href="https://t.me/antako_np" target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 hover:text-white transition-colors">
             <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
             t.me/antako_np
          </a>
      </div>

      {/* Overlays */}
      {state.showAdmin && (
        <AdminPanel 
            settings={state.adminSettings}
            onSave={handleSaveSettings}
            onClose={() => setState(prev => ({ ...prev, showAdmin: false }))}
        />
      )}

      {state.showProxy && (
        <ProxyModal 
            onClose={() => setState(prev => ({ ...prev, showProxy: false }))}
            onSave={(newProxies) => setCustomProxies(newProxies)}
            initialProxies={customProxies}
        />
      )}

      {showPasswordModal && (
        <PasswordModal 
            onAuthenticated={handleAuthenticated}
            onClose={() => setShowPasswordModal(false)}
        />
      )}
    </div>
  );
};

