export const generatePdfReport = (result: AnalysisResult) => {
  // A4 Landscape
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const pageWidth = doc.internal.pageSize.width; // 297mm
  const pageHeight = doc.internal.pageSize.height; // 210mm
  const margin = 14;
  let cursorY = margin;

  // --- Helpers ---
  const drawFooter = () => {
    const pageCount = doc.getNumberOfPages();
    for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(...COLORS.slateLight);

        // Left Side: Contact
        doc.textWithLink("// work in progress for fixes & suggestions contact Antako", margin, pageHeight - 8, { url: 'https://t.me/antako_np' });

        // Right Side: Page Number
        doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
    }
  };

  const drawContainer = (x: number, y: number, w: number, h: number, color: [number, number, number] = COLORS.white) => {
     doc.setFillColor(...color);
     doc.setDrawColor(...COLORS.border);
     doc.roundedRect(x, y, w, h, 3, 3, 'FD');
  };

  // --- PAGE 1: DASHBOARD ---

  // 1. Header
  doc.setFont("helvetica", "bold");
  doc.setFontSize(24);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Content Audit Report", margin, cursorY + 8);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(...COLORS.slateMed);
  doc.text(new Date().toLocaleDateString(), pageWidth - margin, cursorY + 8, { align: 'right' });

  cursorY += 15;

  // 2. URL & Meta
  doc.setDrawColor(...COLORS.border);
  doc.setLineWidth(0.1);
  doc.line(margin, cursorY, pageWidth - margin, cursorY);
  cursorY += 6;

  doc.setFontSize(9);
  doc.setTextColor(...COLORS.slateLight);
  doc.text("TARGET URL", margin, cursorY + 3);
  doc.setFontSize(11);
  doc.setTextColor(...COLORS.primary);
  doc.text(result.url, margin + 25, cursorY + 3);

  cursorY += 10;

  // 3. Score Overview (Using 3 distinct blocks)
  const blockGap = 5;
  const blockW = (pageWidth - (margin * 2) - (blockGap * 2)) / 3;
  const blockH = 25;

  const drawStat = (label: string, score: number, x: number) => {
      drawContainer(x, cursorY, blockW, blockH, COLORS.bgLight);

      doc.setFontSize(8);
      doc.setTextColor(...COLORS.slateMed);
      doc.setFont("helvetica", "bold");
      doc.text(label.toUpperCase(), x + 6, cursorY + 7);

      doc.setFontSize(18);
      // Color logic
      let sc = COLORS.success;
      if (score < 50) sc = COLORS.danger;
      else if (score < 80) sc = COLORS.warning;

      doc.setTextColor(...sc);
      doc.text(`${score}`, x + 6, cursorY + 18);

      doc.setFontSize(10);
      doc.setTextColor(...COLORS.slateLight);
      doc.text("/ 100", x + 16 + (score > 9 ? 10 : 5), cursorY + 18);

      // Simple bar at bottom
      doc.setFillColor(...sc);
      doc.rect(x + 6, cursorY + 21, (blockW - 12) * (score / 100), 1.5, 'F');
  };

  drawStat("SEO Health", result.seoScore, margin);
  drawStat("E-E-A-T Score", result.eeatScore, margin + blockW + blockGap);
  drawStat("AI Readiness", result.llmOptimizationScore, margin + (blockW + blockGap) * 2);

  cursorY += blockH + 10;

  // 4. Executive Summary
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin, right: margin },
      head: [['EXECUTIVE SUMMARY']],
      body: [[result.summary]],
      theme: 'plain',
      headStyles: {
          fillColor: COLORS.white,
          textColor: COLORS.secondary,
          fontSize: 11,
          fontStyle: 'bold',
          cellPadding: { top: 0, bottom: 2, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateMed,
          fontSize: 10,
          cellPadding: 0,
          lineHeight: 1.4
      },
      columnStyles: {
          0: { cellWidth: 'auto' }
      }
  });

  // Update cursor based on table end
  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // 5. Strengths & Weaknesses (Side-by-Side Tables)
  const halfPage = (pageWidth - (margin * 2)) / 2;

  const strengthsBody = result.strengths.map(s => [`• ${s}`]);
  const weaknessesBody = result.weaknesses.map(w => [`• ${w}`]);

  // Strengths Table
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin },
      tableWidth: halfPage - 4,
      head: [['KEY STRENGTHS']],
      body: strengthsBody,
      theme: 'plain',
      headStyles: {
          textColor: COLORS.success,
          fontSize: 10,
          fontStyle: 'bold',
          cellPadding: { bottom: 3, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateDark,
          fontSize: 9,
          cellPadding: { top: 1, bottom: 1, left: 2 },
          overflow: 'linebreak'
      }
  });

  // Weaknesses Table
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin + halfPage + 4 },
      tableWidth: halfPage - 4,
      head: [['CRITICAL ISSUES']],
      body: weaknessesBody,
      theme: 'plain',
      headStyles: {
          textColor: COLORS.danger,
          fontSize: 10,
          fontStyle: 'bold',
          cellPadding: { bottom: 3, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateDark,
          fontSize: 9,
          cellPadding: { top: 1, bottom: 1, left: 2 },
          overflow: 'linebreak'
      }
  });

  // --- PAGE 2: ACTION PLAN ---
  doc.addPage();
  cursorY = margin;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Optimization Action Plan", margin, cursorY + 6);
  cursorY += 15;

  const planBody = result.recommendations.map(rec => [
      rec.priority.toUpperCase(),
      rec.category,
      rec.action,
      `${rec.description}\n\nFIX:\n${rec.fixSteps.map(s => `- ${s}`).join('\n')}`,
      rec.expectedImpact
  ]);

  (autoTable as any)(doc, {
      startY: cursorY,
      head: [['PRIORITY', 'AREA', 'ACTION', 'DETAILS & INSTRUCTIONS', 'IMPACT']],
      body: planBody,
      theme: 'grid',
      styles: {
          font: 'helvetica',
          fontSize: 9,
          lineColor: COLORS.border,
          lineWidth: 0.1,
          cellPadding: 4,
          textColor: COLORS.slateMed,
          valign: 'top',
          overflow: 'linebreak'
      },
      headStyles: {
          fillColor: COLORS.bgLight,
          textColor: COLORS.slateDark,
          fontStyle: 'bold',
          lineWidth: 0.1,
          lineColor: COLORS.border,
          halign: 'left'
      },
      // ADJUSTED COLUMN WIDTHS TO FIX "PRIORIT-Y" BREAK
      columnStyles: {
          0: { cellWidth: 30, halign: 'center', fontStyle: 'bold' }, // Increased from 22 to 30
          1: { cellWidth: 25 },
          2: { cellWidth: 50, fontStyle: 'bold', textColor: COLORS.primary },
          3: { cellWidth: 'auto' }, 
          4: { cellWidth: 40, fontSize: 8 }
      },
      didParseCell: (data: any) => {
          if (data.section === 'body' && data.column.index === 0) {
              const p = data.cell.raw;
              if (p === 'HIGH') data.cell.styles.textColor = COLORS.danger;
              else if (p === 'MEDIUM') data.cell.styles.textColor = COLORS.warning;
              else data.cell.styles.textColor = COLORS.success;
          }
      }
  });

  drawFooter();
  doc.save(`AuditReport_${new Date().toISOString().slice(0,10)}.pdf`);
};

import React, { useState, useRef, useEffect } from 'react';

interface Option {
  value: string;
  label: string;
}

interface CustomSelectProps {
  label?: string;
  value: string;
  onChange: (value: string) => void;
  options: Option[];
  placeholder?: string;
  icon?: React.ReactNode;
}

const CustomSelect: React.FC<CustomSelectProps> = ({ label, value, onChange, options, placeholder, icon }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const selectedOption = options.find(opt => opt.value === value);

  return (
    <div className="relative" ref={containerRef}>
      {label && <label className="block text-xs font-semibold text-slate-500 mb-1.5 ml-1">{label}</label>}

      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className={`w-full flex items-center justify-between bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 shadow-sm transition-all duration-200 hover:border-blue-400 focus:ring-2 focus:ring-blue-100 outline-none ${isOpen ? 'border-blue-500 ring-2 ring-blue-100' : ''}`}
      >
        <div className="flex items-center gap-2 truncate">
          {icon && <span className="text-slate-400">{icon}</span>}
          <span className={`truncate ${!selectedOption ? 'text-slate-400' : ''}`}>
            {selectedOption ? selectedOption.label : placeholder || 'Select...'}
          </span>
        </div>

        <svg 
            className={`w-4 h-4 text-slate-400 transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} 
            fill="none" 
            stroke="currentColor" 
            viewBox="0 0 24 24"
        >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {isOpen && (
        <div className="absolute z-50 w-full mt-2 bg-white border border-slate-100 rounded-xl shadow-xl max-h-60 overflow-auto animate-in fade-in zoom-in-95 duration-100">
          <div className="p-1">
            {options.map((opt) => (
              <button
                key={opt.value}
                type="button"
                onClick={() => {
                  onChange(opt.value);
                  setIsOpen(false);
                }}
                className={`w-full text-left px-3 py-2.5 rounded-lg text-sm transition-colors flex items-center justify-between group ${
                  opt.value === value 
                    ? 'bg-blue-50 text-blue-700 font-medium' 
                    : 'text-slate-700 hover:bg-slate-50'
                }`}
              >
                {opt.label}
                {opt.value === value && (
                  <svg className="w-4 h-4 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                  </svg>
                )}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomSelect;

