import React, { useState, useEffect } from 'react';
import { CustomProxy } from '../types';
import CustomSelect from './CustomSelect';

interface ProxyModalProps {
  onClose: () => void;
  onSave: (proxies: CustomProxy[]) => void;
  initialProxies: CustomProxy[];
}

const STORAGE_KEY = 'content_audit_user_proxies';

const ProxyModal: React.FC<ProxyModalProps> = ({ onClose, onSave, initialProxies }) => {
  const [proxies, setProxies] = useState<CustomProxy[]>([]);

  // New Proxy Form State
  const [ip, setIp] = useState('');
  const [port, setPort] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [protocol, setProtocol] = useState<'http' | 'https'>('http');

  useEffect(() => {
    // Load from props or local storage fallback
    if (initialProxies.length > 0) {
      setProxies(initialProxies);
    } else {
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) setProxies(JSON.parse(stored));
      } catch (e) {
        console.error("Failed to load proxies", e);
      }
    }
  }, [initialProxies]);

  const saveProxies = (newProxies: CustomProxy[]) => {
    setProxies(newProxies);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newProxies));
    onSave(newProxies);
  };

  const addProxy = () => {
    if (!ip || !port) return;

    const newProxy: CustomProxy = {
      id: Math.random().toString(36).substr(2, 9),
      ip,
      port,
      username,
      password,
      protocol,
      isActive: true
    };

    saveProxies([...proxies, newProxy]);

    // Reset Form
    setIp('');
    setPort('');
    setUsername('');
    setPassword('');
  };

  const removeProxy = (id: string) => {
    saveProxies(proxies.filter(p => p.id !== id));
  };

  const toggleProxy = (id: string) => {
    saveProxies(proxies.map(p => p.id === id ? { ...p, isActive: !p.isActive } : p));
  };

  const protocolOptions = [
    { value: 'http', label: 'HTTP' },
    { value: 'https', label: 'HTTPS' },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 overflow-y-auto">
      <div className="bg-white w-full max-w-2xl rounded-xl border border-gray-200 shadow-2xl flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-white rounded-t-xl sticky top-0 z-10">
          <div>
            <h2 className="text-xl font-bold text-slate-900 flex items-center gap-2">
              <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
              Network & Proxy Configuration
            </h2>
            <p className="text-slate-500 text-sm mt-1">Configure custom proxies to bypass restrictions. Data is stored locally.</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-white">

          {/* Add Proxy Form */}
          <div className="bg-gray-50 p-5 rounded-lg border border-gray-200 shadow-sm">
             <h3 className="text-sm font-bold text-slate-900 mb-3 uppercase tracking-wide">Add New Proxy</h3>
             <div className="grid grid-cols-1 md:grid-cols-12 gap-3">
                 <div className="md:col-span-2">
                     <CustomSelect 
                        label="Protocol"
                        value={protocol}
                        onChange={(val) => setProtocol(val as any)}
                        options={protocolOptions}
                     />
                 </div>
                 <div className="md:col-span-4">
                     <label className="text-xs font-semibold text-slate-500 mb-1.5 ml-1 block">IP Address / Host</label>
                     <input 
                        type="text" 
                        value={ip}
                        onChange={e => setIp(e.target.value)}
                        placeholder="192.168.1.1"
                        className="w-full bg-white border border-gray-300 rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-1 focus:ring-green-500 shadow-sm"
                     />
                 </div>
                 <div className="md:col-span-2">
                     <label className="text-xs font-semibold text-slate-500 mb-1.5 ml-1 block">Port</label>
                     <input 
                        type="text" 
                        value={port}
                        onChange={e => setPort(e.target.value)}
                        placeholder="8080"
                        className="w-full bg-white border border-gray-300 rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-1 focus:ring-green-500 shadow-sm"
                     />
                 </div>
                 <div className="md:col-span-2">
                     <label className="text-xs font-semibold text-slate-500 mb-1.5 ml-1 block">Username</label>
                     <input 
                        type="text" 
                        value={username}
                        onChange={e => setUsername(e.target.value)}
                        placeholder="user"
                        className="w-full bg-white border border-gray-300 rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-1 focus:ring-green-500 shadow-sm"
                     />
                 </div>
                 <div className="md:col-span-2">
                     <label className="text-xs font-semibold text-slate-500 mb-1.5 ml-1 block">Password</label>
                     <input 
                        type="password" 
                        value={password}
                        onChange={e => setPassword(e.target.value)}
                        placeholder="pass"
                        className="w-full bg-white border border-gray-300 rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-1 focus:ring-green-500 shadow-sm"
                     />
                 </div>
             </div>
             <div className="mt-4 flex justify-end">
                 <button 
                    onClick={addProxy}
                    disabled={!ip || !port}
                    className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white text-sm font-medium rounded-lg shadow-sm disabled:opacity-50 transition-colors"
                 >
                    Add Proxy Config
                 </button>
             </div>
          </div>

          {/* Proxy List */}
          <div className="space-y-3">
             <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wide">Saved Proxies</h3>
             {proxies.length === 0 ? (
                 <div className="text-center py-8 text-slate-400 text-sm border-2 border-dashed border-gray-200 rounded-lg">
                     No proxies configured. The app will use default public relays.
                 </div>
             ) : (
                 proxies.map(p => (
                     <div key={p.id} className="flex items-center justify-between bg-white p-3 rounded-lg border border-gray-200 shadow-sm">
                         <div className="flex items-center gap-4">
                             <button 
                                onClick={() => toggleProxy(p.id)}
                                className={`w-4 h-4 rounded-full border ${p.isActive ? 'bg-green-500 border-green-600' : 'bg-gray-200 border-gray-300'}`}
                                title={p.isActive ? 'Active' : 'Inactive'}
                             />
                             <div className="flex flex-col">
                                 <div className="flex items-center gap-2">
                                     <span className="font-mono text-sm font-bold text-slate-800">{p.ip}:{p.port}</span>
                                     <span className="text-[10px] uppercase bg-gray-100 px-1.5 py-0.5 rounded text-slate-500 border border-gray-200">{p.protocol}</span>
                                 </div>
                                 {p.username && <span className="text-xs text-slate-500">Auth: {p.username} / ******</span>}
                             </div>
                         </div>
                         <button 
                            onClick={() => removeProxy(p.id)}
                            className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
                         >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                         </button>
                     </div>
                 ))
             )}
          </div>

        </div>

        {/* Footer */}
        <div className="p-6 border-t border-gray-200 bg-gray-50 rounded-b-xl flex justify-end sticky bottom-0 z-10">
          <button 
            onClick={onClose}
            className="px-5 py-2 bg-slate-800 hover:bg-slate-900 text-white font-medium rounded-lg shadow transition-colors"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
};

