    },
    summary: { type: Type.STRING, description: "A concise summary of the content." },
    strengths: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key strengths."
    },
    weaknesses: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of key weaknesses."
    },
    recommendations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING, enum: ['SEO', 'EEAT', 'Content', 'Technical'] },
          priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
          action: { type: Type.STRING, description: "The concise title of the action to take." },
          description: { type: Type.STRING, description: "Detailed explanation of the issue." },
          affectedContent: { type: Type.STRING, description: "The specific quote, section, or HTML element where the error was found. If general, specify 'Page-wide'." },
          fixSteps: { 
