          expectedImpact: { type: Type.STRING, description: "The benefit of fixing this (e.g., 'Improves Keyword Ranking', 'Increases Trust')." }
        },
        required: ['category', 'priority', 'action', 'description', 'affectedContent', 'fixSteps', 'expectedImpact']
      }
    },
    keywordGaps: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Potential missing keywords or topics."
    },
    sentiment: { type: Type.STRING, description: "Overall tone of the content." }
  },
  required: ['seoScore', 'eeatScore', 'llmOptimizationScore', 'isYMYL', 'summary', 'strengths', 'weaknesses', 'recommendations']
};

export const analyzeContent = async (
  url: string,
  pageTitle: string, // Accept pageTitle
  content: string,
  criteria: AnalysisCriteria,
  model: ModelType,
  adminSettings: AdminSettings
): Promise<AnalysisResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY not found in environment variables");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Prepare Context from Uploaded Files
  const knowledgeBaseContext = adminSettings.instructionFiles.length > 0 
    ? `\n\nREFERENCE MATERIALS & INSTRUCTIONS:\n${adminSettings.instructionFiles.map(f => `--- FILE: ${f.name} ---\n${f.content}\n--- END FILE ---`).join('\n')}`
    : "";

  // --- ENHANCED INSTRUCTION MAPPING ---
  // Instead of just passing "High", we pass detailed behavioral instructions
  const strictnessInstructions = {
    low: "LOW (Baseline): Be lenient. Focus only on critical technical broken elements or severe misinformation. Ignore minor style issues.",
    medium: "MEDIUM (Standard): Conduct a professional SEO audit. Balance strengths and weaknesses evenly.",
    high: "HIGH (Ruthless): Be extremely strict. Flag content thinning, lack of depth, passive voice, and minor E-E-A-T signals. Penalize generic advice heavily."
  };

  const focusInstructions = {
    'General SEO': 'General SEO: Focus on keyword usage, structure, and basic technical health.',
    'Medical/Health': 'Medical/Health (YMYL): STRICTLY check for author medical credentials, scientific citations, and medical disclaimers. Flag any unsubstantiated health claims immediately.',
    'Finance': 'Finance (YMYL): Check for financial qualifications, risk disclaimers, and data accuracy. Flag get-rich-quick sentiment.',
    'E-commerce': 'E-commerce: Focus on product descriptions, conversion optimization (CRO), trust signals, and return policies.',
    'Blog/News': 'Blog/News: Focus on editorial standards, inverted pyramid structure, hook quality, and author bio.',
    'Technical Documentation': 'Technical Docs: Focus on clarity, code snippet accuracy, and navigation structure.'
  };

  // Process Template Replacements
  let finalPrompt = adminSettings.promptTemplate;

  // Safe replacement helper
  const replace = (key: string, value: string) => {
    finalPrompt = finalPrompt.replace(new RegExp(key, 'g'), value);
  };

  replace('{{url}}', url);
  replace('{{content}}', content.slice(0, 45000)); // Increased limit

  // Inject the DETAILED instructions
  replace('{{focusArea}}', focusInstructions[criteria.focusArea as keyof typeof focusInstructions] || criteria.focusArea);
  replace('{{strictness}}', strictnessInstructions[criteria.strictness]);

  // Ensure custom instructions are prominent
  const customCtx = criteria.customInstructions 
    ? `USER CUSTOM OVERRIDE: "${criteria.customInstructions}". (Prioritize this instruction over others).` 
    : 'None';
  replace('{{customInstructions}}', customCtx);

  // Append knowledge base
  finalPrompt += knowledgeBaseContext;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
        temperature: criteria.strictness === 'high' ? 0.2 : 0.4, // Lower temperature for high strictness
      },
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("No response from Gemini");

    const parsedData = JSON.parse(jsonText);

    // SORT RECOMMENDATIONS BY PRIORITY
    const priorityOrder: Record<string, number> = { 'High': 3, 'Medium': 2, 'Low': 1 };
    if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
      parsedData.recommendations.sort((a: Recommendation, b: Recommendation) => {
        return (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0);
      });
    }

    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      ...parsedData
    };
  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    return {
      url,
      pageTitle,
      timestamp: Date.now(),
      seoScore: 0,
      eeatScore: 0,
      llmOptimizationScore: 0,
      isYMYL: false,
      summary: "Analysis Failed",
      strengths: [],
      weaknesses: [],
      recommendations: [],
      keywordGaps: [],
      sentiment: "Neutral",
      error: error.message || "An unexpected error occurred during AI analysis."
    };
  }
};

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import { AnalysisResult } from "../types";

// --- Color Palette (Modern & Minimal) ---
const COLORS = {
  primary: [59, 130, 246] as [number, number, number],    // Blue 500
  secondary: [99, 102, 241] as [number, number, number],  // Indigo 500
  slateDark: [30, 41, 59] as [number, number, number],    // Slate 800
  slateMed: [71, 85, 105] as [number, number, number],    // Slate 600
  slateLight: [148, 163, 184] as [number, number, number],// Slate 400
  bgLight: [248, 250, 252] as [number, number, number],   // Slate 50
  white: [255, 255, 255] as [number, number, number],
  border: [226, 232, 240] as [number, number, number],

  // Status Colors
  success: [16, 185, 129] as [number, number, number],
  warning: [245, 158, 11] as [number, number, number],
  danger: [239, 68, 68] as [number, number, number],
};

export const generatePdfReport = (result: AnalysisResult) => {
  // A4 Landscape
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const pageWidth = doc.internal.pageSize.width; // 297mm
  const pageHeight = doc.internal.pageSize.height; // 210mm
  const margin = 14;
  let cursorY = margin;

  // --- Helpers ---
  const drawFooter = () => {
    const pageCount = doc.getNumberOfPages();
    for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(...COLORS.slateLight);

        // Left Side: Contact
        doc.textWithLink("// work in progress for fixes & suggestions contact Antako", margin, pageHeight - 8, { url: 'https://t.me/antako_np' });

        // Right Side: Page Number
        doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
    }
  };

  const drawContainer = (x: number, y: number, w: number, h: number, color: [number, number, number] = COLORS.white) => {
     doc.setFillColor(...color);
     doc.setDrawColor(...COLORS.border);
     doc.roundedRect(x, y, w, h, 3, 3, 'FD');
  };

  // --- PAGE 1: DASHBOARD ---

  // 1. Header
  doc.setFont("helvetica", "bold");
  doc.setFontSize(24);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Content Audit Report", margin, cursorY + 8);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(...COLORS.slateMed);
  doc.text(new Date().toLocaleDateString(), pageWidth - margin, cursorY + 8, { align: 'right' });

  cursorY += 15;

  // 2. URL & Meta
  doc.setDrawColor(...COLORS.border);
  doc.setLineWidth(0.1);
  doc.line(margin, cursorY, pageWidth - margin, cursorY);
  cursorY += 6;

  doc.setFontSize(9);
  doc.setTextColor(...COLORS.slateLight);
  doc.text("TARGET URL", margin, cursorY + 3);
  doc.setFontSize(11);
  doc.setTextColor(...COLORS.primary);
  doc.text(result.url, margin + 25, cursorY + 3);

  if (result.pageTitle) {
      cursorY += 5;
      doc.setFontSize(9);
      doc.setTextColor(...COLORS.slateLight);
      doc.text("PAGE TITLE", margin, cursorY + 3);
      doc.setFontSize(10);
      doc.setTextColor(...COLORS.slateMed);
      // Truncate title if too long
      const safeTitle = result.pageTitle.length > 90 ? result.pageTitle.substring(0, 90) + '...' : result.pageTitle;
      doc.text(safeTitle, margin + 25, cursorY + 3);
  }

  cursorY += 10;

  // 3. Score Overview (Using 3 distinct blocks)
  const blockGap = 5;
  const blockW = (pageWidth - (margin * 2) - (blockGap * 2)) / 3;
  const blockH = 25;

  const drawStat = (label: string, score: number, x: number) => {
      drawContainer(x, cursorY, blockW, blockH, COLORS.bgLight);

      doc.setFontSize(8);
      doc.setTextColor(...COLORS.slateMed);
      doc.setFont("helvetica", "bold");
      doc.text(label.toUpperCase(), x + 6, cursorY + 7);

      doc.setFontSize(18);
      // Color logic
      let sc = COLORS.success;
      if (score < 50) sc = COLORS.danger;
      else if (score < 80) sc = COLORS.warning;

      doc.setTextColor(...sc);
      doc.text(`${score}`, x + 6, cursorY + 18);

      doc.setFontSize(10);
      doc.setTextColor(...COLORS.slateLight);
      doc.text("/ 100", x + 16 + (score > 9 ? 10 : 5), cursorY + 18);

      // Simple bar at bottom
      doc.setFillColor(...sc);
      doc.rect(x + 6, cursorY + 21, (blockW - 12) * (score / 100), 1.5, 'F');
  };

  drawStat("SEO Health", result.seoScore, margin);
  drawStat("E-E-A-T Score", result.eeatScore, margin + blockW + blockGap);
  drawStat("AI Readiness", result.llmOptimizationScore, margin + (blockW + blockGap) * 2);

  cursorY += blockH + 10;

  // 4. Executive Summary
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin, right: margin },
      head: [['EXECUTIVE SUMMARY']],
      body: [[result.summary]],
      theme: 'plain',
      headStyles: {
          fillColor: COLORS.white,
          textColor: COLORS.secondary,
          fontSize: 11,
          fontStyle: 'bold',
          cellPadding: { top: 0, bottom: 2, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateMed,
          fontSize: 10,
          cellPadding: 0,
          lineHeight: 1.4
      },
      columnStyles: {
          0: { cellWidth: 'auto' }
      }
  });

  // Update cursor based on table end
  cursorY = (doc as any).lastAutoTable.finalY + 10;

  // 5. Strengths & Weaknesses (Side-by-Side Tables)
  const halfPage = (pageWidth - (margin * 2)) / 2;

  const strengthsBody = result.strengths.map(s => [`• ${s}`]);
  const weaknessesBody = result.weaknesses.map(w => [`• ${w}`]);

  // Strengths Table
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin },
      tableWidth: halfPage - 4,
      head: [['KEY STRENGTHS']],
      body: strengthsBody,
      theme: 'plain',
      headStyles: {
          textColor: COLORS.success,
          fontSize: 10,
          fontStyle: 'bold',
          cellPadding: { bottom: 3, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateDark,
          fontSize: 9,
          cellPadding: { top: 1, bottom: 1, left: 2 },
          overflow: 'linebreak'
      }
  });

  // Weaknesses Table
  (autoTable as any)(doc, {
      startY: cursorY,
      margin: { left: margin + halfPage + 4 },
      tableWidth: halfPage - 4,
      head: [['CRITICAL ISSUES']],
      body: weaknessesBody,
      theme: 'plain',
      headStyles: {
          textColor: COLORS.danger,
          fontSize: 10,
          fontStyle: 'bold',
          cellPadding: { bottom: 3, left: 0 }
      },
      bodyStyles: {
          textColor: COLORS.slateDark,
          fontSize: 9,
          cellPadding: { top: 1, bottom: 1, left: 2 },
          overflow: 'linebreak'
      }
  });

  // --- PAGE 2: ACTION PLAN ---
  doc.addPage();
  cursorY = margin;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.setTextColor(...COLORS.slateDark);
  doc.text("Optimization Action Plan", margin, cursorY + 6);
  cursorY += 15;

  const planBody = result.recommendations.map(rec => [
      rec.priority.toUpperCase(),
      rec.category,
      rec.action,
      `${rec.description}\n\nFIX:\n${rec.fixSteps.map(s => `- ${s}`).join('\n')}`,
      rec.expectedImpact
  ]);

  (autoTable as any)(doc, {
      startY: cursorY,
      head: [['PRIORITY', 'AREA', 'ACTION', 'DETAILS & INSTRUCTIONS', 'IMPACT']],
      body: planBody,
      theme: 'grid',
      styles: {
          font: 'helvetica',
          fontSize: 9,
          lineColor: COLORS.border,
          lineWidth: 0.1,
          cellPadding: 4,
          textColor: COLORS.slateMed,
          valign: 'top',
          overflow: 'linebreak'
      },
      headStyles: {
          fillColor: COLORS.bgLight,
          textColor: COLORS.slateDark,
          fontStyle: 'bold',
          lineWidth: 0.1,
          lineColor: COLORS.border,
          halign: 'left'
      },
      // ADJUSTED COLUMN WIDTHS TO FIX "PRIORIT-Y" BREAK
      columnStyles: {
          0: { cellWidth: 30, halign: 'center', fontStyle: 'bold' }, // Increased from 22 to 30
          1: { cellWidth: 25 },
          2: { cellWidth: 50, fontStyle: 'bold', textColor: COLORS.primary },
          3: { cellWidth: 'auto' }, 
          4: { cellWidth: 40, fontSize: 8 }
      },
      didParseCell: (data: any) => {
          if (data.section === 'body' && data.column.index === 0) {
              const p = data.cell.raw;
              if (p === 'HIGH') data.cell.styles.textColor = COLORS.danger;
              else if (p === 'MEDIUM') data.cell.styles.textColor = COLORS.warning;
              else data.cell.styles.textColor = COLORS.success;
          }
      }
  });

  drawFooter();

  // --- NAMING LOGIC ---
  const dateStr = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
  const timeStr = new Date().toISOString().slice(11, 16).replace(':', ''); // HHmm

  let hostname = 'domain';
  try {
      hostname = new URL(result.url).hostname.replace('www.', '');
  } catch (e) {}

  const safeTitle = (result.pageTitle || 'Report').replace(/[^a-z0-9]/gi, '-').substring(0, 40);

  doc.save(`${hostname}_${safeTitle}_${dateStr}_${timeStr}.pdf`);
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
